const CROSS_SECTION_HANDLE_HIT_PX: f32 = 20.0;
const DEFAULT_STORM_MOTION_DIRECTION_DEG: f32 = 45.0;
const DEFAULT_STORM_MOTION_SPEED_KT: f32 = 35.0;
const KNOT_TO_MPS: f32 = 0.514_444;
const METERS_PER_KFT: f32 = 304.8;
const VROT_ROW_RADIUS: usize = 2;
const VROT_GATE_RADIUS: usize = 4;
const DERIVED_READOUT_FALLBACK_RADIUS: usize = 3;
const SPECULATIVE_SAMPLE_CACHE_MIN_PIXELS: u64 = 720 * 480;
const LOW_END_SPECULATIVE_SAMPLE_CACHE_MIN_RENDER_MS: f32 = 4.0;
const HIGH_END_SPECULATIVE_SAMPLE_CACHE_MIN_RENDER_MS: f32 = 0.25;
const LOW_END_SAMPLE_CACHE_BYTES: usize = 6 * 1024 * 1024;
const LOW_END_SAMPLE_CACHE_BUILD_BYTES: usize = LOW_END_SAMPLE_CACHE_BYTES * 2;
const MID_RANGE_SAMPLE_CACHE_BYTES: usize = 24 * 1024 * 1024;
const HIGH_END_SAMPLE_CACHE_BYTES: usize = 64 * 1024 * 1024;
const LOW_END_LOOP_RENDER_CACHE_BYTES: usize = 96 * 1024 * 1024;
const MID_RANGE_LOOP_RENDER_CACHE_BYTES: usize = 384 * 1024 * 1024;
const HIGH_END_LOOP_RENDER_CACHE_BYTES: usize = 512 * 1024 * 1024;
/// Per-machine FLOOR for the shared dealiased-velocity grid memo
/// ([`dealias_grid_cache`]). The ACTUAL budget scales with the user's
/// radar-history RAM budget (see [`dealias_grid_cache_budget_bytes`]); these
/// thread-derived tiers only keep a beefy machine from ever dropping below a
/// useful working set even when the history budget is set small.
///
/// A dealiased super-res velocity tilt is ~1.7 MB (measured on live PGUA: 720
/// radials × 1192 gates, 16-bit storage; F32 grids from other feeds are ~2×
/// that). The bug this fixes: the budget used to be a FIXED tier (256 MiB /
/// 1 GiB / 3 GiB) chosen by core count alone, so a machine that loaded a long
/// super-res loop (the player loads 256+ frames; ceiling 2000) into a large
/// radar-history budget still capped the grid memo at the small tier — the
/// loop tail evicted and re-ran the ~200 ms dealiaser every pass ("works then
/// re-dealiases toward the end", worst in dual-pane where two tilts compete
/// for the same tier). These grids are a few percent of the raw volumes the
/// history budget already holds (~60-100 MB each), so a memo sized to a small
/// fraction of that budget holds one grid PER loaded frame PER active tilt.
const LOW_END_DEALIAS_GRID_CACHE_BYTES: usize = 256 * 1024 * 1024;
const MID_RANGE_DEALIAS_GRID_CACHE_BYTES: usize = 1024 * 1024 * 1024;
const HIGH_END_DEALIAS_GRID_CACHE_BYTES: usize = 3 * 1024 * 1024 * 1024;
/// Fraction (as a divisor) of the radar-history RAM budget the dealiased-grid
/// memo may use PER active dealias pane. A dealiased tilt is ~2-6% of the raw
/// volume it derives from, so one grid per history frame costs a small slice
/// of the history budget; 1/8 (12.5%) covers the worst case (F32 grids on
/// small intl volumes) with margin. The memo never actually allocates up to
/// this cap — resident bytes are bounded by the real grids (frames × tilts) —
/// so a generous cap simply guarantees the whole loaded loop stays memoized
/// instead of the tail thrashing.
const DEALIAS_GRID_BUDGET_HISTORY_DIVISOR: usize = 8;
/// Keep prewarming a sliding working set instead of eventually rasterizing the
/// entire history while playback is paused or running.
const LOOP_PREWARM_PLAYING_LOOKAHEAD_FRAMES: usize = 24;
const LOOP_PREWARM_IDLE_LOOKAHEAD_FRAMES: usize = 4;
const LOOP_PREWARM_INTERACTION_PAUSE_MS: u64 = 250;
/// While playback is waiting for the selected native-resolution texture, poll
/// the render worker promptly instead of advancing the timeline past it.
const LOOP_RENDER_WAIT_POLL_MS: u64 = 8;
const LOW_CORE_PREVIEW_THREADS: usize = 4;
const LOW_CORE_PREVIEW_RENDER_HEAD_START_MS: u64 = 8;
const INTERACTIVE_POLL_REPAINT_MS: u64 = 16;
const ACTIVE_LOAD_POLL_MS: u64 = INTERACTIVE_POLL_REPAINT_MS;
const RENDER_RESULT_POLL_MS: u64 = INTERACTIVE_POLL_REPAINT_MS;
const LOW_ZOOM_RENDER_BACKOFF_SCALE: f32 = 48.0;
const LOW_ZOOM_RENDER_BACKOFF_MIN_MS: u64 = 2_000;
const LOW_ZOOM_RENDER_BACKOFF_MIN_RENDER_MS: f32 = 80.0;
const LOW_ZOOM_REALTIME_REFRESH_SECONDS: u64 = 5;
const ALGO_FRAME_CACHE_LIMIT: usize = 96;
/// Some GPUs expose a max 2D texture dimension of 8192. GOES full-disk
/// preview frames can be 10000 px wide, so cap the player preview well
/// below the hard limit before egui uploads it.
const MAX_SAT_PLAYER_TEXTURE_DIM: usize = 4096;
/// Floor for the operator-configurable warning refresh cadence
/// (`AppSettings::warning_refresh_seconds`, default 30 s per the NWS Alerts
/// Web Service polling guidance). A custom or relayed feed (e.g. a
/// landfalling-cyclone ops relay) can poll faster than 30 s, but not so fast
/// it hammers the endpoint or starves the UI thread. Overlapping loads are
/// still blocked by `hazard_receiver.is_some()`.
const MIN_LIVE_HAZARD_REFRESH_SECONDS: u64 = 5;
const MAX_ACTIVE_ALERT_ZONE_GEOMETRIES: usize = 320;
/// Screen-pixel radius for the Shift+click "pin this station's 3h obs
/// timeline" gesture and its hover-card hint. Matches the pinned-inspector
/// release radius so the pin and release gestures share one feel.
