/// One fetched international frame: `Ok(Some)` = new (identity, volume),
/// `Ok(None)` = unchanged upstream, `Err` = catalog/download/decode error.
type IntlFrameResult = std::result::Result<Option<(String, RadarVolume)>, String>;
/// One streamed Load Loop frame (no unchanged marker — every plan in the
/// window downloads).
type IntlLoopFrameResult = std::result::Result<(String, RadarVolume), String>;
enum IntlLoopFrameMessage {
    Progress(ArchiveLoadProgress),
    Frame(IntlLoopFrameResult),
}
type IntlCoverageProbeResult = std::result::Result<IntlCoverageProbe, String>;

#[derive(Clone, Debug, Eq, PartialEq)]
struct IntlCoverageProbe {
    provider_id: String,
    provider_label: String,
    site_id: String,
    requested: usize,
    frame_count: usize,
    first_identity: Option<String>,
    latest_identity: Option<String>,
    first_part_count: usize,
    latest_part_count: usize,
    checked_at_utc: DateTime<Utc>,
    elapsed_ms: u128,
}

/// UI-side view of an international site selection (provider, site, and a
/// display label). Since the v0.29 Phase-3 pin collapse this is NOT pane
/// state — pane identity is `PaneView::pin: Option<SiteRef>` — it is the
/// label-carrying view the SITE controls build from a pin or the primary
/// poll source.
#[derive(Clone, Debug, Eq, PartialEq)]
struct PaneIntlSource {
    provider_id: String,
    site_id: String,
    label: String,
}

impl PaneIntlSource {
    fn from_site(site: &data_source::international::IntlSite) -> Self {
        Self {
            provider_id: site.provider_id.to_owned(),
            site_id: site.site_id.clone(),
            label: site.label.clone(),
        }
    }
}

struct AsyncLoadResult {
    label: String,
    update: AsyncLoadUpdate,
}

#[derive(Clone, Debug)]
struct ArchiveLoadProgress {
    label: String,
    detail: String,
    done: usize,
    total: usize,
}

impl ArchiveLoadProgress {
    fn indeterminate(label: impl Into<String>, detail: impl Into<String>) -> Self {
        Self {
            label: label.into(),
            detail: detail.into(),
            done: 0,
            total: 0,
        }
    }

    fn listing(site_id: &str, date: chrono::NaiveDate) -> Self {
        Self::indeterminate("Archive listing", format!("Listing {site_id} {date}"))
    }

    fn latest_loop_start(site_id: &str) -> Self {
        Self::indeterminate(
            format!("L2 {site_id} loop"),
            format!("Starting live loop load for {site_id}"),
        )
    }

    fn status_text(&self) -> String {
        if self.total == 0 {
            self.detail.clone()
        } else {
            format!(
                "{} {}/{} - {}",
                self.label, self.done, self.total, self.detail
            )
        }
    }

    fn fraction(&self) -> f32 {
        if self.total == 0 {
            0.0
        } else {
            (self.done as f32 / self.total as f32).clamp(0.0, 1.0)
        }
    }
}

#[derive(Clone, Debug, PartialEq)]
struct BackgroundActivity {
    label: String,
    fraction: Option<f32>,
}

impl BackgroundActivity {
    fn indeterminate(label: impl Into<String>) -> Self {
        Self {
            label: label.into(),
            fraction: None,
        }
    }

    fn progress(label: impl Into<String>, done: usize, total: usize) -> Self {
        let fraction = if total == 0 {
            None
        } else {
            Some((done as f32 / total as f32).clamp(0.0, 1.0))
        };
        Self {
            label: label.into(),
            fraction,
        }
    }
}

fn archive_load_progress_row(ui: &mut egui::Ui, progress: &ArchiveLoadProgress) {
    let status = progress.status_text();
    if progress.total == 0 {
        ui.horizontal(|ui| {
            ui.spinner();
            ui.weak(status);
        });
    } else {
        ui.add(egui::ProgressBar::new(progress.fraction()).text(status));
    }
}

/// The archive/backfill progress bar in a FIXED-height slot.
///
/// The bar/spinner only exists while a load is in flight. Drawing it
/// conditionally reflowed every control below it: a loop or preload backfill
/// finishing WHILE the user was looping or dragging the slider made the
/// "loading frames" bar vanish, shifting the whole sidebar up and causing
/// misclicks (field report, v0.28.x). This slot keeps its height whether or
/// not a load is running, so nothing below it ever moves. The bar itself is
/// unchanged (still [`archive_load_progress_row`]); only its presence is now
/// height-neutral.
fn archive_load_progress_slot(
    ui: &mut egui::Ui,
    progress: Option<&ArchiveLoadProgress>,
) -> egui::Response {
    let row_height = ui.spacing().interact_size.y;
    ui.allocate_ui_with_layout(
        egui::vec2(ui.available_width(), row_height),
        egui::Layout::top_down(egui::Align::Min),
        |ui| {
            ui.set_min_height(row_height);
            if let Some(progress) = progress {
                archive_load_progress_row(ui, progress);
            }
        },
    )
    .response
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub(crate) enum ArchiveLoopSource {
    EventPoint,
    EventTrack,
}

impl ArchiveLoopSource {
    fn progress_label(self) -> &'static str {
        match self {
            Self::EventPoint => "Event archive loop",
            Self::EventTrack => "Tornado archive loop",
        }
    }
}

/// One US Level-II archive-loop request shared by event clicks and the
/// operator Event Loop Builder. `start_utc..=end_utc` is the event's base
/// window; before/after are scan counts, not guessed wall-clock minutes.
#[derive(Clone, Debug, Eq, PartialEq)]
pub(crate) struct ArchiveLoopContext {
    pub(crate) anchor_utc: DateTime<Utc>,
    pub(crate) start_utc: DateTime<Utc>,
    pub(crate) end_utc: DateTime<Utc>,
    pub(crate) before_scans: usize,
    pub(crate) after_scans: usize,
    pub(crate) max_frames: usize,
    pub(crate) source: ArchiveLoopSource,
}

impl ArchiveLoopContext {
    pub(crate) fn event(
        start_utc: DateTime<Utc>,
        end_utc: DateTime<Utc>,
        anchor_utc: DateTime<Utc>,
        source: ArchiveLoopSource,
        settings: &settings::AppSettings,
    ) -> Self {
        let end_utc = end_utc.max(start_utc);
        Self {
            anchor_utc: anchor_utc.clamp(start_utc, end_utc),
            start_utc,
            end_utc,
            before_scans: usize::from(normalized_event_pad_frames(
                settings.effective_event_before_scans(),
            )),
            after_scans: usize::from(normalized_event_pad_frames(
                settings.effective_event_after_scans(),
            )),
            max_frames: normalized_event_max_frames(settings.event_max_frames),
            source,
        }
    }

    pub(crate) fn window_request(&self) -> data_source::Level2ArchiveWindowRequest {
        data_source::Level2ArchiveWindowRequest {
            start_utc: self.start_utc,
            end_utc: self.end_utc,
            anchor_utc: self.anchor_utc,
            pad_scans: 0,
            extra_start_scans: self.before_scans,
            extra_end_scans: self.after_scans,
            max_objects: self.max_frames.clamp(1, MAX_HISTORY_FRAME_LIMIT),
        }
    }
}

