/// Content hash of a frame history. Superseded in the summary cache key by
/// `FrameHistory::generation` (O(1) per repaint); kept for the regression
/// test pinning that a replaced volume Arc changes the signature.
#[cfg(test)]
fn frame_history_signature(frames: &[FrameHistoryEntry]) -> u64 {
    let mut hasher = DefaultHasher::new();
    frames.len().hash(&mut hasher);
    for frame in frames {
        frame.identity.site_id.hash(&mut hasher);
        frame
            .identity
            .scan_time_utc
            .timestamp_millis()
            .hash(&mut hasher);
        (Arc::as_ptr(&frame.volume) as usize).hash(&mut hasher);
    }
    hasher.finish()
}

/// Previous same-site volume used as the model-anchored (v4) velocity
/// dealiaser's temporal prior (the same selection the retired hybrid engine
/// used).  The reference is strictly older than the target scan; duplicate
/// live-partial/full objects for the same volume are not treated as a temporal
/// observation.
fn previous_dealias_reference_volume(
    frames: &[FrameHistoryEntry],
    selected_index: usize,
    current: &Arc<RadarVolume>,
) -> Option<Arc<RadarVolume>> {
    let current_ptr = Arc::as_ptr(current) as usize;
    let current_position = frames
        .iter()
        .position(|frame| Arc::as_ptr(&frame.volume) as usize == current_ptr)
        .unwrap_or_else(|| selected_index.min(frames.len()));
    frames
        .get(..current_position)?
        .iter()
        .rev()
        .find(|frame| {
            !matches!(
                frame.status,
                FrameStatus::Preview | FrameStatus::LivePartial
            ) && frame.volume.site.id.eq_ignore_ascii_case(&current.site.id)
                && frame.volume.volume_time < current.volume_time
        })
        .map(|frame| Arc::clone(&frame.volume))
}

