fn history_archive_load_parallelism() -> usize {
    history_archive_load_parallelism_for_threads(effective_worker_threads())
}

fn history_archive_load_parallelism_for_threads(threads: usize) -> usize {
    match threads {
        0..=2 => 1,
        3..=4 => 2,
        5..=7 => 3,
        _ => HISTORY_ARCHIVE_LOAD_MAX_PARALLELISM.min(threads),
    }
}

fn archive_object_scan_time_utc(object: &data_source::S3Object) -> Option<DateTime<Utc>> {
    let name = object.key.rsplit('/').next()?;
    let mut parts = name.split('_');
    let site_and_date = parts.next()?;
    let time = parts.next()?;
    if site_and_date.len() < 8 || time.len() < 6 {
        return None;
    }
    let date = &site_and_date[site_and_date.len() - 8..];
    let time = &time[..6];
    let naive = NaiveDateTime::parse_from_str(&format!("{date}{time}"), "%Y%m%d%H%M%S").ok()?;
    Some(Utc.from_utc_datetime(&naive))
}

fn archive_loop_objects_ending_at(
    objects: &[data_source::S3Object],
    target_utc: DateTime<Utc>,
    requested: usize,
) -> Vec<data_source::S3Object> {
    let requested = requested.clamp(1, MAX_HISTORY_FRAME_LIMIT);
    let timed: Vec<(DateTime<Utc>, data_source::S3Object)> = objects
        .iter()
        .filter_map(|object| Some((archive_object_scan_time_utc(object)?, object.clone())))
        .collect();
    if timed.is_empty() {
        return Vec::new();
    }
    let end = timed
        .iter()
        .rposition(|(time, _)| *time <= target_utc)
        .unwrap_or(0);
    let start = (end + 1).saturating_sub(requested);
    timed[start..=end]
        .iter()
        .map(|(_, object)| object.clone())
        .collect()
}

fn limit_archive_objects_for_event_loop(
    mut objects: Vec<(DateTime<Utc>, data_source::S3Object)>,
    max_frames: usize,
) -> Vec<(DateTime<Utc>, data_source::S3Object)> {
    objects.sort_by(|left, right| {
        left.0
            .cmp(&right.0)
            .then_with(|| left.1.key.cmp(&right.1.key))
    });
    let max_frames = max_frames.max(1);
    if objects.len() <= max_frames {
        return objects;
    }
    if max_frames == 1 {
        return objects.into_iter().rev().take(1).collect();
    }
    let last = objects.len() - 1;
    let mut selected = Vec::with_capacity(max_frames);
    let mut last_index = None;
    for slot in 0..max_frames {
        let index = slot * last / (max_frames - 1);
        if last_index != Some(index) {
            selected.push(objects[index].clone());
            last_index = Some(index);
        }
    }
    selected
}

fn archive_window_dates(start_utc: DateTime<Utc>, end_utc: DateTime<Utc>) -> Vec<NaiveDate> {
    let mut dates = Vec::new();
    let mut date = start_utc.date_naive();
    let end_date = end_utc.date_naive();
    while date <= end_date {
        dates.push(date);
        let Some(next) = date.succ_opt() else {
            break;
        };
        date = next;
    }
    dates
}

fn limit_ord_archive_plans_for_window(
    mut plans: Vec<data_source::international::OrdArchivePlan>,
    start_utc: DateTime<Utc>,
    end_utc: DateTime<Utc>,
    max_frames: usize,
) -> Vec<data_source::international::OrdArchivePlan> {
    plans.retain(|plan| plan.stamp_utc >= start_utc && plan.stamp_utc <= end_utc);
    plans.sort_by(|left, right| {
        left.stamp_utc
            .cmp(&right.stamp_utc)
            .then(left.frame.identity.cmp(&right.frame.identity))
    });
    plans.dedup_by(|left, right| left.frame.identity == right.frame.identity);
    let max_frames = max_frames.max(1);
    if plans.len() <= max_frames {
        return plans;
    }
    if max_frames == 1 {
        return plans.into_iter().rev().take(1).collect();
    }
    let last = plans.len() - 1;
    let mut selected = Vec::with_capacity(max_frames);
    let mut last_index = None;
    for slot in 0..max_frames {
        let index = slot * last / (max_frames - 1);
        if last_index != Some(index) {
            selected.push(plans[index].clone());
            last_index = Some(index);
        }
    }
    selected
}

fn send_archive_progress(
    sender: &mpsc::Sender<AsyncLoadResult>,
    label: &str,
    detail: impl Into<String>,
    done: usize,
    total: usize,
) {
    let _ = sender.send(AsyncLoadResult {
        label: label.to_owned(),
        update: AsyncLoadUpdate::ArchiveProgress(ArchiveLoadProgress {
            label: label.to_owned(),
            detail: detail.into(),
            done,
            total,
        }),
    });
}

#[allow(clippy::too_many_arguments)]
fn decode_archive_history_object(
    site_id: &str,
    object: data_source::S3Object,
    site_cache_dir: &Path,
    known_frame_paths: &BTreeSet<PathBuf>,
    archive_lookup_ms: Option<f32>,
    total_start: Instant,
    sender: &mpsc::Sender<AsyncLoadResult>,
    preview: bool,
    skip_known_frame: bool,
) -> Result<Option<DecodedLoad>, String> {
    let mut timings = LoadTimings {
        lookup_ms: archive_lookup_ms,
        lookup_cache_hit: archive_lookup_ms.map(|_| false),
        ..Default::default()
    };

    let fetch_start = Instant::now();
    let downloaded = data_source::download_object(LEVEL2_ARCHIVE_BUCKET, object, site_cache_dir)
        .map_err(|err| err.to_string())?;
    timings.fetch_ms = Some(fetch_start.elapsed().as_secs_f32() * 1000.0);
    timings.fetch_cache_hit = Some(downloaded.cache_hit);

    if skip_known_frame && downloaded.cache_hit && known_frame_paths.contains(&downloaded.path) {
        return Ok(None);
    }

    let mut decoded = decode_load_path_with_optional_preview(
        downloaded.path,
        &format!("archive L2 {site_id}"),
        total_start,
        timings,
        sender,
        preview,
        FrameStatus::Complete,
        format!("archive L2 {site_id}"),
        true,
    )?;
    decoded.status =
        archive_frame_status(decoded.volume.volume_time.with_timezone(&Utc), Utc::now());
    if global_displayable_products(&decoded.volume).is_empty() {
        return Ok(None);
    }
    Ok(Some(decoded))
}

struct ArchiveHistoryLoadContext<'a> {
    site_id: &'a str,
    progress_label: &'a str,
    site_cache_dir: &'a Path,
    known_frame_paths: &'a BTreeSet<PathBuf>,
    archive_lookup_ms: Option<f32>,
    total_start: Instant,
    sender: &'a mpsc::Sender<AsyncLoadResult>,
    progress_done_start: usize,
    progress_total: usize,
}

fn load_archive_history_objects_parallel(
    ctx: ArchiveHistoryLoadContext<'_>,
    objects: Vec<(usize, data_source::S3Object)>,
) -> (Vec<DecodedLoad>, Option<String>) {
    let parallelism = history_archive_load_parallelism();
    let total_objects = objects.len();
    let progress_total = ctx.progress_total.max(total_objects);
    let site_id = ctx.site_id;
    let progress_label = ctx.progress_label;
    let priority_count = total_objects.min(parallelism.min(3));
    let mut decoded_frames = Vec::new();
    let mut first_error = None;
    let mut offset = 0;
    let mut completed = ctx.progress_done_start.min(progress_total);

    while offset < objects.len() {
        let chunk_size = if offset == 0 && priority_count > 0 {
            priority_count
        } else {
            parallelism
        };
        let end = offset.saturating_add(chunk_size).min(objects.len());
        let chunk = &objects[offset..end];
        let batch_results = thread::scope(|scope| {
            let mut workers = Vec::with_capacity(chunk.len());
            for (index, object) in chunk.iter().cloned() {
                let site_id = site_id.to_owned();
                let site_cache_dir = ctx.site_cache_dir.to_path_buf();
                let sender = ctx.sender.clone();
                workers.push(scope.spawn(move || {
                    decode_archive_history_object(
                        &site_id,
                        object,
                        &site_cache_dir,
                        ctx.known_frame_paths,
                        (index == 0).then_some(ctx.archive_lookup_ms).flatten(),
                        ctx.total_start,
                        &sender,
                        false,
                        true,
                    )
                }));
            }

            let mut results = Vec::with_capacity(workers.len());
            for worker in workers {
                results.push(
                    worker
                        .join()
                        .map_err(|_| "archive history frame worker panicked".to_owned()),
                );
            }
            results
        });

        for result in batch_results {
            completed += 1;
            match result {
                Ok(Ok(Some(decoded))) => {
                    let _ = ctx.sender.send(AsyncLoadResult {
                        label: format!("L2 {site_id} loop frame"),
                        update: AsyncLoadUpdate::History(
                            DecodedLoadBatch {
                                frames: vec![decoded.clone()],
                                selected_index: 0,
                            },
                            false,
                        ),
                    });
                    decoded_frames.push(decoded);
                }
                Ok(Ok(None)) => {}
                Ok(Err(err)) | Err(err) => {
                    first_error.get_or_insert(err);
                }
            }
            send_archive_progress(
                ctx.sender,
                progress_label,
                "Decoded recent archive frame",
                completed,
                progress_total,
            );
        }
        offset = end;
    }

    (decoded_frames, first_error)
}

#[allow(clippy::result_large_err, clippy::too_many_arguments)]
fn spawn_latest_level2_load_worker(
    site: RadarSite,
    mode: LatestLoadMode,
    current_source_path: Option<PathBuf>,
    known_frame_paths: BTreeSet<PathBuf>,
    current_frame_identity: Option<FrameIdentity>,
    history_limit: usize,
    live_preload_frame_count: usize,
    display_live_chunk_updates: bool,
    sender: mpsc::Sender<AsyncLoadResult>,
) {
    thread::spawn(move || {
        let total_start = Instant::now();
        let site_id = site.level2_id.clone();
        let site_cache_dir = cache_dir(&site.level2_id);

        let final_update = (|| -> Result<AsyncLoadUpdate, String> {
            let history_limit = history_limit.max(1);
            let explicit_loop_load = mode == LatestLoadMode::Loop;
            let live_preload_frames =
                live_preload_frames_for_mode(mode, live_preload_frame_count, history_limit);
            let loop_progress_label = format!("L2 {site_id} loop");
            let preload_progress_label = format!("L2 {site_id} preload");
            if explicit_loop_load {
                send_archive_progress(
                    &sender,
                    &loop_progress_label,
                    "Checking current realtime scan",
                    0,
                    0,
                );
            }
            let mut decoded_frames = Vec::new();
            let mut selected_identity = if explicit_loop_load {
                current_frame_identity.filter(|identity| identity.site_id == site_id)
            } else {
                None
            };
            let mut fallback_error = None;

            let should_load_realtime = !explicit_loop_load || selected_identity.is_none();
            if should_load_realtime {
                let realtime_result = (|| -> Result<DecodedLoad, RealtimeLoadError> {
                    let mut realtime_timings = LoadTimings::default();
                    let poll_start_utc = Utc::now();
                    realtime_timings.realtime_poll_start_utc = Some(poll_start_utc);
                    let lookup_start = Instant::now();
                    let realtime = data_source::latest_realtime_level2_volume(&site.level2_id)
                        .map_err(|err| RealtimeLoadError::new(err.to_string()))?;
                    realtime_timings.lookup_ms =
                        Some(lookup_start.elapsed().as_secs_f32() * 1000.0);
                    realtime_timings.lookup_cache_hit = Some(false);
                    record_realtime_level2_metadata(&mut realtime_timings, &realtime);
                    if realtime_level2_is_stale_for_latest_load(&realtime, Utc::now()) {
                        realtime_timings.realtime_poll_end_utc = Some(Utc::now());
                        return Err(RealtimeLoadError::with_timings(
                            stale_realtime_fallback_reason(&realtime),
                            realtime_timings.finish(total_start),
                        ));
                    }

                    let fetch_start = Instant::now();
                    let downloaded =
                        data_source::download_realtime_volume(&realtime, &site_cache_dir).map_err(
                            |err| {
                                realtime_timings.realtime_poll_end_utc = Some(Utc::now());
                                RealtimeLoadError::with_timings(
                                    err.to_string(),
                                    realtime_timings.finish(total_start),
                                )
                            },
                        )?;
                    realtime_timings.fetch_ms = Some(fetch_start.elapsed().as_secs_f32() * 1000.0);
                    realtime_timings.fetch_cache_hit = Some(downloaded.cache_hit);
                    realtime_timings.realtime_assembled_size = downloaded
                        .path
                        .metadata()
                        .ok()
                        .map(|metadata| metadata.len());
                    if is_unchanged_realtime_refresh(
                        downloaded.cache_hit,
                        &downloaded.path,
                        current_source_path.as_deref(),
                    ) {
                        realtime_timings.realtime_poll_end_utc = Some(Utc::now());
                        return Err(RealtimeLoadError::with_timings(
                            "unchanged cache hit".to_owned(),
                            realtime_timings.finish(total_start),
                        ));
                    }

                    let decode_timings = realtime_timings;
                    let eager_realtime_display =
                        mode != LatestLoadMode::AutoRefresh || current_source_path.is_none();
                    let realtime_preview_enabled = should_preview_loads()
                        && eager_realtime_display
                        && display_live_chunk_updates;
                    let decoded = decode_load_path_with_optional_preview(
                        downloaded.path,
                        &format!("realtime L2 {site_id}"),
                        total_start,
                        decode_timings,
                        &sender,
                        realtime_preview_enabled,
                        if realtime.complete {
                            FrameStatus::LiveComplete
                        } else {
                            FrameStatus::LivePartial
                        },
                        format!("realtime L2 {site_id}"),
                        // Live partial volumes are re-assembled under the same
                        // on-disk path as chunks arrive, so they must never be
                        // served from the decoded-volume cache.
                        false,
                    )
                    .map_err(|err| {
                        let mut timings = decode_timings;
                        timings.realtime_poll_end_utc = Some(Utc::now());
                        RealtimeLoadError::with_timings(err, timings.finish(total_start))
                    })?;
                    if global_displayable_products(&decoded.volume).is_empty() {
                        let mut timings = decoded.timings;
                        timings.realtime_poll_end_utc = Some(Utc::now());
                        return Err(RealtimeLoadError::with_timings(
                            "realtime chunks are not displayable yet".to_owned(),
                            timings,
                        ));
                    }
                    if !realtime.complete
                        && !display_live_chunk_updates
                        && !live_partial_has_complete_low_level_tilt(&decoded.volume)
                    {
                        let mut timings = decoded.timings;
                        timings.realtime_poll_end_utc = Some(Utc::now());
                        return Err(RealtimeLoadError::with_timings(
                            "waiting for complete live low-level tilt".to_owned(),
                            timings,
                        ));
                    }
                    let mut decoded = decoded;
                    decoded.timings.realtime_poll_end_utc = Some(Utc::now());
                    Ok(decoded)
                })();
                if let Ok(decoded) = realtime_result {
                    selected_identity = Some(frame_identity_for_volume(&decoded.volume));
                    if mode != LatestLoadMode::AutoRefresh || current_source_path.is_none() {
                        let _ = sender.send(AsyncLoadResult {
                            label: format!("L2 {site_id} current"),
                            update: AsyncLoadUpdate::History(
                                DecodedLoadBatch {
                                    frames: vec![decoded.clone()],
                                    selected_index: 0,
                                },
                                true,
                            ),
                        });
                    }
                    decoded_frames.push(decoded);
                } else if let Err(err) = realtime_result {
                    if mode == LatestLoadMode::AutoRefresh
                        && current_source_path.is_some()
                        && !realtime_load_error_allows_archive_fallback(&err.reason)
                    {
                        return Ok(AsyncLoadUpdate::Unchanged {
                            timings: err.timings,
                            reason: err.reason,
                        });
                    }
                    fallback_error = Some(err.reason);
                }
            }

            if let Some(archive_limit) = archive_fetch_count_for_latest_load(
                mode,
                live_preload_frames,
                history_limit,
                !decoded_frames.is_empty(),
            ) {
                let archive_lookup_start = Instant::now();
                let mut archive_lookup_ms = None;
                if explicit_loop_load {
                    send_archive_progress(
                        &sender,
                        &loop_progress_label,
                        "Listing recent archive scans",
                        0,
                        0,
                    );
                } else if live_preload_frames > 0 {
                    send_archive_progress(
                        &sender,
                        &preload_progress_label,
                        "Listing recent history",
                        0,
                        0,
                    );
                }
                let recent_archive_objects =
                    match data_source::recent_level2_objects(&site.level2_id, 7, archive_limit) {
                        Ok(objects) => {
                            archive_lookup_ms =
                                Some(archive_lookup_start.elapsed().as_secs_f32() * 1000.0);
                            objects
                        }
                        Err(err) => {
                            fallback_error.get_or_insert_with(|| err.to_string());
                            if explicit_loop_load || live_preload_frames > 0 {
                                send_archive_progress(
                                    &sender,
                                    if explicit_loop_load {
                                        &loop_progress_label
                                    } else {
                                        &preload_progress_label
                                    },
                                    "Archive scan listing failed",
                                    0,
                                    0,
                                );
                            }
                            Vec::new()
                        }
                    };
                let recent_archive_total = recent_archive_objects.len();
                let mut archive_progress_done = 0usize;
                if (explicit_loop_load || live_preload_frames > 0) && recent_archive_total > 0 {
                    send_archive_progress(
                        &sender,
                        if explicit_loop_load {
                            &loop_progress_label
                        } else {
                            &preload_progress_label
                        },
                        if explicit_loop_load {
                            "Queued recent archive scans"
                        } else {
                            "Queued live preload frames"
                        },
                        0,
                        recent_archive_total,
                    );
                }

                let mut remaining_archive_objects = Vec::new();
                for (index, object) in recent_archive_objects.into_iter().enumerate() {
                    if selected_identity.is_none() {
                        let select_archive_frame = true;
                        let progress_detail = match decode_archive_history_object(
                            &site_id,
                            object,
                            &site_cache_dir,
                            &known_frame_paths,
                            (index == 0).then_some(archive_lookup_ms).flatten(),
                            total_start,
                            &sender,
                            should_preview_loads(),
                            true,
                        ) {
                            Ok(Some(decoded)) => {
                                selected_identity =
                                    Some(frame_identity_for_volume(&decoded.volume));
                                let _ = sender.send(AsyncLoadResult {
                                    label: format!("L2 {site_id} latest archive"),
                                    update: AsyncLoadUpdate::History(
                                        DecodedLoadBatch {
                                            frames: vec![decoded.clone()],
                                            selected_index: 0,
                                        },
                                        select_archive_frame,
                                    ),
                                });
                                decoded_frames.push(decoded);
                                "Decoded recent archive frame"
                            }
                            Ok(None) => "Skipped cached archive frame",
                            Err(err) => {
                                fallback_error.get_or_insert(err);
                                "Archive frame failed"
                            }
                        };
                        if explicit_loop_load || live_preload_frames > 0 {
                            archive_progress_done += 1;
                            send_archive_progress(
                                &sender,
                                if explicit_loop_load {
                                    &loop_progress_label
                                } else {
                                    &preload_progress_label
                                },
                                progress_detail,
                                archive_progress_done,
                                recent_archive_total,
                            );
                        }
                    } else if explicit_loop_load || live_preload_frames > 0 {
                        remaining_archive_objects.push((index, object));
                    } else {
                        break;
                    }
                }

                if (explicit_loop_load || live_preload_frames > 0)
                    && !remaining_archive_objects.is_empty()
                {
                    let progress_label = if explicit_loop_load {
                        &loop_progress_label
                    } else {
                        &preload_progress_label
                    };
                    let (history_frames, history_error) = load_archive_history_objects_parallel(
                        ArchiveHistoryLoadContext {
                            site_id: &site_id,
                            progress_label,
                            site_cache_dir: &site_cache_dir,
                            known_frame_paths: &known_frame_paths,
                            archive_lookup_ms,
                            total_start,
                            sender: &sender,
                            progress_done_start: archive_progress_done,
                            progress_total: recent_archive_total,
                        },
                        remaining_archive_objects,
                    );
                    fallback_error = fallback_error.or(history_error);
                    for decoded in history_frames {
                        decoded_frames.push(decoded);
                    }
                }
            }

            if decoded_frames.is_empty() {
                if explicit_loop_load && selected_identity.is_some() {
                    return Ok(AsyncLoadUpdate::Final(Ok(DecodedLoadBatch {
                        frames: Vec::new(),
                        selected_index: 0,
                    })));
                }
                if mode == LatestLoadMode::AutoRefresh {
                    return Ok(AsyncLoadUpdate::Unchanged {
                        timings: None,
                        reason: fallback_error
                            .unwrap_or_else(|| "no displayable Level II scans found".to_owned()),
                    });
                }
                return Err(fallback_error
                    .unwrap_or_else(|| "no displayable Level II scans found".to_owned()));
            }

            if explicit_loop_load {
                return Ok(AsyncLoadUpdate::Final(Ok(DecodedLoadBatch {
                    frames: Vec::new(),
                    selected_index: 0,
                })));
            }

            decoded_frames.sort_by(|left, right| {
                frame_identity_for_volume(&left.volume)
                    .cmp(&frame_identity_for_volume(&right.volume))
            });
            let selected_index = selected_identity
                .and_then(|identity| {
                    decoded_frames
                        .iter()
                        .position(|decoded| frame_identity_for_volume(&decoded.volume) == identity)
                })
                .unwrap_or_else(|| decoded_frames.len().saturating_sub(1));

            Ok(AsyncLoadUpdate::Final(Ok(DecodedLoadBatch {
                frames: decoded_frames,
                selected_index,
            })))
        })();
        let update = final_update.unwrap_or_else(|err| AsyncLoadUpdate::Final(Err(err)));
        let _ = sender.send(AsyncLoadResult {
            label: format!("L2 {site_id}"),
            update,
        });
    });
}

