/// render channel (renders are independent; a slow layer never blocks the
/// others). `id` is stable for UI rows; draw order = vec order.
struct MapLayerSlot {
    id: u64,
    layer: model_layer::ModelMapLayer,
    texture: Option<(egui::TextureHandle, u64, ModelLayerView)>,
    render_rx: Option<mpsc::Receiver<ModelLayerRender>>,
}

/// The map view a model-layer raster was rendered for.
#[derive(Clone, Copy, PartialEq)]
struct ModelLayerView {
    center_lat: f32,
    center_lon: f32,
    map_scale: f32,
}

fn model_layer_view_needs_rerender(rendered: &ModelLayerView, current: &ModelLayerView) -> bool {
    if !rendered.center_lat.is_finite()
        || !rendered.center_lon.is_finite()
        || !rendered.map_scale.is_finite()
        || !current.center_lat.is_finite()
        || !current.center_lon.is_finite()
        || !current.map_scale.is_finite()
        || rendered.map_scale <= 0.0
        || current.map_scale <= 0.0
    {
        return true;
    }
    let zoom_delta = (current.map_scale / rendered.map_scale).ln().abs()
        > (1.0 + MAP_LAYER_RERENDER_ZOOM_RATIO).ln();
    if zoom_delta {
        return true;
    }
    let (east_km, north_km) = aeqd_forward_km(
        current.center_lat as f64,
        current.center_lon as f64,
        rendered.center_lat as f64,
        rendered.center_lon as f64,
    );
    let pan_px = east_km.hypot(north_km) as f32 * current.map_scale / 111.32;
    pan_px > MAP_LAYER_RERENDER_PAN_PX
}

/// Whether a field came from a locally-ingested WRF/NetCDF run (store model
/// slug `wrf`, per `wrf_process` / `local_import`). Such fields get Solar's
/// WRF-Runner palettes by default via [`solar_model_field_table`].
fn is_local_wrf_field(field: &rw_ui::FieldData) -> bool {
    let model = field.key.hour.model.to_ascii_lowercase();
    model == "wrf" || model.starts_with("wrf")
}

fn default_model_layer_color_family(field: &rw_ui::FieldData) -> Option<ColorTableFamily> {
    let model = field.key.hour.model.to_ascii_lowercase();
    let var = field.key.var.to_ascii_lowercase();
    let units = field.units.trim().to_ascii_lowercase();
    // Locally-ingested WRF reflectivity is colored by Solar's "PW Style" via
    // the model-table path (`solar_model_field_table`), so don't claim it for
    // the radar reflectivity family here. Real radar composites (MRMS/OPERA
    // and any downloaded dBZ model field) still bind to the radar table so
    // they match the radar overlay pixel-for-pixel.
    if is_local_wrf_field(field) {
        return None;
    }
    if units == "dbz"
        || model == "mrms"
        || model == "eumetnet-opera"
        || var.contains("reflectivity")
        || var.contains("dbzh")
        || var.contains("cref")
    {
        Some(ColorTableFamily::Reflectivity)
    } else {
        None
    }
}

/// Resolve the Solarpower07 WRF-Runner palette a model layer should use, or
/// `None` to keep the field's production style / generic ramp.
///
/// WRF/local fields take their Solar palette by default (it's the intended
/// look). Downloaded-model fields only take one when Rusty Weather supplied
/// no production style — turning the generic viridis fallback into a
/// sensible, unit-aware table. Ranks below an explicit `custom_color_family`
/// override.
///
/// `user_override` — whether the 🎨 Color-tables editor binds a user palette
/// to this field ([`model_data::user_style_override_active`]). The store
/// worker compiles that binding INTO `field.style` (= the layer's production
/// colormap), so when it is set Solar must yield or the user's edit would be
/// silently repainted over. Effective precedence: user override → Solar
/// model table → production → generic ramp.
///
/// CREDIT: Solarpower07 (see `color_tables::solar`).
fn model_layer_solar_table(
    field: &rw_ui::FieldData,
    has_production: bool,
    user_override: bool,
) -> Option<Arc<ColorTable>> {
    if user_override {
        return None;
    }
    let table = color_tables::solar_model_field_table(&field.key.var, &field.units)?;
    if is_local_wrf_field(field) || !has_production {
        Some(Arc::new(table))
    } else {
        None
    }
}

/// Single source of truth for the on-screen color a model layer gives
/// `value`: BowEcho family override → Solar model table → rusty-weather
/// production style (which carries any 🎨 user-bound palette) → generic
/// normalized ramp. Both `draw_model_layers`' raster loop and the inspector
/// color chip resolve through this, so the chip can never drift from the
/// painted pixel.
fn model_layer_value_color(
    custom_table: Option<&ColorTable>,
    model_table: Option<&ColorTable>,
    production: Option<&rustwx_render::LeveledColormap>,
    range: Option<(f32, f32)>,
    generic: rw_ui::colormap::Colormap,
    value: f32,
) -> Option<egui::Color32> {
    if let Some(table) = custom_table {
        let [r, g, b, a] = table.sample(value).to_array();
        Some(egui::Color32::from_rgba_unmultiplied(r, g, b, a))
    } else if let Some(table) = model_table {
        let [r, g, b, a] = table.sample(value).to_array();
        Some(egui::Color32::from_rgba_unmultiplied(r, g, b, a))
    } else if let Some(cmap) = production {
        let rgba = cmap.map(f64::from(value));
        Some(egui::Color32::from_rgba_unmultiplied(
            rgba.r, rgba.g, rgba.b, rgba.a,
        ))
    } else if let Some((vmin, vmax)) = range {
        let t = rw_ui::colormap::normalize(value, vmin, vmax);
        Some(generic.sample(t))
    } else {
        None
    }
}

fn map_layer_rerender_deferred(ctx: &egui::Context) -> bool {
    ctx.input(|input| {
        input.pointer.any_down() || input.smooth_scroll_delta.length_sq() > f32::EPSILON
    })
}

