/// error) — the id lets the drain drop answers for a provider the user has
/// since navigated away from.
type IntlSiteListResult = (
    String,
    std::result::Result<Vec<data_source::international::IntlSite>, String>,
);

// What the shared poller follows lives in `self.primary.feed` (v0.29 Phase
// 4e stage (i)): the legacy two-variant `PollSource` enum died into
// `ui_core::loop_engine::FeedSource` — `CustomUrl` ↔ `CustomUrl`, `Intl` ↔
// `Live(SiteRef::Intl)`; `save_to_settings`/`intl_from_settings` live on
// `FeedSource` with the identical per-variant write/restore behavior.
// There is still ONE poll: both variants share `poll_active` / `poll_rx` /
// `primary.live.dedupe_key` / `poll_next` and the `install_polled_volume`
// install path, so every ownership guard — the auto-refresh skip in
// `maybe_refresh_realtime_level2`, the explicit-load pauses, history
// upsert + follow — applies to both identically.

fn diagnostic_poll_source_label(source: &FeedSource) -> String {
    match source {
        FeedSource::CustomUrl(url) => format!("custom {}", diagnostic_url_label(url)),
        FeedSource::Live(SiteRef::Intl {
            provider_id,
            site_id,
        }) => format!("intl {provider_id}/{site_id}"),
        // Unreachable through Phase 4e stage (i): the primary feed is only
        // ever CustomUrl or Live(Intl) until the stage-(ii) unify.
        FeedSource::Live(SiteRef::Us { level2_id }) => format!("us {level2_id}"),
        FeedSource::Archive { site, .. } => format!("archive {}", site.settings_key()),
        FeedSource::LocalFiles { label } => format!("local {label}"),
    }
}

fn diagnostic_url_label(url: &str) -> String {
    let trimmed = url.trim();
    if trimmed.is_empty() {
        return "-".to_owned();
    }
    let Some((scheme, rest)) = trimmed.split_once("://") else {
        return trimmed
            .split(['/', '?', '#'])
            .next()
            .unwrap_or(trimmed)
            .to_owned();
    };
    let host = rest
        .split(['/', '?', '#'])
        .next()
        .filter(|host| !host.is_empty())
        .unwrap_or(rest);
    format!("{scheme}://{host}/...")
}

fn optional_ms_label(value: Option<f32>) -> String {
    value
        .map(|value| format!("{value:.1}"))
        .unwrap_or_else(|| "-".to_owned())
}

fn push_optional_path(text: &mut String, label: &str, path: Option<&Path>) {
    let value = path
        .map(|path| path.display().to_string())
        .unwrap_or_else(|| "-".to_owned());
    let _ = writeln!(text, "{label}: {value}");
}

/// Picker label for an international provider id; falls back to the raw id
/// when a saved selection references a provider this build doesn't ship.
pub(crate) fn intl_provider_label(provider_id: &str) -> String {
    data_source::international::intl_providers()
        .into_iter()
        .find(|provider| provider.id() == provider_id)
        .map(|provider| provider.label().to_owned())
        .unwrap_or_else(|| provider_id.to_owned())
}

/// Comma-joined labels of every international provider with a real
/// multi-frame recent catalog — derived from the provider registry's
/// capability cards, so the Load Loop hover and the one-frame status
/// hint can never go stale against the adapter code.
fn intl_recent_loop_provider_labels() -> &'static str {
    static LABELS: OnceLock<String> = OnceLock::new();
    LABELS.get_or_init(|| {
        data_source::international::intl_provider_capabilities()
            .into_iter()
            .filter(|capability| capability.recent_loop)
            .map(|capability| capability.provider_label)
            .collect::<Vec<_>>()
            .join(", ")
    })
}
/// SPC fetch identity: (day, archive date) — refetch when it changes.
type SpcFetchKey = (u8, Option<(i32, u32, u32)>);
type ModelLayerRender = (u64, ModelLayerView, egui::ColorImage, f32);

/// One SPC storm report (tornado) — the archive events browser entry.
#[derive(Clone, Debug)]
struct SpcReport {
    time_utc: DateTime<Utc>,
    f_scale: String,
    location: String,
    state: String,
    lat: f32,
    lon: f32,
}

/// Parse SPC's filtered tornado-report CSV
/// (Time,F_Scale,Location,County,State,Lat,Lon,Comments; times UTC; the
/// report "day" runs 12Z -> 12Z next day, so HHMM < 1200 belongs to the
/// following calendar date).
fn parse_spc_tornado_csv(date: chrono::NaiveDate, text: &str) -> Vec<SpcReport> {
    let mut reports = Vec::new();
    for line in text.lines().skip(1) {
        let fields: Vec<&str> = line.splitn(8, ',').collect();
        if fields.len() < 7 {
            continue;
        }
        let Ok(hhmm) = fields[0].trim().parse::<u32>() else {
            continue;
        };
        let (hour, minute) = (hhmm / 100, hhmm % 100);
        if hour > 23 || minute > 59 {
            continue;
        }
        let report_date = if hour < 12 {
            date + chrono::Duration::days(1)
        } else {
            date
        };
        let Some(time_utc) = report_date
            .and_hms_opt(hour, minute, 0)
            .map(|naive| DateTime::<Utc>::from_naive_utc_and_offset(naive, Utc))
        else {
            continue;
        };
        let (Ok(lat), Ok(lon)) = (
            fields[5].trim().parse::<f32>(),
            fields[6].trim().parse::<f32>(),
        ) else {
            continue;
        };
        reports.push(SpcReport {
            time_utc,
            f_scale: fields[1].trim().to_owned(),
            location: fields[2].trim().to_owned(),
            state: fields[4].trim().to_owned(),
            lat,
            lon,
        });
    }
    reports
}

/// A rotation site detected on the lowest velocity tilt, geolocated.
#[derive(Clone, Copy, Debug)]
struct RotationMarker {
    lon: f32,
    lat: f32,
    /// Best rotational velocity across the column (m/s).
    vrot_mps: f32,
    /// 3D strength rank (Stumpf et al. 1998 scale).
    rank: u8,
    strength: render2d::RotationStrength,
    /// Volumes in a row this circulation has been detected (time association,
    /// Stumpf 1998 §3d): a first-seen meso-strength couplet displays as CPLT
    /// and is promoted to MESO once seen on consecutive volumes.
    persistence: u8,
}

/// An extra synchronized view pane in the multi-pane grid. Pane 0 is the
/// primary view (ViewerApp's own product/texture state, untouched); extra
/// panes are 1-based. All panes share the loaded volume, the geo transform
/// (pan/zoom stay in sync by construction), the selected tilt, and the ONE
/// render worker — renders are sequential on it, so total CPU parallelism
/// stays bounded at the core count no matter how many panes are open.
/// One extra view pane: a [`LoopEngine`] plus the display-side state the
/// engine does not own (v0.29 Phase 4d — the spec §3 `PaneView` shape;
/// panes are the SECOND engine adoption, after the 4c overlays). Textures
/// and the load receiver stay view-side because the 4d engine core
/// deliberately has no worker/texture slots — those arrive with the
/// primary port (4e).
///
/// Engine-owned state, with the legacy `PaneView` field it replaced (for
/// grep archaeology): `engine.history` ← `frame_history`,
/// `engine.cursor.index` ← `selected_frame_index`, `engine.cursor.playing`
/// ← `history_playing`, `engine.cursor.browsing` ← `browsing_history`,
/// `engine.cursor.last_step` ← `last_history_step`, `engine.live.enabled`
/// ← `live` (the per-pane auto-refresh toggle; defaults ON — independent
/// panes exist for storm-day multi-radar), `engine.live.last_refresh` ←
/// `last_realtime_level2_refresh`, `engine.status` ← `status`,
/// `engine.limits` ← the silent `self.primary.limits.frame_limit` read in the
/// deleted `trim_extra_pane_history` (census D8: the primary's limit is
/// now passed explicitly at construction and re-passed at every install).
///
/// `engine.feed` MIRRORS `pin`: `Live(pin)` when pinned, the inert
/// [`PaneView::follow_primary_feed`] placeholder when following. The one
/// sync site is [`ViewerApp::extra_pane_live_action`], which re-derives the
/// feed from the pin before every engine consultation — direct pin writes
/// (loads, restores, tests) converge on the next tick, so the mirror can
/// never drift for more than one frame.
struct PaneView {
    /// The pane's loop machine (`EngineRole::Pane { slot }`).
    engine: LoopEngine,
    product: DisplayProduct,
    /// Pane-local mirror of `ViewerApp::pending_product_restore`: when a
    /// velocity-less frame forces this pane to fall back to reflectivity for
    /// that frame only (a live-partial / stale / not-yet-complete velocity
    /// cut), the pane's chosen product is remembered here so the next frame
    /// that CAN show it restores it. Without this a following/owned velocity
    /// pane that hit one velocity-less frame stuck on reflectivity for the
    /// rest of the loop (the fallback was written back as `product` and every
    /// later frame inherited it), while the primary already recovered.
    pending_product_restore: Option<DisplayProduct>,
    /// Independent tilt override; None = follow the main pane's tilt, so
    /// scrubbing the main tilt moves every un-pinned pane in sync.
    cut: Option<usize>,
    /// None = follow the primary radar volume. Some = this pane owns its
    /// own source and map view — ONE identity for both worlds (v0.29
    /// Phase 3): `SiteRef::Us` for Level-II catalog sites, `SiteRef::Intl`
    /// for international registry sites. The old `pinned_site_id` +
    /// `intl_source` pair could disagree (a lingering US id under an intl
    /// source, the Follow-primary `None==None` combo no-op); one enum
    /// makes those states unrepresentable.
    pin: Option<SiteRef>,
    /// Arc address of the primary frame most recently mirrored into this
    /// pane by the same-site dedupe (`follow_primary_volume_into_pane`),
    /// so an unchanged primary volume is not re-installed every tick.
    followed_primary_volume_ptr: Option<usize>,
    volume: Option<Arc<RadarVolume>>,
    source_path: Option<PathBuf>,
    load_timing: Option<LoadTimings>,
    archive_load_progress: Option<ArchiveLoadProgress>,
    load_receiver: Option<mpsc::Receiver<AsyncLoadResult>>,
    load_mode: Option<LatestLoadMode>,
    pending_site_id: Option<String>,
    map_center_lat: f32,
    map_center_lon: f32,
    map_scale: f32,
    texture: Option<egui::TextureHandle>,
    texture_key: Option<TextureKey>,
    pending_render_key: Option<TextureKey>,
    render_ms: Option<f32>,
}

impl PaneView {
    /// A fresh pane following the primary. `engine_id` comes from the
    /// session-monotonic `ViewerApp::next_radar_layer_id` counter (shared
    /// with overlay engines — EngineIds are never reused within a session);
    /// `limits` is the SHARED history-limits handoff (census D8): the
    /// caller passes `HistoryLimits::pane(self.primary.limits.frame_limit)` so the
    /// pane visibly starts on the primary's frame limit instead of silently
    /// reading it at trim time.
    fn new(engine_id: u64, slot: usize, product: DisplayProduct, limits: HistoryLimits) -> Self {
        let mut engine = LoopEngine::new(
            EngineId(engine_id),
            EngineRole::Pane {
                slot: u8::try_from(slot).unwrap_or(u8::MAX),
            },
            Self::follow_primary_feed(),
        );
        engine.limits = limits;
        // The pane Live toggle defaults ON regardless of the (inert)
        // follow-primary feed, so a first pin goes live immediately —
        // the legacy `live: true` default.
        engine.live.enabled = true;
        engine.status = "Following primary radar".to_owned();
        Self {
            engine,
            product,
            pending_product_restore: None,
            cut: None,
            pin: None,
            followed_primary_volume_ptr: None,
            volume: None,
            source_path: None,
            load_timing: None,
            archive_load_progress: None,
            load_receiver: None,
            load_mode: None,
            pending_site_id: None,
            map_center_lat: 0.0,
            map_center_lon: 0.0,
            map_scale: DEFAULT_MAP_SCALE,
            texture: None,
            texture_key: None,
            pending_render_key: None,
            render_ms: None,
        }
    }

    /// The engine feed for an UNPINNED pane. Deliberately inert: it is not
    /// a live variant, so an unpinned pane's engine structurally cannot
    /// claim `Liveness::Live` and never produces a poll cadence — every
    /// engine consultation is gated on `owns_radar()` anyway, and the chip
    /// for following panes reads the primary's state until Phase 4e.
    fn follow_primary_feed() -> FeedSource {
        FeedSource::LocalFiles {
            label: "following primary radar".to_owned(),
        }
    }

    /// Re-derive `engine.feed` from `pin` (the mirror invariant on
    /// [`PaneView`]). Called by `extra_pane_live_action` before every
    /// engine consultation; cheap when already in sync.
    fn sync_engine_feed_to_pin(&mut self) {
        let want = match &self.pin {
            Some(site) => FeedSource::Live(site.clone()),
            None => Self::follow_primary_feed(),
        };
        if self.engine.feed != want {
            self.engine.feed = want;
        }
    }

    fn owns_radar(&self) -> bool {
        self.pin.is_some()
    }

    /// Pinned US Level-II id, if this pane's pin is a US-catalog site.
    fn pinned_us_id(&self) -> Option<&str> {
        match self.pin.as_ref()? {
            SiteRef::Us { level2_id } => Some(level2_id),
            SiteRef::Intl { .. } => None,
        }
    }

    /// Pinned `(provider_id, site_id)`, if this pane's pin is an
    /// international registry site.
    fn pinned_intl(&self) -> Option<(&str, &str)> {
        match self.pin.as_ref()? {
            SiteRef::Us { .. } => None,
            SiteRef::Intl {
                provider_id,
                site_id,
            } => Some((provider_id, site_id)),
        }
    }

    fn clear_texture(&mut self) {
        self.texture = None;
        self.texture_key = None;
        self.pending_render_key = None;
        self.render_ms = None;
    }

    /// The pane clear blast radius (census D4): the engine-owned loop
    /// state PLUS the view-side load progress. Panes deliberately do NOT
    /// clear shared loop-render caches or storm state — that is the
    /// PRIMARY's clear, do not "fix" it here.
    fn clear_history(&mut self) {
        self.engine.clear_history();
        self.archive_load_progress = None;
    }
}

/// What actually feeds a radar-owning pane, as the live poll tick sees it.
/// This is the OWNER-side classification (catalog lookups, research-feed
/// refusal) feeding [`ui_core::loop_engine::LoopEngine::live_tick`]; the
/// SharedWithPrimary dedupe that used to be a variant here is now SiteRef
/// equality inside `live_tick` (Phase 4d — uniform for US and intl, the
/// "intl double-poll dies" deliverable).
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum PaneLiveSource {
    /// Nothing pollable: no source, a pinned id outside the US catalog
    /// (e.g. an international/archive id inherited from the primary), or
    /// a research feed the pane load path refuses anyway.
    None,
    /// Pinned US Level-II catalog site with its own feed.
    UsSite,
    /// International provider frames.
    Intl,
}

struct PaneContextSnapshot {
    volume: Option<Arc<RadarVolume>>,
    load_timing: Option<LoadTimings>,
    map_center_lat: f32,
    map_center_lon: f32,
    map_scale: f32,
}

struct RenderRequest {
    key: TextureKey,
    /// Which render lane this render is for (`ui_core::render_service::LaneId`).
    /// Queued requests coalesce per lane: a newer request replaces the queued
    /// one for the SAME lane only, so one lane's traffic can't starve another.
    lane: LaneId,
    volume: Arc<RadarVolume>,
    /// Strictly older same-site volume used by the model-anchored (v4)
    /// dealiaser's temporal prior. Kept as an Arc so background/prewarm
    /// workers never borrow mutable UI history.
    previous_volume: Option<Arc<RadarVolume>>,
    /// RAP 0-h analysis wind profile at the radar site (CONUS only) — the
    /// v4 engine's absolute Nyquist-branch anchor. None until the
    /// background fetch lands, and always None for intl sites (the engine's
    /// graceful no-env path). Identity is `key.dealias_env_ptr`.
    dealias_env: Option<Arc<EnvironmentalWindProfile>>,
    cut: usize,
    product: DisplayProduct,
    render_dealiased_velocity: bool,
    plain_velocity_render_dealiased: bool,
    color_tables: ColorTableSet,
    storm_motion: StormMotion,
    hail_levels_m: (f32, f32),
    /// Display smoothing: the worker preprocesses the polar grid once
    /// (cached) — binomial soften or bilinear upsample — and renders it
    /// through the unchanged fast path.
    smoothing: SmoothingMode,
    /// Velocity dealias engine for this render (see [`DealiasEngine`]):
    /// `Region`, `RegionGlobal`, or `Analyst3d`. Carried into the cache key
    /// so switching engines re-renders.
    dealias_engine: DealiasEngine,
    /// Gate filter threshold in deci-dBZ; i16::MIN = off.
    gate_filter_decidbz: i16,
    viewport_options: ViewportRasterOptions,
    radar_range_km: f32,
}

struct RenderedTexture {
    width: usize,
    height: usize,
    rgba: Vec<u8>,
    buffer_signature: RenderWorkerViewportSignature,
    render_ms: f32,
    worker_ms: f32,
    sample_cache_build_ms: Option<f32>,
    used_sample_cache: bool,
    radar_range_km: f32,
}

struct CachedLoopRenderedTexture {
    width: usize,
    height: usize,
    rgba: Arc<[u8]>,
    buffer_signature: RenderWorkerViewportSignature,
    render_ms: f32,
    worker_ms: f32,
    sample_cache_build_ms: Option<f32>,
    used_sample_cache: bool,
    radar_range_km: f32,
}

impl CachedLoopRenderedTexture {
    fn from_rendered(rendered: RenderedTexture) -> Self {
        Self {
            width: rendered.width,
            height: rendered.height,
            rgba: Arc::from(rendered.rgba.into_boxed_slice()),
            buffer_signature: rendered.buffer_signature,
            render_ms: rendered.render_ms,
            worker_ms: rendered.worker_ms,
            sample_cache_build_ms: rendered.sample_cache_build_ms,
            used_sample_cache: rendered.used_sample_cache,
            radar_range_km: rendered.radar_range_km,
        }
    }

    fn to_rendered(&self) -> RenderedTexture {
        RenderedTexture {
            width: self.width,
            height: self.height,
            rgba: self.rgba.as_ref().to_vec(),
            buffer_signature: self.buffer_signature.clone(),
            render_ms: self.render_ms,
            worker_ms: self.worker_ms,
            sample_cache_build_ms: self.sample_cache_build_ms,
            used_sample_cache: self.used_sample_cache,
            radar_range_km: self.radar_range_km,
        }
    }
}

struct LoopRenderCacheEntry {
    key: TextureKey,
    rendered: CachedLoopRenderedTexture,
    bytes: usize,
}

/// Drop a drained loop's frame history and render-cache buffers on a
/// detached worker thread. A loaded synthetic-radar loop is multiple GB of
/// `Arc<RadarVolume>` (plus the render cache's `Arc<[u8]>` RGBA rasters);
/// releasing it inline on the egui update thread — which is what the loop
/// engine's cross-site clear used to do when the first live volume replaced
/// a synthetic loop — froze the UI ~10s while the allocator returned the
/// memory. Both inputs are the LAST references to their buffers (the engine
/// history is already empty; the render cache copies its RGBA out on read),
/// so the final release happens off-thread. No-op when there is nothing to
/// reap. On the rare spawn failure the closure is dropped here, falling back
/// to the old inline release — correct, just slow.
fn spawn_loop_history_reaper(
    frames: Vec<FrameHistoryEntry>,
    render_cache: VecDeque<LoopRenderCacheEntry>,
) -> Option<std::thread::JoinHandle<()>> {
    if frames.is_empty() && render_cache.is_empty() {
        return None;
    }
    std::thread::Builder::new()
        .name("loop-history-reaper".to_owned())
        .spawn(move || {
            drop(frames);
            drop(render_cache);
        })
        .ok()
}

#[derive(Clone, Debug, Eq, PartialEq)]
struct LoopRenderContextKey {
    // Deliberately excludes `cut`: low-sweep playback changes cuts on nearly
    // every timeline step, while the full TextureKey already distinguishes
    // cached rasters by cut. Treating a cut change as a whole-loop context
    // change flushes useful frames and loses in-flight prewarm bookkeeping.
    product: DisplayProduct,
    render_dealiased_velocity: bool,
    color_table_signature: u64,
    storm_motion_key: (i16, i16),
    hail_levels_key: (i16, i16),
    smoothing: SmoothingMode,
    dealias_engine: DealiasEngine,
    // `dealias_env_ptr` is deliberately absent, like the reference-volume
    // pointer: both are per-frame DATA identity (the full TextureKey keys
    // cached rasters by them); a landing RAP profile must not read as a
    // whole-loop context change for frames near a cycle boundary.
    gate_filter_decidbz: i16,
    viewport: ViewportKey,
}

impl LoopRenderContextKey {
    fn from_texture_key(key: &TextureKey) -> Self {
        Self {
            product: key.product.clone(),
            render_dealiased_velocity: key.render_dealiased_velocity,
            color_table_signature: key.color_table_signature,
            storm_motion_key: key.storm_motion_key,
            hail_levels_key: key.hail_levels_key,
            smoothing: key.smoothing,
            dealias_engine: key.dealias_engine,
            gate_filter_decidbz: key.gate_filter_decidbz,
            viewport: key.viewport,
        }
    }
}

struct RenderRecycleBuffer {
    rgba: Vec<u8>,
    signature: Option<RenderWorkerViewportSignature>,
}

struct DealiasedReadoutCache {
    volume_ptr: usize,
    reference_volume_ptr: usize,
    dealias_env_ptr: usize,
    cut_index: usize,
    /// Which engine produced `grid`; switching engines invalidates this
    /// readout cache so the cursor readout matches the rendered image.
    dealias_engine: DealiasEngine,
    /// Attests the pointer fields above still identify the grid's inputs —
    /// same defense as the shared [`DealiasGridCache`]: a readout for a
    /// history-trimmed volume must not survive into an address-recycled
    /// successor (checked on lookup in `dealiased_velocity_readout_grid`).
    witness: DealiasGridWitness,
    grid: Arc<MomentGrid>,
}

/// Engine + optional Analyst3d anchor identity shared by every consumer of a
/// dealiased field. Pure same-tilt engines deliberately zero both pointers;
/// only Analyst3d output depends on the previous volume and RAP profile.
#[derive(Clone, Copy, Debug, Eq, Hash, Ord, PartialEq, PartialOrd)]
struct DealiasContextKey {
    reference_volume_ptr: usize,
    dealias_env_ptr: usize,
    engine: DealiasEngine,
}

impl DealiasContextKey {
    fn new(
        engine: DealiasEngine,
        previous_volume: Option<&Arc<RadarVolume>>,
        dealias_env: Option<&Arc<EnvironmentalWindProfile>>,
    ) -> Self {
        let anchored = engine == DealiasEngine::Analyst3d;
        Self {
            reference_volume_ptr: if anchored {
                previous_volume
                    .map(|volume| Arc::as_ptr(volume) as usize)
                    .unwrap_or(0)
            } else {
                0
            },
            dealias_env_ptr: if anchored {
                dealias_env
                    .map(|profile| Arc::as_ptr(profile) as usize)
                    .unwrap_or(0)
            } else {
                0
            },
            engine,
        }
    }
}

/// Identity of one dealiased velocity tilt. The raw addresses distinguish
/// inputs cheaply, but an address alone is NOT an identity: a dropped
/// volume's allocation can be recycled by a later `Arc` (the volume-ptr ABA
/// the texture path defends against by poisoning keys in
/// `install_decoded_volume`). Every cache entry therefore also carries a
/// [`DealiasGridWitness`] that attests these addresses still point at the
/// inputs the grid was computed from. `reference_volume_ptr`/
/// `dealias_env_ptr` are the previous volume and RAP profile the `Analyst3d`
/// engine consumes (both `0` for the pure same-tilt `Region`/`RegionGlobal`
/// engines), so switching any input yields a distinct key.
#[derive(Clone, Copy, Debug, Eq, Hash, PartialEq)]
struct DealiasGridKey {
    volume_ptr: usize,
    reference_volume_ptr: usize,
    dealias_env_ptr: usize,
    cut_index: usize,
    engine: DealiasEngine,
}

impl DealiasGridKey {
    fn from_context(volume_ptr: usize, cut_index: usize, context: DealiasContextKey) -> Self {
        Self {
            volume_ptr,
            reference_volume_ptr: context.reference_volume_ptr,
            dealias_env_ptr: context.dealias_env_ptr,
            cut_index,
            engine: context.engine,
        }
    }

    /// Key for the pure same-tilt engines (`Region`/`RegionGlobal`): they read
    /// only this volume's own tilt, so the reference/env pointers are `0`.
    #[cfg(test)]
    fn same_tilt(volume_ptr: usize, cut_index: usize, engine: DealiasEngine) -> Self {
        Self {
            volume_ptr,
            reference_volume_ptr: 0,
            dealias_env_ptr: 0,
            cut_index,
            engine,
        }
    }
}

/// Liveness witness for the raw addresses in a [`DealiasGridKey`]. Each
/// `Weak` does two jobs. (1) `strong_count() == 0` proves an input was
/// dropped, so its entry is a miss that gets evicted instead of silently
/// serving a dead volume's grid. (2) Holding the `Weak` keeps the dropped
/// input's `ArcInner` allocation resident (its weak count stays > 0), so no
/// NEW `Arc` can ever land at the recycled address while the entry exists —
/// the volume-ptr ABA stale hit is structurally impossible, not merely
/// unlikely. The pinned shell is only the counters + the struct itself (the
/// volume's heap payload is freed when the last strong ref drops), so the
/// retained bytes per dead entry are negligible and reclaimed by
/// [`DealiasGridCache::purge_dead`].
#[derive(Clone)]
struct DealiasGridWitness {
    volume: Weak<RadarVolume>,
    reference_volume: Option<Weak<RadarVolume>>,
    dealias_env: Option<Weak<EnvironmentalWindProfile>>,
}

impl DealiasGridWitness {
    /// Witness for the pure same-tilt engines (`Region`/`RegionGlobal`),
    /// mirroring [`DealiasGridKey::same_tilt`]'s zeroed anchor pointers.
    #[cfg(test)]
    fn same_tilt(volume: &Arc<RadarVolume>) -> Self {
        Self {
            volume: Arc::downgrade(volume),
            reference_volume: None,
            dealias_env: None,
        }
    }

    /// Witness including the `Analyst3d` anchors; pass `None` for an anchor
    /// whose key pointer is `0`.
    fn with_anchors(
        volume: &Arc<RadarVolume>,
        reference_volume: Option<&Arc<RadarVolume>>,
        dealias_env: Option<&Arc<EnvironmentalWindProfile>>,
    ) -> Self {
        Self {
            volume: Arc::downgrade(volume),
            reference_volume: reference_volume.map(Arc::downgrade),
            dealias_env: dealias_env.map(Arc::downgrade),
        }
    }

    /// All attested inputs still alive? At most three atomic loads —
    /// allocation-free, cheap enough for every cache hit.
    fn alive(&self) -> bool {
        self.volume.strong_count() > 0
            && self
                .reference_volume
                .as_ref()
                .is_none_or(|weak| weak.strong_count() > 0)
            && self
                .dealias_env
                .as_ref()
                .is_none_or(|weak| weak.strong_count() > 0)
    }
}

struct DealiasGridEntry {
    key: DealiasGridKey,
    witness: DealiasGridWitness,
    grid: Arc<MomentGrid>,
    bytes: usize,
}

/// Approximate resident size of a dealiased grid, for the cache byte budget.
fn moment_grid_cache_bytes(grid: &MomentGrid) -> usize {
    let word_bytes = usize::from(grid.storage.word_size_bits()) / 8;
    grid.storage.len() * word_bytes.max(1)
        + grid.radial_indices.len() * std::mem::size_of::<usize>()
        + std::mem::size_of::<MomentGrid>()
}

/// Byte-bounded LRU memo of dealiased velocity grids. `front` is the
/// least-recently-used entry, `back` the most-recent; a hit moves its entry to
/// the back so a full-loop working set survives while stale tilts age out.
/// Linear scan is fine: lookups happen on render-cache misses (a handful per
/// frame), never per pixel, and the entry count stays in the low hundreds.
struct DealiasGridCache {
    entries: VecDeque<DealiasGridEntry>,
    bytes: usize,
    budget_bytes: usize,
}

impl DealiasGridCache {
    fn with_budget(budget_bytes: usize) -> Self {
        Self {
            entries: VecDeque::new(),
            bytes: 0,
            budget_bytes,
        }
    }

    /// Return the cached grid for `key`, promoting it to most-recently-used.
    /// A key match whose witness reports a dropped input is NOT a hit: the
    /// addresses in the key no longer identify the grid's inputs, so the
    /// stale entry is evicted and the caller recomputes.
    fn get(&mut self, key: &DealiasGridKey) -> Option<Arc<MomentGrid>> {
        let pos = self.entries.iter().position(|entry| entry.key == *key)?;
        if !self.entries[pos].witness.alive() {
            if let Some(dead) = self.entries.remove(pos) {
                self.bytes = self.bytes.saturating_sub(dead.bytes);
            }
            return None;
        }
        let entry = self.entries.remove(pos)?;
        let grid = Arc::clone(&entry.grid);
        self.entries.push_back(entry);
        Some(grid)
    }

    /// Store `grid` under `key` (most-recently-used), then evict oldest entries
    /// until within the byte budget. The just-inserted entry is never evicted.
    /// Also purges entries for dropped volumes: this runs on the miss path
    /// right after a ~200 ms dealias, so the linear scan is free by
    /// comparison, and orphaned grids stop piling up toward the byte cap.
    fn insert(&mut self, key: DealiasGridKey, witness: DealiasGridWitness, grid: Arc<MomentGrid>) {
        self.purge_dead();
        if let Some(pos) = self.entries.iter().position(|entry| entry.key == key)
            && let Some(old) = self.entries.remove(pos)
        {
            self.bytes = self.bytes.saturating_sub(old.bytes);
        }
        let bytes = moment_grid_cache_bytes(&grid);
        self.bytes += bytes;
        self.entries.push_back(DealiasGridEntry {
            key,
            witness,
            grid,
            bytes,
        });
        self.evict_to_budget();
    }

    /// Retarget the byte budget (the user changed the radar-history budget or
    /// the pane count). Growing keeps every entry; shrinking evicts the oldest
    /// down to the new cap. Idempotent, so cheap to call on every settings sync.
    fn set_budget(&mut self, budget_bytes: usize) {
        self.budget_bytes = budget_bytes;
        // Prefer reclaiming grids of dropped volumes over evicting live ones.
        self.purge_dead();
        self.evict_to_budget();
    }

    /// Drop every entry whose witness reports a dropped input (grids for
    /// volumes long trimmed from history / replaced by live polling).
    fn purge_dead(&mut self) {
        let mut freed = 0usize;
        self.entries.retain(|entry| {
            if entry.witness.alive() {
                true
            } else {
                freed += entry.bytes;
                false
            }
        });
        self.bytes = self.bytes.saturating_sub(freed);
    }

    /// Drop least-recently-used entries until within budget, always keeping at
    /// least the most-recent one so a single oversized grid still caches.
    fn evict_to_budget(&mut self) {
        while self.bytes > self.budget_bytes && self.entries.len() > 1 {
            let Some(front) = self.entries.pop_front() else {
                break;
            };
            self.bytes = self.bytes.saturating_sub(front.bytes);
        }
    }

    #[cfg(test)]
    fn len(&self) -> usize {
        self.entries.len()
    }

    #[cfg(test)]
    fn total_bytes(&self) -> usize {
        self.bytes
    }
}

/// Per-machine floor for the grid memo (see the tier consts): a beefy machine
/// never drops below a useful working set even with a small history budget.
fn dealias_grid_cache_tier_floor_bytes() -> usize {
    match effective_worker_threads() {
        0..=7 => LOW_END_DEALIAS_GRID_CACHE_BYTES,
        8..=15 => MID_RANGE_DEALIAS_GRID_CACHE_BYTES,
        _ => HIGH_END_DEALIAS_GRID_CACHE_BYTES,
    }
}

/// Byte budget for the shared dealiased-grid memo, scaled to the user's
/// radar-history RAM budget so it can hold one dealiased grid PER loaded frame
/// PER active dealias pane — the whole loaded loop stays memoized instead of
/// the tail re-dealiasing under LRU eviction. `active_dealias_panes` is the
/// pane count (primary + extras, 1..=4); floored at the per-machine tier.
fn dealias_grid_cache_budget_bytes(history_budget_gib: u16, active_dealias_panes: usize) -> usize {
    let panes = active_dealias_panes.max(1);
    let scaled = radar_history_budget_bytes(history_budget_gib)
        / DEALIAS_GRID_BUDGET_HISTORY_DIVISOR
        * panes;
    scaled.max(dealias_grid_cache_tier_floor_bytes())
}

/// Retarget the process-wide grid memo's budget from the current settings.
/// Called at startup and whenever the radar-history budget or pane count
/// changes; growing is free, shrinking evicts the oldest grids down to the cap.
fn set_dealias_grid_cache_budget(history_budget_gib: u16, active_dealias_panes: usize) {
    let budget = dealias_grid_cache_budget_bytes(history_budget_gib, active_dealias_panes);
    dealias_grid_cache()
        .lock()
        .unwrap_or_else(|poison| poison.into_inner())
        .set_budget(budget);
}

/// Process-wide memo of dealiased velocity grids. The three dealiasers
/// (`dealias_velocity_grid`, `dealias_velocity_grid_pyart_region`,
/// `dealias_velocity_grid_v4`) cost ~200 ms/tilt (measured: 219 ms on a live
/// PGUA super-res velocity cut); without this, replaying a loop or toggling a
/// product back to dealiased velocity re-runs them on every frame. Shared
/// across ALL render workers (primary, panes, overlay, and the
/// one-shot loop-prewarm pool whose Overlay policy keeps only one moment cache)
/// plus the UI-thread cursor readout, so a given (volume, cut, engine) tilt is
/// dealiased at most once. LRU-bounded so a long loop cannot grow it forever.
fn dealias_grid_cache() -> &'static Mutex<DealiasGridCache> {
    static CACHE: OnceLock<Mutex<DealiasGridCache>> = OnceLock::new();
    CACHE.get_or_init(|| {
        // Initialised lazily (possibly from a background worker before settings
        // are known) at the default history budget for a single pane;
        // `set_dealias_grid_cache_budget` rescales it once the app knows the
        // user's real budget and pane count.
        Mutex::new(DealiasGridCache::with_budget(
            dealias_grid_cache_budget_bytes(settings::default_radar_history_budget_gib(), 1),
        ))
    })
}

/// Return the memoized dealiased grid for `key`, computing it via `compute`
/// only on a miss. The dealias runs WITHOUT the cache lock held (~200 ms would
/// otherwise serialize every render worker); a concurrent duplicate compute is
/// harmless and dedups to a single shared `Arc` on insert. `compute` returns
/// `None` when the tilt cannot be dealiased (e.g. `Analyst3d` failure), which
/// is not cached. `witness` must attest the very `Arc`s whose addresses are
/// in `key`; it is stored with the entry so a later lookup can prove the
/// addresses still identify these inputs.
fn cached_dealias_grid(
    key: DealiasGridKey,
    witness: DealiasGridWitness,
    compute: impl FnOnce() -> Option<MomentGrid>,
) -> Option<Arc<MomentGrid>> {
    debug_assert_eq!(
        witness.volume.as_ptr() as usize,
        key.volume_ptr,
        "witness must attest the keyed volume"
    );
    debug_assert_eq!(
        witness
            .reference_volume
            .as_ref()
            .map(|weak| weak.as_ptr() as usize)
            .unwrap_or(0),
        key.reference_volume_ptr,
        "witness must attest the keyed reference volume"
    );
    debug_assert_eq!(
        witness
            .dealias_env
            .as_ref()
            .map(|weak| weak.as_ptr() as usize)
            .unwrap_or(0),
        key.dealias_env_ptr,
        "witness must attest the keyed environment profile"
    );
    if let Some(hit) = dealias_grid_cache()
        .lock()
        .unwrap_or_else(|poison| poison.into_inner())
        .get(&key)
    {
        return Some(hit);
    }
    // Count actual dealias runs (cache misses). Relaxed is fine: this is a
    // diagnostic tally, never a synchronization signal. Lets tests assert a
    // given (volume, cut, engine) tilt is dealiased at most once across the
    // primary AND every pane, which is the whole point of the shared memo.
    note_dealias_grid_computed();
    let grid = Arc::new(compute()?);
    let mut cache = dealias_grid_cache()
        .lock()
        .unwrap_or_else(|poison| poison.into_inner());
    // Another worker may have computed the same key while we were unlocked;
    // prefer its entry so every caller shares one Arc.
    if let Some(existing) = cache.get(&key) {
        return Some(existing);
    }
    cache.insert(key, witness, Arc::clone(&grid));
    Some(grid)
}

/// Resolve exactly one dealiased velocity tilt through the process-wide memo.
/// Every display and analysis path calls this seam, so the selected engine and
/// Analyst3d anchor identity cannot drift between the painted velocity,
/// derivatives, markers, tracks, and GBVTD.
fn resolve_dealiased_grid(
    volume: &Arc<RadarVolume>,
    previous_volume: Option<&Arc<RadarVolume>>,
    dealias_env: Option<&Arc<EnvironmentalWindProfile>>,
    cut_index: usize,
    engine: DealiasEngine,
) -> Option<Arc<MomentGrid>> {
    let context = DealiasContextKey::new(engine, previous_volume, dealias_env);
    let key = DealiasGridKey::from_context(Arc::as_ptr(volume) as usize, cut_index, context);
    let anchored = engine == DealiasEngine::Analyst3d;
    let witness = DealiasGridWitness::with_anchors(
        volume,
        anchored.then_some(previous_volume).flatten(),
        anchored.then_some(dealias_env).flatten(),
    );
    let cut = volume.cuts.get(cut_index)?;
    let source = cut.moments.get(&MomentType::Velocity)?;
    cached_dealias_grid(key, witness, || match engine {
        DealiasEngine::Analyst3d => dealias_velocity_grid_v4(
            volume,
            cut_index,
            previous_volume.map(|reference| reference.as_ref()),
            dealias_env.map(|profile| profile.as_ref()),
        ),
        DealiasEngine::RegionGlobal => Some(dealias_velocity_grid_pyart_region(cut, source)),
        DealiasEngine::Region => Some(dealias_velocity_grid(cut, source)),
    })
}

/// Resolve every velocity-bearing cut using [`resolve_dealiased_grid`]. The
/// vector is aligned one-for-one with `volume.cuts`, which is the explicit
/// input contract of render2d's downstream no-double-dealias kernels.
fn resolve_dealiased_volume_grids(
    volume: &Arc<RadarVolume>,
    previous_volume: Option<&Arc<RadarVolume>>,
    dealias_env: Option<&Arc<EnvironmentalWindProfile>>,
    engine: DealiasEngine,
) -> Vec<Option<Arc<MomentGrid>>> {
    let cut_indices: Vec<usize> = volume
        .cuts
        .iter()
        .enumerate()
        .filter_map(|(cut_index, cut)| {
            cut.moments
                .contains_key(&MomentType::Velocity)
                .then_some(cut_index)
        })
        .collect();
    resolve_dealiased_cut_grids(volume, previous_volume, dealias_env, engine, &cut_indices)
}

/// Resolve only the listed cuts while preserving a volume-aligned result
/// vector. Rotation markers and tracks use their kernel-owned cut selectors so
/// Analyst3d never pays whole-volume solve cost for tilts they will discard.
fn resolve_dealiased_cut_grids(
    volume: &Arc<RadarVolume>,
    previous_volume: Option<&Arc<RadarVolume>>,
    dealias_env: Option<&Arc<EnvironmentalWindProfile>>,
    engine: DealiasEngine,
    cut_indices: &[usize],
) -> Vec<Option<Arc<MomentGrid>>> {
    let mut grids = vec![None; volume.cuts.len()];
    for &cut_index in cut_indices {
        let Some(cut) = volume.cuts.get(cut_index) else {
            continue;
        };
        if cut.moments.contains_key(&MomentType::Velocity) {
            grids[cut_index] =
                resolve_dealiased_grid(volume, previous_volume, dealias_env, cut_index, engine);
        }
    }
    grids
}

