const SIDEBAR_TABS: &[SidebarTab] = &[
    SidebarTab::Radar,
    SidebarTab::Layers,
    SidebarTab::Severe,
    SidebarTab::Data,
    SidebarTab::Settings,
];

fn sidebar_tab_label(tab: SidebarTab, brand: &settings::BrandConfig) -> &str {
    fn non_empty<'a>(value: &'a str, fallback: &'a str) -> &'a str {
        if value.trim().is_empty() {
            fallback
        } else {
            value.trim()
        }
    }
    match tab {
        SidebarTab::Radar => non_empty(&brand.features.radar, "Radar"),
        SidebarTab::Layers => non_empty(&brand.features.map, "Custom"),
        SidebarTab::Severe => non_empty(&brand.features.warnings, "Severe"),
        SidebarTab::Data => "Data",
        SidebarTab::Settings => "⚙",
    }
}

fn sidebar_tab_tooltip(tab: SidebarTab) -> &'static str {
    match tab {
        SidebarTab::Radar => "Site, products, tilt, loop, algorithms — live operations",
        SidebarTab::Layers => {
            "Customization: map layers, added overlays, analysis overlays, radar age, and appearance/color tables"
        }
        SidebarTab::Severe => "Warnings, watches, MDs, SPC outlooks + reports, alert filters",
        SidebarTab::Data => {
            "Acquisition: any date in history, live poll feeds, the model store, local files"
        }
        SidebarTab::Settings => {
            "Settings: display, basemap, alerts, hotkeys, performance, diagnostics"
        }
    }
}

