fn us_state_abbr_for_bbox(bbox: [f32; 4]) -> &'static str {
    let lon = (bbox[0] + bbox[2]) * 0.5;
    let lat = (bbox[1] + bbox[3]) * 0.5;
    US_STATE_ANCHORS
        .iter()
        .min_by(|a, b| {
            haversine_km(lat, lon, a.lat, a.lon).total_cmp(&haversine_km(lat, lon, b.lat, b.lon))
        })
        .map(|anchor| anchor.abbr)
        .unwrap_or("US")
}

