fn us_detail_visible(bounds: GeoBounds) -> bool {
    if !bounds.intersects_bbox(basemap_data::BASEMAP_US_BOUNDS) {
        return false;
    }
    BASEMAP_US_DETAIL_BOUNDS
        .iter()
        .any(|us_bounds| bounds.intersects_bbox(*us_bounds))
}

/// A loaded placefile overlay: URL + parsed content + refresh bookkeeping.
/// Fetch + parse run on background threads; the UI polls a channel.
struct PlacefileSlot {
    url: String,
    enabled: bool,
    /// Draw Text/Place statements (off = icons/lines only).
    show_text: bool,
    data: Option<placefiles::Placefile>,
    /// Bumped on every successful install — exact shape-cache invalidation.
    generation: u64,
    next_refresh: Option<Instant>,
    status: String,
    receiver: Option<mpsc::Receiver<std::result::Result<placefiles::Placefile, String>>>,
    /// Loaded icon sprite sheets (fetched + decoded off-thread, texture
    /// created on install).
    sheets: Vec<PlacefileSheet>,
    sheets_receiver: Option<mpsc::Receiver<Vec<DecodedSheet>>>,
}

/// (sheet index, width, height, rgba) from the fetch/decode thread.
type DecodedSheet = (u32, u32, u32, Vec<u8>);

struct PlacefileSheet {
    spec: placefiles::IconSheetSpec,
    size: (u32, u32),
    texture: egui::TextureHandle,
}

impl PlacefileSlot {
    fn new(url: String, enabled: bool) -> Self {
        Self {
            url,
            enabled,
            show_text: true,
            data: None,
            generation: 0,
            next_refresh: None,
            status: "queued".to_owned(),
            receiver: None,
            sheets: Vec::new(),
            sheets_receiver: None,
        }
    }
}

/// Cached placefile draw geometry: shapes plus live-drawn text labels
/// (position, text, size px, color).
struct PlacefileDrawList {
    shapes: Vec<egui::Shape>,
    labels: Vec<(egui::Pos2, String, f32, egui::Color32)>,
    /// Icon HOVER texts (position, decoded text) — GR semantics: the
    /// Icon statement's trailing string shows on hover only, never as
    /// map text (SpotterNetwork hover cards are paragraphs).
    hovers: Vec<(egui::Pos2, String)>,
}

/// Cached hazard-overlay geometry: fill shapes draw below radar, outlines
/// and label anchors draw above it.
#[derive(Clone)]
struct HazardOverlayShapes {
    fill_shapes: Vec<egui::Shape>,
    outline_shapes: Vec<egui::Shape>,
    labels: Vec<(egui::Pos2, String, bool, usize)>,
}

#[derive(Clone, Debug)]
struct CrossSectionReadout {
    product: DisplayProduct,
    width: usize,
    height: usize,
    top_m: f32,
    length_m: f32,
    values: Vec<f32>,
}

/// Display smoothing mode (Settings ▸ Display ▸ Smoothing). Persisted as a
/// string in `AppSettings::smooth_display_mode`; the legacy
/// `smooth_display` bool maps to `Soften` so old configs keep their look.
/// Which velocity-dealias engine the viewer runs. All three produce a
/// dealiased VEL/DVEL/DSRV grid; they differ in method and cost:
/// - `Region`: the fast same-tilt BowEcho region solver (the default).
/// - `RegionGlobal`: a Rust port of Py-ART's `dealias_region_based`
///   per-sweep core — same-tilt, no volume/model/temporal evidence.
/// - `Analyst3d`: the model-anchored v4 engine (whole-volume branch
///   optimization; uses the previous volume + a RAP wind profile).
///
/// Only `Analyst3d` consumes the previous volume and RAP env profile;
/// `Region` and `RegionGlobal` are pure same-tilt engines. This enum is
/// carried through every render/readout cache key so switching engines
/// invalidates cached textures and readouts.
#[derive(Clone, Copy, Debug, Default, Eq, Hash, Ord, PartialEq, PartialOrd)]
enum DealiasEngine {
    /// Fast same-tilt region unfolding — the app's default.
    #[default]
    Region,
    /// Rust port of Py-ART `dealias_region_based` (same-tilt).
    RegionGlobal,
    /// Model-anchored whole-volume v4 engine.
    Analyst3d,
}

#[derive(Clone, Copy, Debug, Default, Eq, PartialEq)]
enum SmoothingMode {
    /// Raw gates, nearest-gate rendering — the app's identity.
    #[default]
    Native,
    /// 3×3 binomial over the polar grid (the legacy "Smooth display").
    Soften,
    /// Bilinear polar upsampling: synthetic radials/gates between the
    /// native ones (inter-gate interpolation), nearest-gate rendered.
    Interpolated,
}

impl SmoothingMode {
    fn from_settings(settings: &settings::AppSettings) -> Self {
        match settings.smooth_display_mode.as_str() {
            "native" => Self::Native,
            "soften" => Self::Soften,
            "interpolated" => Self::Interpolated,
            // Pre-mode configs: the legacy bool was the binomial pass.
            _ => {
                if settings.smooth_display {
                    Self::Soften
                } else {
                    Self::Native
                }
            }
        }
    }

    fn settings_str(self) -> &'static str {
        match self {
            Self::Native => "native",
            Self::Soften => "soften",
            Self::Interpolated => "interpolated",
        }
    }

    /// The interpolated mode is the only one that changes the GRID
    /// GEOMETRY (more rows/gates) — native and soften share viewport
    /// sample caches, interpolated cannot.
    fn changes_grid_geometry(self) -> bool {
        self == Self::Interpolated
    }
}

fn cross_section_smoothing_from_settings(
    settings: &settings::AppSettings,
) -> CrossSectionSmoothing {
    match settings.cross_section_smoothing.as_str() {
        "native" => CrossSectionSmoothing::Native,
        _ => CrossSectionSmoothing::Smoothed,
    }
}

fn cross_section_smoothing_slug(smoothing: CrossSectionSmoothing) -> &'static str {
    match smoothing {
        CrossSectionSmoothing::Native => "native",
        CrossSectionSmoothing::Smoothed => "smoothed",
    }
}

fn cross_section_smoothing_label(smoothing: CrossSectionSmoothing) -> &'static str {
    match smoothing {
        CrossSectionSmoothing::Native => "Native",
        CrossSectionSmoothing::Smoothed => "Smoothed",
    }
}

#[derive(Clone, Debug, Eq, PartialEq)]
struct TextureKey {
    volume_ptr: usize,
    /// Previous-volume identity participates only in model-anchored (v4)
    /// dealiased renders. It prevents a newly available temporal reference
    /// from reusing an older region-only texture for the same current volume.
    dealias_reference_volume_ptr: usize,
    /// RAP profile identity (Arc pointer; 0 = none), same contract as the
    /// previous-volume pointer above: when the background profile fetch
    /// lands, renders produced without the model anchor stop matching.
    dealias_env_ptr: usize,
    cut: usize,
    product: DisplayProduct,
    render_dealiased_velocity: bool,
    color_table_signature: u64,
    storm_motion_key: (i16, i16),
    hail_levels_key: (i16, i16),
    smoothing: SmoothingMode,
    dealias_engine: DealiasEngine,
    gate_filter_decidbz: i16,
    viewport: ViewportKey,
}

fn texture_keys_match_data_and_style(left: &TextureKey, right: &TextureKey) -> bool {
    left.volume_ptr == right.volume_ptr
        && left.dealias_reference_volume_ptr == right.dealias_reference_volume_ptr
        && left.dealias_env_ptr == right.dealias_env_ptr
        && left.cut == right.cut
        && left.product == right.product
        && left.render_dealiased_velocity == right.render_dealiased_velocity
        && left.color_table_signature == right.color_table_signature
        && left.storm_motion_key == right.storm_motion_key
        && left.hail_levels_key == right.hail_levels_key
        && left.smoothing == right.smoothing
        && left.dealias_engine == right.dealias_engine
        && left.gate_filter_decidbz == right.gate_filter_decidbz
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
struct ViewportKey {
    width: u32,
    height: u32,
    radar_x_px: i32,
    radar_y_px: i32,
    km_per_px_x: i32,
    km_per_px_y: i32,
    /// Quantized AEQD convergence baked into the raster (millradians).
    rotation_mrad: i16,
}

impl ViewportKey {
    fn dimensions(&self) -> (u32, u32) {
        (self.width, self.height)
    }
}

/// Paint a texture as a quad rotated by `angle` about `pivot` — used to
/// align the planar-ENU radar raster with the AEQD screen frame at draw time
/// (zero per-pixel cost; the raster itself is rotation-agnostic).
/// Rotation baked into a rendered texture, from its viewport key.
fn pane_or_key_rotation_rad(key: &Option<TextureKey>) -> f32 {
    key.as_ref()
        .map(|key| key.viewport.rotation_mrad as f32 / 1000.0)
        .unwrap_or(0.0)
}

/// Coordinate line in Solarpower07's loupe convention: absolute degrees with a
/// hemisphere letter, e.g. `39.322N, 83.959W`.
fn format_lat_lon(lat: f32, lon: f32) -> String {
    let ns = if lat >= 0.0 { 'N' } else { 'S' };
    let ew = if lon >= 0.0 { 'E' } else { 'W' };
    format!("{:.3}{}, {:.3}{}", lat.abs(), ns, lon.abs(), ew)
}

/// `#RRGGBB` card line for a sampled color, with a 3-space gutter reserved for
/// the color chip drawn over it.
fn hex_rgb_line(rgba: [u8; 4]) -> String {
    format!("   #{:02X}{:02X}{:02X}", rgba[0], rgba[1], rgba[2])
}

fn anchored_radar_texture_rect(
    rect: egui::Rect,
    pixels_per_point: f32,
    rendered: ViewportKey,
    current: ViewportRasterOptions,
) -> egui::Rect {
    let pixels_per_point = pixels_per_point.max(1.0);
    let rendered_radar_x_px = rendered.radar_x_px as f32 / 8.0;
    let rendered_radar_y_px = rendered.radar_y_px as f32 / 8.0;
    let rendered_km_per_px_x = rendered.km_per_px_x as f32 / 1_000_000.0;
    let rendered_km_per_px_y = rendered.km_per_px_y as f32 / 1_000_000.0;
    let scale_x = positive_ratio(rendered_km_per_px_x, current.km_per_px_x);
    let scale_y = positive_ratio(rendered_km_per_px_y, current.km_per_px_y);
    let left_px = current.radar_x_px - rendered_radar_x_px * scale_x;
    let top_px = current.radar_y_px - rendered_radar_y_px * scale_y;
    egui::Rect::from_min_size(
        egui::pos2(
            rect.left() + left_px / pixels_per_point,
            rect.top() + top_px / pixels_per_point,
        ),
        egui::vec2(
            rendered.width as f32 * scale_x / pixels_per_point,
            rendered.height as f32 * scale_y / pixels_per_point,
        ),
    )
}

fn positive_ratio(numerator: f32, denominator: f32) -> f32 {
    if numerator.is_finite() && denominator.is_finite() && numerator > 0.0 && denominator > 0.0 {
        numerator / denominator
    } else {
        1.0
    }
}

/// Where the last-rendered satellite raster lands in the CURRENT view — the
/// satellite twin of [`anchored_radar_texture_rect`]. The raster filled the
/// whole map rect when it was rendered, centered on the render view's
/// center, so it is re-anchored at that geo point's current screen position
/// and scaled by the zoom ratio (`texture_pts` is the raster's size in
/// points, i.e. the map rect at render time). AEQD azimuth rotation between
/// the two view centers is deliberately ignored: this rect only bridges an
/// active pan/zoom gesture web-map style, and the exact re-render replaces
/// it as soon as the view settles. Degenerate views produce a non-finite
/// rect the caller must skip.
fn anchored_sat_texture_rect(
    rect: egui::Rect,
    texture_pts: egui::Vec2,
    rendered: &ModelLayerView,
    current: &ModelLayerView,
) -> egui::Rect {
    let scale = positive_ratio(current.map_scale, rendered.map_scale);
    let (east_km, north_km) = aeqd_forward_km(
        current.center_lat as f64,
        current.center_lon as f64,
        rendered.center_lat as f64,
        rendered.center_lon as f64,
    );
    let px_per_km = current.map_scale / 111.32;
    let center = egui::pos2(
        rect.center().x + east_km as f32 * px_per_km,
        rect.center().y - north_km as f32 * px_per_km,
    );
    egui::Rect::from_center_size(center, texture_pts * scale)
}

fn radar_age_glyph_arc_points(
    center: egui::Pos2,
    volume_time_utc: DateTime<Utc>,
    now_utc: DateTime<Utc>,
    age_style: &styles::RadarAgeStyle,
) -> Vec<egui::Pos2> {
    let sweep_fraction = radar_age_glyph_arc_sweep_fraction(volume_time_utc, now_utc, age_style);
    if sweep_fraction <= f32::EPSILON {
        return Vec::new();
    }
    let radius = if age_style.glyph_arc_radius_px.is_finite() {
        age_style.glyph_arc_radius_px.clamp(4.0, 48.0)
    } else {
        styles::RadarAgeStyle::default().glyph_arc_radius_px
    };
    let segments = ((48.0 * sweep_fraction).ceil() as usize).clamp(2, 48);
    let sweep = std::f32::consts::TAU * sweep_fraction;
    (0..=segments)
        .map(|index| {
            let angle = sweep * index as f32 / segments as f32;
            egui::pos2(
                center.x + radius * angle.sin(),
                center.y - radius * angle.cos(),
            )
        })
        .collect()
}

fn radar_age_glyph_arc_sweep_fraction(
    volume_time_utc: DateTime<Utc>,
    now_utc: DateTime<Utc>,
    age_style: &styles::RadarAgeStyle,
) -> f32 {
    let age_seconds = now_utc
        .signed_duration_since(volume_time_utc)
        .num_seconds()
        .max(0) as f32;
    let red_seconds = age_style.red_seconds.max(1) as f32;
    (age_seconds / red_seconds).clamp(0.0, 1.0)
}

/// Scan-age ring color: green → yellow → red → dark-red across the style's
/// thresholds (defaults 6/10/15 min). Thresholds AND colors come from the
/// radar-age style group so the gradient is one customization shared by
/// every age-coloring surface.
fn freshness_ring_color(
    volume_time_utc: DateTime<Utc>,
    now_utc: DateTime<Utc>,
    alpha: u8,
    age_style: &styles::RadarAgeStyle,
) -> egui::Color32 {
    let age_seconds = now_utc
        .signed_duration_since(volume_time_utc)
        .num_seconds()
        .max(0);
    let fresh = (
        age_style.fresh_color[0],
        age_style.fresh_color[1],
        age_style.fresh_color[2],
    );
    let aging = (
        age_style.aging_color[0],
        age_style.aging_color[1],
        age_style.aging_color[2],
    );
    let stale = (
        age_style.stale_color[0],
        age_style.stale_color[1],
        age_style.stale_color[2],
    );
    let expired = (
        age_style.expired_color[0],
        age_style.expired_color[1],
        age_style.expired_color[2],
    );
    let (start, end, t) = if age_seconds <= age_style.green_seconds {
        (fresh, fresh, 0.0)
    } else if age_seconds <= age_style.yellow_seconds {
        (
            fresh,
            aging,
            ratio_between(
                age_seconds,
                age_style.green_seconds,
                age_style.yellow_seconds,
            ),
        )
    } else if age_seconds <= age_style.red_seconds {
        (
            aging,
            stale,
            ratio_between(age_seconds, age_style.yellow_seconds, age_style.red_seconds),
        )
    } else {
        (stale, expired, 1.0)
    };
    let (r, g, b) = lerp_rgb(start, end, t);
    egui::Color32::from_rgba_unmultiplied(r, g, b, alpha)
}

fn ratio_between(value: i64, start: i64, end: i64) -> f32 {
    if end <= start {
        return 1.0;
    }
    ((value - start) as f32 / (end - start) as f32).clamp(0.0, 1.0)
}

fn lerp_rgb(start: (u8, u8, u8), end: (u8, u8, u8), t: f32) -> (u8, u8, u8) {
    (
        lerp_u8(start.0, end.0, t),
        lerp_u8(start.1, end.1, t),
        lerp_u8(start.2, end.2, t),
    )
}

fn lerp_u8(start: u8, end: u8, t: f32) -> u8 {
    (start as f32 + (end as f32 - start as f32) * t.clamp(0.0, 1.0)).round() as u8
}

fn site_location(site: &RadarSite) -> Option<(f32, f32)> {
    Some((site.latitude_deg?, site.longitude_deg?))
}

fn community_feed_site(feed: &data_source::community_feeds::CommunityFeed) -> RadarSite {
    RadarSite::new(feed.id).with_location(
        Some(format!("{}{}", feed.label, COMMUNITY_FEED_SITE_NAME_SUFFIX)),
        Some(feed.latitude_deg),
        Some(feed.longitude_deg),
    )
}

fn site_catalog_with_community_feeds(mut sites: Vec<RadarSite>) -> Vec<RadarSite> {
    let mut existing = sites
        .iter()
        .map(|site| site.level2_id.to_ascii_uppercase())
        .collect::<BTreeSet<_>>();
    for feed in data_source::community_feeds::community_feeds() {
        if existing.insert(feed.id.to_ascii_uppercase()) {
            sites.push(community_feed_site(feed));
        }
    }
    sites.sort_by(|left, right| left.level2_id.cmp(&right.level2_id));
    sites
}

fn community_feed_for_site(
    site: &RadarSite,
) -> Option<&'static data_source::community_feeds::CommunityFeed> {
    if !site
        .name
        .as_deref()
        .is_some_and(|name| name.ends_with(COMMUNITY_FEED_SITE_NAME_SUFFIX))
    {
        return None;
    }
    data_source::community_feeds::community_feeds()
        .iter()
        .find(|feed| feed.id.eq_ignore_ascii_case(&site.level2_id))
}

/// The poll source a fresh session restores from the persisted display
/// owner (v0.29 Phase 3 §1.4): a resolvable international owner re-arms
/// its provider/site — poll NOT active, nothing auto-starts at startup,
/// exactly the armed-resume posture the layers rail already offers — so
/// the archive browser, Event Loop Builder, and Reset View all resume on
/// the owner. Anything else (absent key, bare US id, stale intl ref)
/// keeps the legacy CustomUrl seed. Pure over settings for testing.
fn restored_primary_feed(app_settings: &settings::AppSettings) -> FeedSource {
    if let Some(key) = app_settings.display_owner_site.as_deref()
        && let SiteRef::Intl {
            provider_id,
            site_id,
        } = SiteRef::parse_settings_key(key)
        && data_source::sites::resolve(&SiteRef::Intl {
            provider_id: provider_id.clone(),
            site_id: site_id.clone(),
        })
        .is_some()
    {
        return FeedSource::Live(SiteRef::Intl {
            provider_id,
            site_id,
        });
    }
    FeedSource::CustomUrl(app_settings.poll_url.clone())
}

/// Grouped "International" section for a SITE combo (v0.29 Phase 3: both
/// worlds in one picker): every provider's sites under a provenance
/// header, in catalog/registry order, from the one union catalog.
fn intl_site_combo_section(ui: &mut egui::Ui, selected: &mut Option<SiteRef>) {
    let mut last_origin: Option<String> = None;
    for record in data_source::sites::all_sites() {
        let SiteKind::Intl { .. } = record.kind else {
            continue;
        };
        if last_origin != record.origin {
            ui.separator();
            if let Some(origin) = record.origin.as_deref() {
                ui.label(egui::RichText::new(origin).small().strong());
            }
            last_origin = record.origin.clone();
        }
        ui.selectable_value(selected, Some(record.site.clone()), record.label.clone());
    }
}

/// Honesty tag for a velocity product render, drawn under the mode chip —
/// the one spot where the displayed product's data quality must never lie.
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum VelocityQualityTag {
    /// Product is labeled dealiased (DVEL/DSRV or unfolded VEL) but the
    /// feed carries no Nyquist velocity, so the dealiaser was a pure
    /// pass-through (JMA always by design — staggered PRF; occasional
    /// ODIM files omit how/NI) and the fold warning can never fire.
    NoNyquistPassThrough,
    /// ORD ODIM velocity dealiased in-app (provenance chip).
    DealiasedLocally,
    /// Raw signed radial velocity render: folds possible.
    RawFoldsPossible,
}

impl VelocityQualityTag {
    fn label(self) -> &'static str {
        match self {
            Self::NoNyquistPassThrough => "no Nyquist in this feed — showing raw velocity",
            Self::DealiasedLocally => "VRADH dealiased locally",
            Self::RawFoldsPossible => "RAW VEL — folds possible",
        }
    }
}

/// Pure tag derivation (None = no tag). `dealias_skipped_no_nyquist` is
/// the render2d query over the displayed cut's velocity grid; the
/// pass-through disclosure outranks the ORD provenance chip because a
/// "dealiased" label over raw data is the bigger lie.
fn velocity_quality_tag(
    renders_dealiased: bool,
    is_signed_velocity: bool,
    dealias_skipped_no_nyquist: bool,
    provider_id: Option<&str>,
) -> Option<VelocityQualityTag> {
    if renders_dealiased {
        if dealias_skipped_no_nyquist {
            return Some(VelocityQualityTag::NoNyquistPassThrough);
        }
        if matches!(provider_id, Some("ord")) {
            return Some(VelocityQualityTag::DealiasedLocally);
        }
        return None;
    }
    if is_signed_velocity {
        return Some(VelocityQualityTag::RawFoldsPossible);
    }
    None
}

/// The map-marker catalogs a click can land on.
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum MarkerFamily {
    /// `self.sites` — the NEXRAD site list (click selects the site).
    Conus,
    /// `data_source::international::intl_static_sites` (click live-polls).
    Intl,
    /// `data_source::community_feeds::community_markers` (click live-polls
    /// a direct feed, or opens the shared-pad cluster picker).
    Community,
    /// `AppSettings::custom_poll_links` (click live-polls the saved URL).
    CustomPoll,
    /// `ViewerApp::raob_marker_sites` — RAOB launch sites (click fetches
    /// the observed sounding at the displayed time). Its visible diamond is
    /// the topmost click target; outside that core it ranks after radar/feed
    /// markers.
    Raob,
}

fn site_is_terminal_radar(site: &RadarSite) -> bool {
    site_id_is_terminal_radar(&site.level2_id)
}

fn site_id_is_terminal_radar(site_id: &str) -> bool {
    site_id
        .as_bytes()
        .first()
        .is_some_and(|byte| byte.eq_ignore_ascii_case(&b'T'))
}

fn grid_range_km(grid: &MomentGrid) -> Option<f32> {
    let first_gate_m = grid.gate_range.first_gate_m.max(0) as f32;
    let gate_spacing_m = grid.gate_range.gate_spacing_m.max(0) as f32;
    let range_km = (first_gate_m + gate_spacing_m * grid.gate_range.gate_count as f32) / 1000.0;
    (range_km > 0.0).then_some(range_km)
}

fn gate_for_range(grid: &MomentGrid, range_km: f32) -> Option<usize> {
    let spacing_m = grid.gate_range.gate_spacing_m.max(1) as f32;
    let gate = ((range_km * 1000.0 - grid.gate_range.first_gate_m as f32) / spacing_m).round();
    if gate < 0.0 || gate as usize >= grid.gate_range.gate_count {
        return None;
    }
    Some(gate as usize)
}

fn nearest_finite_grid_sample(
    grid: &MomentGrid,
    center_row: usize,
    center_gate: usize,
    max_radius: usize,
) -> Option<(usize, usize, f32)> {
    let rows = grid.radial_count();
    let gates = grid.gate_range.gate_count;
    if rows == 0 || gates == 0 || center_gate >= gates {
        return None;
    }
    for radius in 0..=max_radius {
        let mut best: Option<(usize, usize, usize, f32)> = None;
        let radius = radius as isize;
        for row_delta in -radius..=radius {
            for gate_delta in -radius..=radius {
                if row_delta.abs().max(gate_delta.abs()) != radius {
                    continue;
                }
                let gate = center_gate as isize + gate_delta;
                if gate < 0 || gate as usize >= gates {
                    continue;
                }
                let row = (center_row as isize + row_delta).rem_euclid(rows as isize) as usize;
                let gate = gate as usize;
                let Some(value) = grid
                    .scaled_value(row, gate)
                    .filter(|value| value.is_finite())
                else {
                    continue;
                };
                let distance_sq = (row_delta * row_delta + gate_delta * gate_delta) as usize;
                if best.as_ref().is_none_or(|current| {
                    (distance_sq, row, gate) < (current.0, current.1, current.2)
                }) {
                    best = Some((distance_sq, row, gate, value));
                }
            }
        }
        if let Some((_, row, gate, value)) = best {
            return Some((row, gate, value));
        }
    }
    None
}

fn nearest_grid_row(
    cut: &ElevationCut,
    grid: &MomentGrid,
    azimuth_deg: f32,
) -> Option<(usize, usize)> {
    let row_count = grid.radial_indices.len();
    if row_count == 0 {
        return None;
    }
    let threshold_deg = (360.0 / row_count as f32 * 0.55).clamp(0.35, 0.8);
    grid.radial_indices
        .iter()
        .enumerate()
        .filter_map(|(row, radial_index)| {
            let radial = cut.radials.get(*radial_index)?;
            let delta = angle_delta_deg(azimuth_deg, radial.azimuth_deg);
            (delta <= threshold_deg).then_some((row, *radial_index, delta))
        })
        .min_by(|left, right| left.2.total_cmp(&right.2))
        .map(|(row, radial_index, _)| (row, radial_index))
}

fn grid_raw_value(grid: &MomentGrid, row: usize, gate: usize) -> Option<u16> {
    let index = row
        .checked_mul(grid.gate_range.gate_count)?
        .checked_add(gate)?;
    match &grid.storage {
        MomentStorage::U8(values) => values.get(index).map(|value| u16::from(*value)),
        MomentStorage::U16(values) => values.get(index).copied(),
        MomentStorage::F32(_) => None,
    }
}

fn velocity_vrot_probe(
    cut: &ElevationCut,
    grid: &MomentGrid,
    center_row: usize,
    center_gate: usize,
    product: &DisplayProduct,
    storm_motion: StormMotion,
) -> Option<VrotProbe> {
    if !product.is_signed_radial_velocity() {
        return None;
    }
    if grid.gate_range.gate_count == 0 || grid.radial_indices.is_empty() {
        return None;
    }

    let row_count = grid.radial_indices.len();
    let gate_start = center_gate.saturating_sub(VROT_GATE_RADIUS);
    let gate_end = center_gate
        .saturating_add(VROT_GATE_RADIUS)
        .min(grid.gate_range.gate_count - 1);
    let mut inbound: Option<VelocitySample> = None;
    let mut outbound: Option<VelocitySample> = None;

    for row_delta in -(VROT_ROW_RADIUS as isize)..=(VROT_ROW_RADIUS as isize) {
        let row = (center_row as isize + row_delta).rem_euclid(row_count as isize) as usize;
        for gate in gate_start..=gate_end {
            let Some(sample) = velocity_sample(cut, grid, row, gate, product, storm_motion) else {
                continue;
            };
            if sample.value_mps < 0.0
                && inbound
                    .map(|current| sample.value_mps < current.value_mps)
                    .unwrap_or(true)
            {
                inbound = Some(sample);
            } else if sample.value_mps > 0.0
                && outbound
                    .map(|current| sample.value_mps > current.value_mps)
                    .unwrap_or(true)
            {
                outbound = Some(sample);
            }
        }
    }

    let inbound = inbound?;
    let outbound = outbound?;
    let delta_v_mps = outbound.value_mps - inbound.value_mps;
    let separation_km = (outbound.x_km - inbound.x_km).hypot(outbound.y_km - inbound.y_km);
    Some(VrotProbe {
        delta_v_mps,
        vrot_mps: delta_v_mps.abs() * 0.5,
        separation_km,
        inbound: inbound.vrot_gate(),
        outbound: outbound.vrot_gate(),
    })
}

#[derive(Clone, Copy)]
struct VelocitySample {
    row: usize,
    gate: usize,
    value_mps: f32,
    azimuth_deg: f32,
    x_km: f32,
    y_km: f32,
}

impl VelocitySample {
    fn vrot_gate(self) -> VrotGate {
        VrotGate {
            row: self.row,
            gate: self.gate,
            value_mps: self.value_mps,
            azimuth_deg: self.azimuth_deg,
        }
    }
}

fn velocity_sample(
    cut: &ElevationCut,
    grid: &MomentGrid,
    row: usize,
    gate: usize,
    product: &DisplayProduct,
    storm_motion: StormMotion,
) -> Option<VelocitySample> {
    let radial_index = *grid.radial_indices.get(row)?;
    let radial = cut.radials.get(radial_index)?;
    let base_velocity_mps = grid.scaled_value(row, gate)?;
    let value_mps = if product.is_storm_relative_velocity() {
        storm_relative_velocity_mps(base_velocity_mps, radial.azimuth_deg, storm_motion)
    } else {
        base_velocity_mps
    };
    let range_km = gate_center_range_km(grid, gate);
    let azimuth_rad = radial.azimuth_deg.to_radians();
    Some(VelocitySample {
        row,
        gate,
        value_mps,
        azimuth_deg: radial.azimuth_deg,
        x_km: range_km * azimuth_rad.sin(),
        y_km: range_km * azimuth_rad.cos(),
    })
}

fn gate_center_range_km(grid: &MomentGrid, gate: usize) -> f32 {
    let first_gate_m = grid.gate_range.first_gate_m.max(0) as f32;
    let spacing_m = grid.gate_range.gate_spacing_m.max(1) as f32;
    (first_gate_m + spacing_m * gate as f32) / 1000.0
}

fn default_hidden_hazard_families() -> BTreeSet<String> {
    HAZARD_FILTER_FAMILIES
        .iter()
        .filter(|(family, _)| !DEFAULT_VISIBLE_HAZARD_FAMILIES.contains(family))
        .map(|(family, _)| (*family).to_owned())
        .collect()
}

fn normalize_alert_family(family: &str) -> String {
    family.trim().to_ascii_lowercase()
}

fn alert_family_enabled(configured: &[String], family: &str) -> bool {
    if configured.is_empty() {
        return true;
    }
    let family = normalize_alert_family(family);
    configured
        .iter()
        .any(|configured| normalize_alert_family(configured) == family)
}

fn set_alert_family_enabled(configured: &mut Vec<String>, family: &str, enabled: bool) {
    let family = normalize_alert_family(family);
    let mut selected = if configured.is_empty() {
        ALERT_SOUND_FAMILY_OPTIONS
            .iter()
            .map(|(slug, _)| (*slug).to_owned())
            .collect::<BTreeSet<_>>()
    } else {
        configured
            .iter()
            .map(|family| normalize_alert_family(family))
            .collect::<BTreeSet<_>>()
    };
    if enabled {
        selected.insert(family);
    } else {
        selected.remove(&family);
    }
    let all_selected = ALERT_SOUND_FAMILY_OPTIONS
        .iter()
        .all(|(slug, _)| selected.contains(*slug));
    configured.clear();
    if all_selected {
        return;
    }
    configured.extend(
        ALERT_SOUND_FAMILY_OPTIONS
            .iter()
            .filter(|(slug, _)| selected.contains(*slug))
            .map(|(slug, _)| (*slug).to_owned()),
    );
}

fn parse_color_table_for_family(
    family: ColorTableFamily,
    name: &str,
    text: &str,
) -> Result<ColorTable, color_tables::ColorTableError> {
    // User .pal files get faithful GR2Analyst semantics for every family:
    // solid/gradient intervals, color4 alpha, Step: as legend ticks only —
    // a community-loaded table must look exactly like it does in GR2A.
    let _ = family;
    ColorTable::parse_gr_pal(name, text)
}

/// Scan `settings::color_tables_dir()` for user `.pal` files ("My tables").
/// Family comes from the file's `Product:` header (unknown/missing →
/// Generic; the picker offers user tables across families anyway, since
/// community files often omit or mislabel it). Unparseable files are
/// skipped — a broken download must never block startup.
fn scan_user_color_tables(dir: &Path) -> Vec<(ColorTableFamily, ColorTable)> {
    let mut out = Vec::new();
    let Ok(entries) = std::fs::read_dir(dir) else {
        return out;
    };
    let mut paths: Vec<PathBuf> = entries
        .flatten()
        .map(|entry| entry.path())
        .filter(|path| {
            path.extension()
                .and_then(|ext| ext.to_str())
                .is_some_and(|ext| ext.eq_ignore_ascii_case("pal"))
        })
        .collect();
    paths.sort();
    for path in paths {
        let Ok(text) = std::fs::read_to_string(&path) else {
            continue;
        };
        let name = path
            .file_stem()
            .and_then(|stem| stem.to_str())
            .filter(|stem| !stem.is_empty())
            .unwrap_or("User table");
        if let Ok(table) = ColorTable::parse_gr_pal(name, &text) {
            let family = table
                .product()
                .map(color_tables::family_for_product_code)
                .unwrap_or(ColorTableFamily::Generic);
            out.push((family, table));
        }
    }
    out
}

/// Resolve a persisted table name for a family: built-ins first, then user
/// tables by name regardless of their declared family (the user picked it).
fn resolve_palette_binding(
    family: ColorTableFamily,
    name: &str,
    user_tables: &[(ColorTableFamily, ColorTable)],
) -> Option<ColorTable> {
    builtin_tables_for_family(family)
        .into_iter()
        .find(|table| table.name() == name)
        .or_else(|| {
            user_tables
                .iter()
                .find(|(_, table)| table.name() == name)
                .map(|(_, table)| table.clone())
        })
}

/// Resolve a table name with no family hint (per-product bindings):
/// every family's built-ins ∪ user tables.
fn resolve_table_by_name(
    name: &str,
    user_tables: &[(ColorTableFamily, ColorTable)],
) -> Option<ColorTable> {
    ColorTableFamily::ALL
        .into_iter()
        .find_map(|family| {
            builtin_tables_for_family(family)
                .into_iter()
                .find(|table| table.name() == name)
        })
        .or_else(|| {
            user_tables
                .iter()
                .find(|(_, table)| table.name() == name)
                .map(|(_, table)| table.clone())
        })
}

/// Apply saved family bindings to the live set. Misses (deleted tables,
/// unknown labels) leave the default in place and return a status line —
/// the boot path logs them to `color_table_status`.
fn restore_palette_bindings(
    color_tables: &mut ColorTableSet,
    bindings: &BTreeMap<String, String>,
    user_tables: &[(ColorTableFamily, ColorTable)],
) -> Vec<String> {
    let mut misses = Vec::new();
    for (label, name) in bindings {
        let Some(family) = ColorTableFamily::from_label(label) else {
            misses.push(format!("Unknown color family \"{label}\" in config.json"));
            continue;
        };
        match resolve_palette_binding(family, name, user_tables) {
            Some(table) => color_tables.set_family(family, table),
            None => misses.push(format!(
                "Saved table \"{name}\" for {label} not found; using the default"
            )),
        }
    }
    misses
}

/// Resolve `palette_by_product` names to concrete tables for render-time
/// injection; misses are reported and skipped.
fn resolve_product_palette_overrides(
    bindings: &BTreeMap<String, String>,
    user_tables: &[(ColorTableFamily, ColorTable)],
) -> (BTreeMap<String, ColorTable>, Vec<String>) {
    let mut overrides = BTreeMap::new();
    let mut misses = Vec::new();
    for (product_label, name) in bindings {
        match resolve_table_by_name(name, user_tables) {
            Some(table) => {
                overrides.insert(product_label.clone(), table);
            }
            None => misses.push(format!(
                "Saved table \"{name}\" for product {product_label} not found; using the family table"
            )),
        }
    }
    (overrides, misses)
}

fn color_table_summary(table: &ColorTable) -> String {
    let range = table
        .stops()
        .first()
        .zip(table.stops().last())
        .map(|(first, last)| format!("range {:.1}..{:.1}", first.value, last.value))
        .unwrap_or_else(|| "range unavailable".to_owned());
    let mode = color_table_mode_summary(table);
    format!(
        "{} stops, {}, {}, {range}",
        table.stops().len(),
        mode,
        color_table_units_summary(table)
    )
}

fn color_table_mode_summary(table: &ColorTable) -> String {
    table
        .step_size()
        .map(|step| format!("{}, step {:.2}", table.sample_mode_label(), step))
        .unwrap_or_else(|| table.sample_mode_label().to_owned())
}

fn color_table_units_summary(table: &ColorTable) -> String {
    let Some(units) = table
        .units()
        .map(str::trim)
        .filter(|units| !units.is_empty())
    else {
        return "units unknown, assuming native".to_owned();
    };
    match units.to_ascii_lowercase().as_str() {
        "kt" | "kts" | "knot" | "knots" | "mph" | "mi/h" => {
            format!("units {units} -> m/s")
        }
        _ => format!("units {units}"),
    }
}

fn hazard_record_is_active_or_pending(record: &HazardRecord) -> bool {
    matches!(
        record.lifecycle_status.as_deref(),
        Some("Active") | Some("Pending") | None
    )
}

fn live_hazard_record_is_current(record: &HazardRecord) -> bool {
    matches!(
        record.lifecycle_status.as_deref(),
        Some("Active") | Some("Pending")
    )
}

fn preview_retained_hazard_records(overlay: &HazardOverlay) -> Vec<HazardRecord> {
    overlay
        .records
        .iter()
        .filter(|record| record.event_family == "mesoscale discussion")
        .filter(|record| live_hazard_record_is_current(record))
        .cloned()
        .collect()
}

fn active_alert_event_ids(records: &[HazardRecord]) -> BTreeSet<String> {
    records
        .iter()
        .filter(|record| hazard_record_is_weather_gov_alert(record))
        .filter(|record| live_hazard_record_is_current(record))
        .map(|record| base_hazard_event_id(&record.event_id).to_owned())
        .collect()
}

fn hazard_record_is_weather_gov_alert(record: &HazardRecord) -> bool {
    record.action == "ALERT"
        || record
            .source_url
            .as_deref()
            .is_some_and(|url| url.contains("api.weather.gov/alerts"))
}

fn live_hazard_record_has_authoritative_source(
    record: &HazardRecord,
    active_alert_event_ids: &BTreeSet<String>,
) -> bool {
    !live_warning_requires_active_alert(record)
        || (hazard_record_is_weather_gov_alert(record)
            && active_alert_event_ids.contains(base_hazard_event_id(&record.event_id)))
}

fn hazard_record_shadowed_by_active_alert(
    record: &HazardRecord,
    active_alert_event_ids: &BTreeSet<String>,
) -> bool {
    live_warning_requires_active_alert(record)
        && !hazard_record_is_weather_gov_alert(record)
        && active_alert_event_ids.contains(base_hazard_event_id(&record.event_id))
}

fn live_warning_requires_active_alert(record: &HazardRecord) -> bool {
    matches!(
        record.event_family.as_str(),
        "tornado"
            | "severe thunderstorm"
            | "flash flood"
            | "flood"
            | "fire weather"
            | "special marine"
            | "snow squall"
    )
}

fn parse_hazard_record_time(value: &Option<String>) -> Option<DateTime<Utc>> {
    value
        .as_deref()
        .and_then(|value| DateTime::parse_from_rfc3339(value).ok())
        .map(|time| time.with_timezone(&Utc))
}

fn event_loop_hazard_record_intersects_window(
    record: &HazardRecord,
    start_utc: DateTime<Utc>,
    end_utc: DateTime<Utc>,
) -> bool {
    let Some(start) = parse_hazard_record_time(&record.valid_start) else {
        return false;
    };
    let Some(end) = parse_hazard_record_time(&record.valid_end) else {
        return false;
    };
    start <= end_utc && end >= start_utc
}

fn event_loop_hazard_record_valid_at(record: &HazardRecord, time_utc: DateTime<Utc>) -> bool {
    let Some(start) = parse_hazard_record_time(&record.valid_start) else {
        return false;
    };
    let Some(end) = parse_hazard_record_time(&record.valid_end) else {
        return false;
    };
    start <= time_utc && time_utc < end
}

fn report_visible_at_timeline_time(
    report_time_utc: DateTime<Utc>,
    frame_time_utc: DateTime<Utc>,
) -> bool {
    let lead = chrono::Duration::seconds(TIMELINE_REPORT_LEAD_SECONDS);
    let trail = chrono::Duration::minutes(TIMELINE_REPORT_TRAILING_MINUTES);
    let age = frame_time_utc - report_time_utc;
    age >= -lead && age <= trail
}

fn mping_draw_priority(report: &mping::MpingReport, now: DateTime<Utc>) -> i64 {
    let category_score = match report.category.as_str() {
        "Hail" | "Wind" | "Wind/Storm Damage" | "Storm Damage" | "Flood" => 5,
        "Reduced Visibility" | "Winter Weather Impacts" => 3,
        "Rain/Snow" => 2,
        "None" => 0,
        _ => 1,
    };
    let age_min = (now - report.obtime)
        .num_minutes()
        .clamp(0, TIMELINE_REPORT_TRAILING_MINUTES);
    category_score * 1_000 + (TIMELINE_REPORT_TRAILING_MINUTES - age_min)
}

fn base_hazard_event_id(event_id: &str) -> &str {
    event_id.split_once('#').map_or(event_id, |(base, _)| base)
}

fn fixed_height_scroll(
    ui: &mut egui::Ui,
    id: &'static str,
    height: f32,
    add_contents: impl FnOnce(&mut egui::Ui),
) {
    let width = ui.available_width();
    ui.allocate_ui_with_layout(
        egui::vec2(width, height),
        egui::Layout::top_down(egui::Align::LEFT),
        |ui| {
            ui.set_min_size(egui::vec2(width, height));
            egui::ScrollArea::vertical()
                .id_salt(id)
                .auto_shrink([false, false])
                .max_height(height)
                .show(ui, |ui| {
                    ui.set_width(width);
                    add_contents(ui);
                });
        },
    );
}

fn wrapped_label(ui: &mut egui::Ui, text: &str) {
    ui.add(egui::Label::new(text).wrap());
}

fn fixed_action_button(ui: &mut egui::Ui, label: &str, width: f32) -> egui::Response {
    ui.add_sized(
        egui::vec2(width, PANEL_BUTTON_HEIGHT),
        egui::Button::new(label),
    )
}

fn fixed_disabled_action_button(
    ui: &mut egui::Ui,
    enabled: bool,
    label: &str,
    width: f32,
) -> egui::Response {
    ui.add_enabled_ui(enabled, |ui| fixed_action_button(ui, label, width))
        .inner
}

fn fixed_status_label_with_sense(
    ui: &mut egui::Ui,
    text: &str,
    width: f32,
    sense: egui::Sense,
) -> egui::Response {
    let (rect, _) = ui.allocate_exact_size(egui::vec2(width, PANEL_BUTTON_HEIGHT), sense);
    ui.put(rect, egui::Label::new(text).truncate().sense(sense))
}

fn fixed_state_dot(ui: &mut egui::Ui, color: egui::Color32, hover_text: &str) {
    let (rect, response) =
        ui.allocate_exact_size(egui::vec2(14.0, PANEL_BUTTON_HEIGHT), egui::Sense::hover());
    ui.painter().circle_filled(rect.center(), 4.0, color);
    response.on_hover_text(hover_text);
}

fn layer_state_color(state: &str) -> egui::Color32 {
    match state {
        "loading" => egui::Color32::from_rgb(238, 218, 62),
        "live" => LIVE_COLOR,
        "stale" => egui::Color32::from_rgb(225, 164, 56),
        _ => egui::Color32::from_rgb(106, 132, 154),
    }
}

pub(crate) fn glm_satellite_for_lon(lon: f32) -> Option<&'static str> {
    let lon = normalize_lon(lon);
    if (-180.0..=-100.0).contains(&lon) {
        Some("goes18")
    } else if (-110.0..=15.0).contains(&lon) {
        Some("goes19")
    } else {
        None
    }
}

pub(crate) fn glm_satellite_label(satellite: &str) -> &'static str {
    match satellite {
        "goes18" => "GOES-West",
        "goes19" => "GOES-East",
        _ => "GOES GLM",
    }
}

pub(crate) const GLM_LIVE_MAX_AGE_MINUTES: i64 = 5;

pub(crate) fn glm_latest_age_minutes(frame_ms: i64, latest_ms: i64) -> i64 {
    frame_ms.saturating_sub(latest_ms).max(0) / 60_000
}

pub(crate) fn glm_latest_is_live(frame_ms: i64, latest_ms: i64) -> bool {
    frame_ms.saturating_sub(latest_ms).max(0) <= GLM_LIVE_MAX_AGE_MINUTES * 60_000
}

pub(crate) fn compact_layer_status(status: &str, max_chars: usize) -> String {
    let trimmed = status.trim();
    if trimmed.chars().count() <= max_chars {
        trimmed.to_owned()
    } else {
        let mut compact = trimmed
            .chars()
            .take(max_chars.saturating_sub(3))
            .collect::<String>();
        compact.push_str("...");
        compact
    }
}

/// Visibility slot of a unified layer row: a toggle for ordinary layers, a
/// fixed badge for the always-on primary radar (no vis toggle, no ✕).
enum LayerRowVis<'a> {
    Toggle { value: &'a mut bool, hover: &'a str },
    Badge { glyph: &'a str, hover: &'a str },
}

/// Opacity slot of a unified layer row: overlay radars store u8 alpha,
/// GOES/model layers and the primary radar store f32 (max is always 1.0
/// unless capped — the warnings fill stops at 80/255 by design).
enum LayerRowOpacity<'a> {
    F32 {
        value: &'a mut f32,
        min: f32,
        hover: &'a str,
    },
    U8 {
        value: &'a mut u8,
        min: u8,
        max: u8,
    },
}

/// Standardized reorder slot: two small ↑/↓ buttons. Deliberately NOT
/// drag-and-drop — the priority persona operates a trackpad in a moving
/// truck; two 18 px buttons beat a drag gesture under stress (spec §2.1).
/// A click writes +1 (draw later/higher) or -1 (draw earlier/lower) into
/// `delta`; the caller applies it after the row returns.
struct LayerRowOrder<'a> {
    delta: &'a mut i8,
}

/// Standardized ⚙ slot — the extensibility rule (ui-overhaul spec §2.1):
/// the gear opens the layer's OWNING SURFACE (a window or a sidebar-tab
/// section), or an inline popover for layers with only 2–3 small options.
/// A row may carry at most two inline extras besides ⚙/✕; everything else
/// goes behind the gear. This single rule is what keeps future features
/// from re-crowding the rail.
enum LayerRowGear<'a> {
    /// ⚙ jumps to the layer's owning window/tab; the click lands in
    /// `clicked` for the caller to act on after the row returns.
    Open {
        hover: &'a str,
        clicked: &'a mut bool,
    },
    /// ⚙ opens a small anchored popover with the layer's few options.
    Menu {
        hover: &'a str,
        content: Box<dyn FnOnce(&mut egui::Ui) + 'a>,
    },
}

/// Standardized ✕ slot, rendered last. Rows where removal makes no sense
/// (the primary radar) opt out.
struct LayerRowRemove<'a> {
    hover: &'a str,
    clicked: &'a mut bool,
}

/// The fixed slots of one unified layer row (see `layer_row`).
struct LayerRowSpec<'a> {
    vis: LayerRowVis<'a>,
    name: &'a str,
    name_width: f32,
    name_hover: &'a str,
    state: Option<&'a str>,
    opacity: Option<LayerRowOpacity<'a>>,
    order: Option<LayerRowOrder<'a>>,
    gear: Option<LayerRowGear<'a>>,
    remove: Option<LayerRowRemove<'a>>,
}

impl Default for LayerRowSpec<'_> {
    fn default() -> Self {
        Self {
            vis: LayerRowVis::Badge {
                glyph: "·",
                hover: "",
            },
            name: "",
            name_width: NAME_W_STD,
            name_hover: "",
            state: None,
            opacity: None,
            order: None,
            gear: None,
            remove: None,
        }
    }
}

/// One unified layer row — the row grammar v2 (docs/ui-overhaul-spec.md §2.1,
/// direction A "everything is a layer"):
///
///   [vis] [name (hover = details)] [state dot] [opacity ───] [↑↓] [extras…] [⚙] [✕]
///
/// Every layer type in the rail (primary radar, overlay radars, GOES, model
/// fields, drapes, surface obs, lightning, SPC, warnings, placefiles)
/// renders through this one shape. `trailing` carries the row's earned
/// inline extras (max two besides ⚙/✕); reorder, gear, and remove are
/// standardized slots. Returns true when visibility or opacity changed
/// (callers repaint).
fn layer_row(
    ui: &mut egui::Ui,
    spec: LayerRowSpec<'_>,
    trailing: impl FnOnce(&mut egui::Ui),
) -> bool {
    let LayerRowSpec {
        vis,
        name,
        name_width,
        name_hover,
        state,
        opacity,
        order,
        gear,
        remove,
    } = spec;
    let mut changed = false;
    ui.horizontal(|ui| {
        ui.spacing_mut().item_spacing.x = ROW_SPACING_X;
        let mut label_toggle: Option<&mut bool> = None;
        match vis {
            LayerRowVis::Toggle { value, hover } => {
                let response = ui.checkbox(value, "");
                let response = if hover.is_empty() {
                    response
                } else {
                    response.on_hover_text(hover)
                };
                if response.changed() {
                    changed = true;
                }
                label_toggle = Some(value);
            }
            LayerRowVis::Badge { glyph, hover } => {
                let (rect, response) = ui.allocate_exact_size(
                    egui::vec2(18.0, PANEL_BUTTON_HEIGHT),
                    egui::Sense::hover(),
                );
                ui.put(rect, egui::Label::new(glyph));
                response.on_hover_text(hover);
            }
        }
        let name_response = fixed_status_label_with_sense(
            ui,
            name,
            name_width,
            if label_toggle.is_some() {
                egui::Sense::click()
            } else {
                egui::Sense::hover()
            },
        );
        if !name_hover.is_empty() {
            let name_response = name_response.on_hover_text(name_hover.to_owned());
            if let Some(value) = label_toggle
                && name_response
                    .on_hover_cursor(egui::CursorIcon::PointingHand)
                    .clicked()
            {
                *value = !*value;
                changed = true;
            }
        } else if let Some(value) = label_toggle
            && name_response
                .on_hover_cursor(egui::CursorIcon::PointingHand)
                .clicked()
        {
            *value = !*value;
            changed = true;
        }
        if let Some(state) = state {
            fixed_state_dot(ui, layer_state_color(state), state);
        }
        match opacity {
            Some(LayerRowOpacity::F32 { value, min, hover }) => {
                if ui
                    .add_sized(
                        egui::vec2(LAYER_ROW_SLIDER_WIDTH, PANEL_BUTTON_HEIGHT),
                        egui::Slider::new(value, min..=1.0).show_value(false),
                    )
                    .on_hover_text(hover)
                    .changed()
                {
                    changed = true;
                }
            }
            Some(LayerRowOpacity::U8 { value, min, max }) => {
                let hover = format!("Opacity {}", *value);
                if ui
                    .add_sized(
                        egui::vec2(LAYER_ROW_SLIDER_WIDTH, PANEL_BUTTON_HEIGHT),
                        egui::Slider::new(value, min..=max).show_value(false),
                    )
                    .on_hover_text(hover)
                    .changed()
                {
                    changed = true;
                }
            }
            None => {}
        }
        if let Some(LayerRowOrder { delta }) = order {
            if ui
                .small_button("↑")
                .on_hover_text("Draw later (higher)")
                .clicked()
            {
                *delta = 1;
            }
            if ui
                .small_button("↓")
                .on_hover_text("Draw earlier (lower)")
                .clicked()
            {
                *delta = -1;
            }
        }
        trailing(ui);
        match gear {
            Some(LayerRowGear::Open { hover, clicked }) => {
                if ui.small_button("⚙").on_hover_text(hover).clicked() {
                    *clicked = true;
                }
            }
            Some(LayerRowGear::Menu { hover, content }) => {
                ui.menu_button("⚙", |ui| {
                    ui.set_min_width(170.0);
                    content(ui);
                })
                .response
                .on_hover_text(hover);
            }
            None => {}
        }
        if let Some(LayerRowRemove { hover, clicked }) = remove
            && ui.small_button("✕").on_hover_text(hover).clicked()
        {
            *clicked = true;
        }
    });
    changed
}

fn hazard_record_detail_lines(record: &HazardRecord) -> Vec<String> {
    let mut lines = vec![
        record.label.clone(),
        record.event_id.clone(),
        format!("{} {}", record.office, record.action),
    ];
    if let Some(status) = &record.lifecycle_status {
        lines.push(status.clone());
    }
    if let Some(headline) = &record.headline {
        lines.push(headline.clone());
    }
    if let Some(area) = &record.area {
        lines.push(format!("Area {area}"));
    }
    if let Some(motion) = &record.motion {
        lines.push(format!("Motion {motion}"));
    }
    lines.extend(record.details.iter().cloned());
    if record.severity.is_some() || record.certainty.is_some() || record.urgency.is_some() {
        let severity = record.severity.as_deref().unwrap_or("-");
        let certainty = record.certainty.as_deref().unwrap_or("-");
        let urgency = record.urgency.as_deref().unwrap_or("-");
        lines.push(format!("{severity} / {certainty} / {urgency}"));
    }
    if let Some(source_url) = &record.source_url {
        lines.push(source_url.clone());
    }
    if let Some(tornado) = &record.tornado {
        lines.push(format!("Tornado {tornado}"));
    }
    if let Some(hail_inches) = record.hail_inches {
        lines.push(format!("Hail {:.2} in", hail_inches));
    }
    if let Some(wind_mph) = record.wind_mph {
        lines.push(format!("Wind {wind_mph} mph"));
    }
    if let Some(damage_threat) = &record.damage_threat {
        lines.push(format!("Damage {damage_threat}"));
    }
    if let Some(valid_start) = &record.valid_start {
        lines.push(format!("From {valid_start}"));
    }
    if let Some(valid_end) = &record.valid_end {
        lines.push(format!("Until {valid_end}"));
    }
    lines
}

fn hazard_record_list_label(record: &HazardRecord) -> String {
    let status = record
        .lifecycle_status
        .as_deref()
        .filter(|status| !status.trim().is_empty())
        .unwrap_or(&record.action);
    let office = if record.office.trim().is_empty() {
        String::new()
    } else {
        format!(" {}", record.office)
    };
    let until = record
        .valid_end
        .as_deref()
        .filter(|until| !until.trim().is_empty())
        .map(|until| format!(" until {until}"))
        .unwrap_or_default();
    format!("{} · {status}{office}{until}", record.label)
}

fn hazard_record_list_hover(record: &HazardRecord) -> String {
    hazard_record_detail_lines(record)
        .into_iter()
        .take(10)
        .collect::<Vec<_>>()
        .join("\n")
}

fn new_hazard_label_color(ctx: &egui::Context) -> egui::Color32 {
    let blink_on = ctx.input(|input| (input.time * 2.4) as i64 % 2 == 0);
    if blink_on {
        egui::Color32::from_rgba_unmultiplied(255, 230, 96, 245)
    } else {
        egui::Color32::from_rgba_unmultiplied(255, 118, 72, 220)
    }
}

fn hazard_focus_view(bbox: [f32; 4]) -> (f32, f32, f32) {
    let west = bbox[0].min(bbox[2]);
    let east = bbox[0].max(bbox[2]);
    let south = bbox[1].min(bbox[3]);
    let north = bbox[1].max(bbox[3]);
    let lat = ((south + north) * 0.5).clamp(-85.0, 85.0);
    let lon = normalize_lon((west + east) * 0.5);
    let lon_span = (east - west).abs().max(0.08);
    let lat_span = (north - south).abs().max(0.08);
    let span = lon_span.max(lat_span);
    let scale = (HAZARD_FOCUS_TARGET_PX / span)
        .clamp(HAZARD_FOCUS_MIN_SCALE, HAZARD_FOCUS_MAX_SCALE)
        .clamp(MIN_MAP_SCALE, MAX_MAP_SCALE);
    (lat, lon, scale)
}

fn moment_units(moment: &MomentType) -> &'static str {
    match moment {
        MomentType::Reflectivity => "dBZ",
        MomentType::Velocity | MomentType::SpectrumWidth => "m/s",
        MomentType::DifferentialReflectivity => "dB",
        MomentType::CorrelationCoefficient => "rho",
        MomentType::DifferentialPhase => "deg",
        MomentType::SpecificDifferentialPhase => "deg/km",
        MomentType::Unknown(_) => advanced_derived_product_for_moment(moment)
            .map(product_engine::DerivedSweepProduct::units)
            .unwrap_or(""),
    }
}

fn product_units(product: &DisplayProduct) -> &'static str {
    match product {
        DisplayProduct::Moment(moment) => moment_units(moment),
        DisplayProduct::DealiasedVelocity
        | DisplayProduct::StormRelativeVelocity
        | DisplayProduct::StormRelativeDealiasedVelocity => "m/s",
        DisplayProduct::Derived(d) => d.units(),
    }
}

fn advanced_derived_product_for_moment(
    moment: &MomentType,
) -> Option<product_engine::DerivedSweepProduct> {
    let MomentType::Unknown(name) = moment else {
        return None;
    };
    product_engine::DerivedSweepProduct::ALL
        .iter()
        .copied()
        .find(|product| product.id().eq_ignore_ascii_case(name))
}

fn advanced_derived_product_for_display_product(
    product: &DisplayProduct,
) -> Option<product_engine::DerivedSweepProduct> {
    match product {
        DisplayProduct::Moment(moment) => advanced_derived_product_for_moment(moment),
        _ => None,
    }
}

fn advanced_derived_color_family(moment: &MomentType) -> Option<ColorTableFamily> {
    use product_engine::DerivedSweepProduct as Product;
    match advanced_derived_product_for_moment(moment)? {
        Product::FilteredDifferentialPhase | Product::DifferentialPhaseTexture => {
            Some(ColorTableFamily::DifferentialPhase)
        }
        Product::KdpUncertainty | Product::KdpTexture => {
            Some(ColorTableFamily::SpecificDifferentialPhase)
        }
        Product::SpecificAttenuation
        | Product::PathIntegratedAttenuation
        | Product::CorrectedReflectivity
        | Product::ReflectivityTexture
        | Product::ReflectivityRangeGradient => Some(ColorTableFamily::Reflectivity),
        Product::SpecificDifferentialAttenuation
        | Product::PathIntegratedDifferentialAttenuation
        | Product::CorrectedDifferentialReflectivity
        | Product::DifferentialReflectivityTexture => {
            Some(ColorTableFamily::DifferentialReflectivity)
        }
        Product::RainRateReflectivity
        | Product::RainRateKdp
        | Product::RainRateHybrid
        | Product::LiquidWaterContent
        | Product::HailKineticEnergy
        | Product::TurbulenceProxy => Some(ColorTableFamily::Vil),
        Product::CircularDepolarizationRatio
        | Product::LogCorrelationRatio
        | Product::CorrelationCoefficientTexture
        | Product::MeteorologicalQuality
        | Product::MeteorologicalGateMask => Some(ColorTableFamily::CorrelationCoefficient),
        Product::VelocityTexture | Product::VelocityRangeGradient => {
            Some(ColorTableFamily::Velocity)
        }
        Product::SpectrumWidthTexture => Some(ColorTableFamily::SpectrumWidth),
        Product::TdsConfidence | Product::HailSignature => Some(ColorTableFamily::Probability),
        Product::Kdp => None,
    }
}

fn display_product_is_rain_rate(product: &DisplayProduct) -> bool {
    use product_engine::DerivedSweepProduct as Product;
    matches!(
        advanced_derived_product_for_display_product(product),
        Some(Product::RainRateReflectivity | Product::RainRateKdp | Product::RainRateHybrid)
    )
}

/// The display unit an internal-m/s product takes from the active color
/// table: a velocity/SW table declared in kt or mph relabels AND rescales
/// the readout, colorbar ticks, and unit chip — GR2A semantics, where the
/// palette's `Units:` header is the product's display unit (field report:
/// an mph table's editor said mph while the map readout stayed m/s).
/// Returns (label, declared→internal factor — divide internal values by it
/// for display). Non-m/s products and SI/unknown declarations are identity.
fn table_display_unit(
    table: &ColorTable,
    product: &DisplayProduct,
    unit_system: units::Units,
) -> (&'static str, f32) {
    if matches!(product, DisplayProduct::Derived(DerivedProduct::EchoTops)) {
        return match unit_system {
            units::Units::Imperial => ("kft", METERS_PER_KFT),
            units::Units::Metric => ("km", 1000.0),
        };
    }
    if display_product_is_rain_rate(product) {
        return match unit_system {
            units::Units::Imperial => ("in/hr", 25.4),
            units::Units::Metric => ("mm/h", 1.0),
        };
    }
    let base = product_units(product);
    if base == "mm" {
        return match unit_system {
            units::Units::Imperial => ("in", 25.4),
            units::Units::Metric => ("mm", 1.0),
        };
    }
    if base != "m/s" {
        return (base, 1.0);
    }
    let declared = table
        .units()
        .map(str::trim)
        .filter(|units| !units.is_empty());
    let declared_lower = declared.map(|units| (units, units.to_ascii_lowercase()));
    match declared_lower {
        Some((raw, lower)) if matches!(lower.as_str(), "kt" | "kts" | "knot" | "knots") => {
            ("kt", color_tables::unit_scale_to_internal(raw))
        }
        Some((raw, lower)) if matches!(lower.as_str(), "mph" | "mi/h") => {
            ("mph", color_tables::unit_scale_to_internal(raw))
        }
        Some((raw, lower)) if matches!(lower.as_str(), "km/h" | "kph" | "kmh") => {
            ("km/h", color_tables::unit_scale_to_internal(raw))
        }
        Some((_raw, lower))
            if matches!(
                lower.as_str(),
                "m/s" | "mps" | "ms-1" | "m s-1" | "meter/s" | "meters/s"
            ) =>
        {
            ("m/s", 1.0)
        }
        _ => match unit_system {
            units::Units::Imperial => ("mph", color_tables::unit_scale_to_internal("mph")),
            units::Units::Metric => ("km/h", color_tables::unit_scale_to_internal("km/h")),
        },
    }
}

/// The display unit an m/s product is locked to when the active color table
/// carries a recognized `Units:` declaration — i.e. the Settings unit system
/// does NOT apply to it. None = undeclared table, velocity follows Settings.
fn table_declared_velocity_unit(
    table: &ColorTable,
    product: &DisplayProduct,
) -> Option<&'static str> {
    if product_units(product) != "m/s" {
        return None;
    }
    let (imperial, _) = table_display_unit(table, product, units::Units::Imperial);
    let (metric, _) = table_display_unit(table, product, units::Units::Metric);
    // A declared unit is unit-system-independent; the undeclared fallback
    // (mph vs km/h) is not.
    (imperial == metric).then_some(imperial)
}

/// Settings ▸ Display footnote answering "where is m/s?": velocity units
/// come from the active velocity color table when the palette declares them
/// (the table declaration is the source of truth; the Units setting is only
/// the fallback for undeclared tables).
fn velocity_units_settings_note(unit: &str, table_name: &str) -> String {
    format!(
        "Velocity display: {unit} — set by the active velocity color table ({table_name}); \
         tables without declared units follow this setting."
    )
}

/// Subdivide the map canvas into per-pane cell rects for a layout. `One`
/// returns exactly `[outer]` (no inset/gap) so single-pane stays byte-identical
/// to today. `TwoVertical` splits left|right; `ThreeStacked` keeps a large
/// primary pane on the left and stacks two comparison panes on the right;
/// `FourGrid` is 2×2.
#[allow(dead_code)] // wired into map_canvas in the multi-pane grid step
fn pane_cell_rects(layout: PanelLayout, outer: egui::Rect, gap: f32) -> Vec<egui::Rect> {
    match layout {
        PanelLayout::One => vec![outer],
        PanelLayout::TwoVertical => {
            let w = ((outer.width() - gap) * 0.5).max(0.0);
            vec![
                egui::Rect::from_min_size(outer.min, egui::vec2(w, outer.height())),
                egui::Rect::from_min_size(
                    egui::pos2(outer.min.x + w + gap, outer.min.y),
                    egui::vec2(w, outer.height()),
                ),
            ]
        }
        PanelLayout::ThreeStacked => {
            let left_w = ((outer.width() - gap) * 0.58).max(0.0);
            let right_w = (outer.width() - left_w - gap).max(0.0);
            let right_h = ((outer.height() - gap) * 0.5).max(0.0);
            let right_x = outer.min.x + left_w + gap;
            let lower_y = outer.min.y + right_h + gap;
            vec![
                egui::Rect::from_min_size(outer.min, egui::vec2(left_w, outer.height())),
                egui::Rect::from_min_size(
                    egui::pos2(right_x, outer.min.y),
                    egui::vec2(right_w, right_h),
                ),
                egui::Rect::from_min_size(
                    egui::pos2(right_x, lower_y),
                    egui::vec2(right_w, right_h),
                ),
            ]
        }
        PanelLayout::FourGrid => {
            let w = ((outer.width() - gap) * 0.5).max(0.0);
            let h = ((outer.height() - gap) * 0.5).max(0.0);
            let (x0, y0) = (outer.min.x, outer.min.y);
            let (x1, y1) = (x0 + w + gap, y0 + h + gap);
            let cell = egui::vec2(w, h);
            vec![
                egui::Rect::from_min_size(egui::pos2(x0, y0), cell),
                egui::Rect::from_min_size(egui::pos2(x1, y0), cell),
                egui::Rect::from_min_size(egui::pos2(x0, y1), cell),
                egui::Rect::from_min_size(egui::pos2(x1, y1), cell),
            ]
        }
    }
}

fn annotation_target_cell(
    cells: &[egui::Rect],
    pointer: Option<egui::Pos2>,
    active_pane: usize,
) -> Option<usize> {
    if cells.is_empty() {
        return None;
    }
    pointer
        .and_then(|position| cells.iter().position(|cell| cell.contains(position)))
        .or_else(|| Some(active_pane.min(cells.len() - 1)))
}

fn cross_section_handle_rect(position: egui::Pos2) -> egui::Rect {
    egui::Rect::from_center_size(
        position,
        egui::vec2(CROSS_SECTION_HANDLE_HIT_PX, CROSS_SECTION_HANDLE_HIT_PX),
    )
}

fn ctrl_best_radar_click(modifiers: egui::Modifiers) -> bool {
    modifiers.ctrl && !modifiers.alt && !modifiers.shift
}

fn alt_model_sounding_active(modifiers: egui::Modifiers, model_soundings_available: bool) -> bool {
    modifiers.alt && model_soundings_available
}

fn plain_map_click_allowed(modifiers: egui::Modifiers, model_soundings_available: bool) -> bool {
    !modifiers.shift
        && !ctrl_best_radar_click(modifiers)
        && !alt_model_sounding_active(modifiers, model_soundings_available)
}

fn plain_context_menu_allowed(modifiers: egui::Modifiers, right_click_loads_nearest: bool) -> bool {
    !modifiers.ctrl && !right_click_loads_nearest
}

/// The map-side plot-domain shortcut chord: Ctrl+Shift (+ primary drag).
/// The one modifier+drag combo with no dedicated map consumer (v0.29.3
/// gesture audit): Shift alone is loupe/inspector-pin territory and pans on
/// drag; Ctrl alone is the best-radar click; every Alt combo belongs to the
/// sounding family — Alt is excluded here so Ctrl+Alt fluid soundings can
/// never collide even with Shift accidentally down; and the 3D box stays on
/// Shift+RIGHT-drag. Only engages at all when the Model window is open with
/// a loaded field ([`ViewerApp::plot_domain_shortcut_ready`]) — otherwise
/// the chord keeps panning like it always did.
fn plot_domain_shortcut_active(modifiers: egui::Modifiers) -> bool {
    modifiers.ctrl && modifiers.shift && !modifiers.alt
}

fn chip_width_for_text(text: &str) -> f32 {
    18.0 + text.chars().count() as f32 * 7.2
}

/// Compute a volume-derived product and wrap it in a render cache on the
/// lowest reflectivity tilt's geometry. Used by the render worker.
/// Background worker: detect rotation sites on the lowest velocity tilt and
/// geolocate them relative to the radar.
fn detect_rotation_markers_for_volume(
    volume: &RadarVolume,
    dealiased_velocity: &[Option<&MomentGrid>],
    radar_lat: f32,
    radar_lon: f32,
) -> Vec<RotationMarker> {
    let cos_lat = radar_lat.to_radians().cos().max(0.05);
    detect_rotation_sites_from_dealiased(volume, dealiased_velocity)
        .into_iter()
        .map(|site| {
            let az = (site.azimuth_deg as f64).to_radians();
            let range_km = site.ground_range_m / 1000.0;
            let east_km = range_km * az.sin();
            let north_km = range_km * az.cos();
            RotationMarker {
                lon: radar_lon + (east_km as f32) / (111.32 * cos_lat),
                lat: radar_lat + (north_km as f32) / 111.32,
                vrot_mps: site.vrot_mps,
                rank: site.rank,
                strength: site.strength,
                persistence: 1,
            }
        })
        .collect()
}

/// Preprocessed plain/dealiased moment: optional model-anchored (v4)
/// dealias, optional reflectivity gate filter (GR2-style GateFilter),
/// optional smoothing (binomial soften OR bilinear upsample) — in that
/// order — rendered via the derived-cache entry. Each combination is keyed
/// separately, so the per-frame fast path is untouched.
///
/// `dealias_env` is the RAP site profile (None until the background fetch
/// lands, always None for intl sites); `previous_volume` feeds the same
/// temporal prior the retired hybrid engine used (spec §15: v4 runs
/// per-volume — no cross-volume solution caching in v0.29.0). The inputs
/// arrive as `Arc`s so the dealias memo can witness them (see
/// [`DealiasGridWitness`]).
#[allow(clippy::too_many_arguments)]
fn build_preprocessed_plain_cache(
    volume: &Arc<RadarVolume>,
    previous_volume: Option<&Arc<RadarVolume>>,
    dealias_env: Option<&Arc<EnvironmentalWindProfile>>,
    cut_index: usize,
    moment: &MomentType,
    family: ColorTableFamily,
    dealiased_velocity: bool,
    dealias_engine: DealiasEngine,
    gate_filter_dbz: Option<f32>,
    smoothing: SmoothingMode,
    color_tables: &ColorTableSet,
) -> std::result::Result<ViewportMomentCache, String> {
    let cut = volume
        .cuts
        .get(cut_index)
        .ok_or_else(|| "cut missing".to_owned())?;
    let grid = cut
        .moments
        .get(moment)
        .ok_or_else(|| format!("moment {moment:?} missing"))?;
    let mut source = if dealiased_velocity {
        let dealiased = resolve_dealiased_grid(
            volume,
            previous_volume,
            dealias_env,
            cut_index,
            dealias_engine,
        )
        .ok_or_else(|| "selected velocity dealias failed".to_owned())?;
        (*dealiased).clone()
    } else {
        grid.clone()
    };
    if let Some(threshold) = gate_filter_dbz {
        source = apply_reflectivity_gate_filter(cut, &source, threshold);
    }
    match smoothing {
        SmoothingMode::Native => {}
        SmoothingMode::Soften => source = smooth_moment_grid(&source),
        SmoothingMode::Interpolated => {
            // Bilinear polar upsampling: the cached grid grows, the
            // per-frame fast path stays nearest-gate. A grid already
            // at/finer than the display targets passes through native.
            if let Some(up) = upsample_moment_grid(cut, &source) {
                return ViewportMomentCache::new_resampled(
                    volume,
                    cut_index,
                    up.grid,
                    &up.row_azimuths_deg,
                    family,
                    color_tables,
                )
                .map_err(|err| err.to_string());
            }
        }
    }
    ViewportMomentCache::new_derived(volume, cut_index, source, family, color_tables)
        .map_err(|err| err.to_string())
}

#[derive(Clone, Copy)]
struct DerivedDealiasContext<'a> {
    previous_volume: Option<&'a Arc<RadarVolume>>,
    environment: Option<&'a Arc<EnvironmentalWindProfile>>,
    engine: DealiasEngine,
}

fn build_derived_moment_cache(
    volume: &Arc<RadarVolume>,
    dealias: DerivedDealiasContext<'_>,
    derived: DerivedProduct,
    selected_cut: usize,
    color_tables: &ColorTableSet,
    hail_levels_m: (f32, f32),
    smoothing: SmoothingMode,
) -> std::result::Result<ViewportMomentCache, String> {
    let DerivedDealiasContext {
        previous_volume,
        environment: dealias_env,
        engine: dealias_engine,
    } = dealias;
    let (geometry_cut, grid) = if derived.is_volume_wide() {
        // Volume products render on the lowest reflectivity tilt.
        // Velocity-based composites render on the lowest VELOCITY cut's
        // geometry (split cuts: the Doppler sweep's radials differ from the
        // surveillance sweep's).
        let base_moment = derived.base_moment();
        let base_idx = volume
            .cuts
            .iter()
            .enumerate()
            .filter(|(_, c)| c.moments.contains_key(&base_moment))
            .min_by(|a, b| a.1.elevation_deg.total_cmp(&b.1.elevation_deg))
            .map(|(i, _)| i)
            .ok_or_else(|| "no base moment for derived product".to_owned())?;
        let dealiased_grids = (derived == DerivedProduct::Marc).then(|| {
            resolve_dealiased_volume_grids(volume, previous_volume, dealias_env, dealias_engine)
        });
        let borrowed_dealiased: Option<Vec<Option<&MomentGrid>>> = dealiased_grids
            .as_ref()
            .map(|grids| grids.iter().map(Option::as_deref).collect());
        let grid = match derived {
            DerivedProduct::CompositeReflectivity => composite_reflectivity_grid(volume),
            DerivedProduct::EchoTops => echo_top_grid(volume, ECHO_TOP_THRESHOLD_DBZ),
            DerivedProduct::Vil => vil_grid(volume),
            DerivedProduct::VilDensity => vil_density_grid(volume),
            DerivedProduct::Mehs => mehs_grid(volume, hail_levels_m.0, hail_levels_m.1),
            DerivedProduct::Posh => hail_grids(
                volume,
                hail_levels_m.0,
                hail_levels_m.1,
                render2d::MeshCalibration::Witt1998,
            )
            .map(|grids| grids.posh_pct),
            DerivedProduct::Poh => poh_grid(volume, hail_levels_m.0),
            DerivedProduct::Marc => {
                marc_grid_from_dealiased(volume, borrowed_dealiased.as_deref().unwrap_or_default())
            }
            DerivedProduct::GustProxy => {
                let velocity = resolve_dealiased_grid(
                    volume,
                    previous_volume,
                    dealias_env,
                    base_idx,
                    dealias_engine,
                );
                velocity
                    .as_deref()
                    .and_then(|velocity| gust_proxy_grid_from_dealiased(volume, base_idx, velocity))
            }
            DerivedProduct::AzimuthalShear | DerivedProduct::Divergence => {
                unreachable!("velocity derivatives are per-cut")
            }
        };
        (base_idx, grid)
    } else {
        // Per-cut derivative (azimuthal shear) on the selected tilt's velocity.
        let cut = volume
            .cuts
            .get(selected_cut)
            .ok_or_else(|| "selected cut missing for derived product".to_owned())?;
        let velocity = resolve_dealiased_grid(
            volume,
            previous_volume,
            dealias_env,
            selected_cut,
            dealias_engine,
        )
        .ok_or_else(|| "selected cut has no dealiased velocity for this product".to_owned())?;
        let grid = match derived {
            DerivedProduct::AzimuthalShear => azimuthal_shear_grid_from_dealiased(cut, &velocity),
            DerivedProduct::Divergence => radial_divergence_grid_from_dealiased(cut, &velocity),
            _ => unreachable!("only velocity derivatives are per-cut"),
        };
        (selected_cut, Some(grid))
    };
    let grid = grid.ok_or_else(|| format!("{} compute failed", derived.label()))?;
    let grid = match smoothing {
        SmoothingMode::Native => grid,
        SmoothingMode::Soften => smooth_moment_grid(&grid),
        SmoothingMode::Interpolated => {
            let cut = volume
                .cuts
                .get(geometry_cut)
                .ok_or_else(|| "geometry cut missing".to_owned())?;
            if let Some(up) = upsample_moment_grid(cut, &grid) {
                return ViewportMomentCache::new_resampled(
                    volume,
                    geometry_cut,
                    up.grid,
                    &up.row_azimuths_deg,
                    derived.color_family(),
                    color_tables,
                )
                .map_err(|err| err.to_string());
            }
            grid
        }
    };
    ViewportMomentCache::new_derived(
        volume,
        geometry_cut,
        grid,
        derived.color_family(),
        color_tables,
    )
    .map_err(|err| err.to_string())
}

/// Build a textured quad for one sprite of an icon sheet, rotated by the
/// icon heading (0 = north, clockwise), positioned so the sheet's hot point
/// lands on the target position.
fn icon_sprite_shape(
    sheet: &PlacefileSheet,
    icon_index: u32,
    position: egui::Pos2,
    heading_deg: f32,
    scale: f32,
) -> Option<egui::Shape> {
    let (sheet_w, sheet_h) = sheet.size;
    let (icon_w, icon_h) = (sheet.spec.icon_w, sheet.spec.icon_h);
    if icon_w == 0 || icon_h == 0 || sheet_w < icon_w || sheet_h < icon_h {
        return None;
    }
    let cols = (sheet_w / icon_w).max(1);
    let rows = (sheet_h / icon_h).max(1);
    let slot = icon_index.saturating_sub(1);
    if slot >= cols * rows {
        return None;
    }
    let (cx, cy) = (slot % cols, slot / cols);
    let uv0 = egui::pos2(
        (cx * icon_w) as f32 / sheet_w as f32,
        (cy * icon_h) as f32 / sheet_h as f32,
    );
    let uv1 = egui::pos2(
        ((cx + 1) * icon_w) as f32 / sheet_w as f32,
        ((cy + 1) * icon_h) as f32 / sheet_h as f32,
    );
    // Quad corners relative to the hot point, rotated about it.
    let hot = egui::vec2(sheet.spec.hot_x, sheet.spec.hot_y);
    let angle = heading_deg.to_radians();
    let (sin, cos) = angle.sin_cos();
    let rotate = |v: egui::Vec2| egui::vec2(v.x * cos - v.y * sin, v.x * sin + v.y * cos);
    let corners = [
        egui::vec2(0.0, 0.0),
        egui::vec2(icon_w as f32, 0.0),
        egui::vec2(icon_w as f32, icon_h as f32),
        egui::vec2(0.0, icon_h as f32),
    ];
    let uvs = [uv0, egui::pos2(uv1.x, uv0.y), uv1, egui::pos2(uv0.x, uv1.y)];
    let mut mesh = egui::epaint::Mesh::with_texture(sheet.texture.id());
    for (corner, uv) in corners.iter().zip(uvs.iter()) {
        // Style icon scale applies about the hot point (scale 1.0 = the
        // file's native pixel size).
        let local = (*corner - hot) * scale.max(0.05);
        mesh.vertices.push(egui::epaint::Vertex {
            pos: position + rotate(local),
            uv: *uv,
            color: egui::Color32::WHITE,
        });
    }
    mesh.indices.extend_from_slice(&[0, 1, 2, 0, 2, 3]);
    Some(egui::Shape::mesh(mesh))
}

/// A sensible starting threshold per family when the user first enables the
/// clamp (REF: cut clear-air clutter; VEL/shear: cut near-zero noise).
fn default_display_threshold(family: ColorTableFamily) -> f32 {
    match family {
        ColorTableFamily::Reflectivity => 20.0,
        ColorTableFamily::Velocity => 5.0,
        ColorTableFamily::AzimuthalShear => 2.0,
        ColorTableFamily::SpectrumWidth => 2.0,
        _ => 0.0,
    }
}

fn display_threshold_range(family: ColorTableFamily, table: &ColorTable) -> Option<(f32, f32)> {
    let first = table.stops().first()?.value;
    let last = table.stops().last()?.value;
    if !first.is_finite() || !last.is_finite() {
        return None;
    }
    if family_threshold_is_symmetric(family) {
        let max_abs = first.abs().max(last.abs());
        (max_abs > 0.0).then_some((0.0, max_abs))
    } else {
        let (min, max) = if first <= last {
            (first, last)
        } else {
            (last, first)
        };
        (min < max).then_some((min, max))
    }
}

fn normalized_display_threshold(
    family: ColorTableFamily,
    table: &ColorTable,
    threshold: f32,
) -> f32 {
    let Some((min, max)) = display_threshold_range(family, table) else {
        return default_display_threshold(family);
    };
    if !threshold.is_finite() {
        return default_display_threshold(family).clamp(min, max);
    }
    let threshold = if family_threshold_is_symmetric(family) {
        threshold.abs()
    } else {
        threshold
    };
    if threshold > max {
        default_display_threshold(family).clamp(min, max)
    } else {
        threshold.clamp(min, max)
    }
}

/// Diverging families clamp on |value| so both strong inbound and outbound
/// survive a threshold; sequential families clamp from below.
fn family_threshold_is_symmetric(family: ColorTableFamily) -> bool {
    matches!(
        family,
        ColorTableFamily::Velocity | ColorTableFamily::AzimuthalShear
    )
}

fn vrot_display_scale_unit(display_unit: (&str, f32), unit_system: units::Units) -> (&str, f32) {
    let (label, scale) = display_unit;
    if matches!(label, "m/s" | "kt" | "mph" | "km/h") {
        return (label, scale);
    }
    match unit_system {
        units::Units::Imperial => ("mph", color_tables::unit_scale_to_internal("mph")),
        units::Units::Metric => ("km/h", color_tables::unit_scale_to_internal("km/h")),
    }
}

fn format_vrot_card_line(
    probe: VrotProbe,
    display_unit: (&'static str, f32),
    unit_system: units::Units,
) -> String {
    let (velocity_unit, velocity_scale) = vrot_display_scale_unit(display_unit, unit_system);
    format!(
        "Vrot {:.1} {velocity_unit} - dV {:.1} {velocity_unit} - sep {:.2} km",
        probe.vrot_mps / velocity_scale,
        probe.delta_v_mps / velocity_scale,
        probe.separation_km
    )
}

fn world_label_budget(map_scale: f32) -> usize {
    if map_scale < 28.0 { 18 } else { 36 }
}

/// Census town tier visible at a given zoom (rank 7 small cities through
/// rank 9 villages); None below storm zoom.
fn town_label_rank(map_scale: f32) -> Option<u8> {
    if map_scale < 260.0 {
        None
    } else if map_scale < 520.0 {
        Some(7)
    } else if map_scale < 900.0 {
        Some(8)
    } else {
        Some(9)
    }
}

fn label_budget(map_scale: f32) -> usize {
    if map_scale < 72.0 {
        28
    } else if map_scale < 130.0 {
        54
    } else if map_scale < 230.0 {
        92
    } else {
        140
    }
}

fn left_label_rect(position: egui::Pos2, text: &str, font_size: f32) -> egui::Rect {
    let width = estimated_label_width(text, font_size);
    let height = font_size + 5.0;
    egui::Rect::from_min_size(
        egui::pos2(position.x, position.y - height * 0.5),
        egui::vec2(width, height),
    )
}

fn centered_label_rect(position: egui::Pos2, text: &str, font_size: f32) -> egui::Rect {
    let width = estimated_label_width(text, font_size);
    let height = font_size + 5.0;
    egui::Rect::from_center_size(position, egui::vec2(width, height))
}

fn estimated_label_width(text: &str, font_size: f32) -> f32 {
    text.chars().count() as f32 * font_size * 0.58 + 8.0
}

fn overlaps_any(existing: &[egui::Rect], candidate: egui::Rect) -> bool {
    existing.iter().any(|rect| rect.intersects(candidate))
}

/// Heavy 8-direction outline for storm-readable callout labels.
fn draw_heavy_halo_text(
    painter: &egui::Painter,
    position: egui::Pos2,
    align: egui::Align2,
    text: &str,
    font: egui::FontId,
    text_color: egui::Color32,
    halo_color: egui::Color32,
) {
    const R: f32 = 2.0;
    const D: f32 = 1.4;
    for offset in [
        egui::vec2(-R, 0.0),
        egui::vec2(R, 0.0),
        egui::vec2(0.0, -R),
        egui::vec2(0.0, R),
        egui::vec2(-D, -D),
        egui::vec2(D, -D),
        egui::vec2(-D, D),
        egui::vec2(D, D),
    ] {
        painter.text(position + offset, align, text, font.clone(), halo_color);
    }
    painter.text(position, align, text, font, text_color);
}

fn draw_halo_text(
    painter: &egui::Painter,
    position: egui::Pos2,
    align: egui::Align2,
    text: &str,
    font: egui::FontId,
    text_color: egui::Color32,
    halo_color: egui::Color32,
) {
    for offset in [
        egui::vec2(-1.0, 0.0),
        egui::vec2(1.0, 0.0),
        egui::vec2(0.0, -1.0),
        egui::vec2(0.0, 1.0),
    ] {
        painter.text(position + offset, align, text, font.clone(), halo_color);
    }
    painter.text(position, align, text, font, text_color);
}

/// Profile selector for the download window (0 sounding / 1 full / 2 view).
/// In-process one-click model ingest via the rw-ingest LIBRARY (typed
/// per-stage progress + cooperative cancel; atomic writes mean cancel never
/// leaves a partial hour). Freshest plausible init first — cycle cadence
/// from rustwx_models, publication lag per model (HRRR ~55 min, GFS
/// ~3.5 h) — fall back one cycle; then prune the store to the newest runs.
/// The four ingested hours start at the run's age so their valid times
/// bracket now..now+3 h (the auto hail-env sampling window).
fn run_model_ingest(
    model: rustwx_core::ModelId,
    cancel: &std::sync::atomic::AtomicBool,
    progress: &mpsc::Sender<String>,
    ctx: &egui::Context,
    keep_runs: usize,
) -> std::result::Result<String, String> {
    let store_dir = settings::model_store_dir();
    let cache_dir = settings::model_cache_dir();
    let store_str = store_dir.to_string_lossy();
    let cache_str = cache_dir.to_string_lossy();
    #[allow(non_snake_case)]
    let STORE: &str = &store_str;
    #[allow(non_snake_case)]
    let CACHE: &str = &cache_str;
    let label = model.as_str().to_uppercase();
    let model_slug = model.as_str().replace('-', "_");
    let now = Utc::now();
    let candidates = ingest_worker::recent_cycle_candidates(
        now,
        rustwx_models::model_summary(model).cycle_hours_utc,
        ingest_worker::publication_lag_minutes(model),
        2,
    );
    let report = |line: String| {
        let _ = progress.send(line);
        ctx.request_repaint();
    };
    let mut last_error = format!("{label}: no plausible cycle candidates");
    'candidates: for (date, cycle_hour) in candidates {
        let Ok(cycle) = rustwx_core::CycleSpec::new(&date, cycle_hour) else {
            continue;
        };
        let profile = rw_ingest::ingest_profile::IngestProfile::sounding();
        let run_slug = format!("{date}_{cycle_hour:02}z");
        let progress_sink = std::sync::Mutex::new(progress.clone());
        let ctx_sink = ctx.clone();
        let stage_label = label.clone();
        let on_event = move |event: rw_ingest::IngestEvent| {
            if let rw_ingest::IngestEvent::StageStarted { hour, stage } = event
                && let Ok(sender) = progress_sink.lock()
            {
                let _ = sender.send(format!("{stage_label} f{hour:02}: {stage:?}…"));
                ctx_sink.request_repaint();
            }
        };
        let config = rw_ingest::IngestConfig {
            model,
            cycle: &cycle,
            source_override: None,
            cache_root: std::path::Path::new(CACHE),
            use_cache: true,
            store_root: std::path::Path::new(STORE),
            model_slug: &model_slug,
            run_slug: &run_slug,
            profile: &profile,
            verify: false,
            progress: &on_event,
            cancel,
        };
        let init = chrono::NaiveDate::parse_from_str(&date, "%Y%m%d")
            .ok()
            .and_then(|d| d.and_hms_opt(cycle_hour as u32, 0, 0))
            .map(|naive| naive.and_utc());
        let run_age_minutes = init.map(|init| (now - init).num_minutes()).unwrap_or(55);
        let first = ingest_worker::first_live_hour(run_age_minutes);
        for hour in first..=first + 3 {
            match rw_ingest::ingest_hour_serial(&config, hour) {
                Ok(_) => {
                    report(format!("{label} {date} {cycle_hour:02}z f{hour:02} stored"));
                }
                Err(rw_ingest::IngestError::Cancelled) => {
                    return Err("cancelled".to_owned());
                }
                Err(err) => {
                    last_error = format!("{label}: {err}");
                    // This cycle likely isn't published yet — try the
                    // previous one (unless some hours already landed, in
                    // which case report the partial truthfully).
                    if hour == first {
                        continue 'candidates;
                    }
                    prune_model_store(STORE, keep_runs);
                    return Ok(format!(
                        "{label} {date} {cycle_hour:02}z: f{first:02}–f{:02} stored (f{hour:02} failed: {last_error})",
                        hour - 1
                    ));
                }
            }
        }
        prune_model_store(STORE, keep_runs);
        return Ok(format!(
            "{label} {date} {cycle_hour:02}z ingested (f{first:02}–f{:02})",
            first + 3
        ));
    }
    Err(last_error)
}

/// Keep only the newest `keep` run directories under store/<model>/
/// (`keep == 0` = unlimited, never deletes).
fn prune_model_store(store_root: &str, keep: usize) {
    if keep == 0 {
        return;
    }
    let Ok(models) = std::fs::read_dir(store_root) else {
        return;
    };
    for model in models.flatten() {
        if !model.path().is_dir() {
            continue;
        }
        let Ok(runs) = std::fs::read_dir(model.path()) else {
            continue;
        };
        let mut run_dirs: Vec<std::path::PathBuf> = runs
            .flatten()
            .map(|entry| entry.path())
            .filter(|path| path.is_dir())
            // Honor the rw-store writer-lock protocol (Wave 1): a run dir
            // holding .rw-lock has an active writer — never prune it.
            .filter(|path| !path.join(".rw-lock").exists())
            .collect();
        run_dirs.sort();
        while run_dirs.len() > keep {
            let oldest = run_dirs.remove(0);
            let _ = std::fs::remove_dir_all(oldest);
        }
    }
}

/// Model picker options for the download panel (multi-model entries show
/// disabled until rw-ingest supports them — "coming soon").
fn ingest_worker_model_options() -> Vec<rw_ui::ModelOption> {
    rustwx_models::supported_models()
        .iter()
        .copied()
        .filter(|&model| bowecho_model_download_supported(model))
        .map(|model| rw_ui::ModelOption {
            slug: model.as_str().to_string(),
            label: model.as_str().to_uppercase(),
            enabled: true,
            note: String::new(),
        })
        .collect()
}

fn bowecho_model_download_supported(model: rustwx_core::ModelId) -> bool {
    rw_ingest::ingest_supported(model)
}

fn model_download_cadence_hint(model: rustwx_core::ModelId, _cycle: u8) -> &'static str {
    use rustwx_core::ModelId;
    match model {
        ModelId::Gfs => "hourly <=120, 3-hourly 123-384",
        ModelId::Gefs => "3-hourly <=240, 6-hourly 246-384",
        ModelId::Aigfs | ModelId::Aigefs => "6-hourly 000-384",
        ModelId::Hgefs => "6-hourly 000-240",
        ModelId::EcmwfOpenData => {
            "00/12z: 3-hourly <=144 then 6-hourly <=360; 06/18z: 3-hourly <=144"
        }
        ModelId::Rap => "f000-f021 most cycles, f000-f051 at 03/09/15/21z",
        ModelId::Nam => "hourly <=36, 3-hourly 39-84",
        _ => "",
    }
}

fn normalize_model_download_spec(mut spec: rw_ui::DownloadSpec) -> rw_ui::DownloadSpec {
    let Ok(model) = spec.model.parse::<rustwx_core::ModelId>() else {
        return spec;
    };
    if let Some(hours) = normalize_model_download_hours(model, spec.cycle, &spec.hours) {
        spec.hours = hours;
    }
    spec
}

fn normalize_model_download_hours(
    model: rustwx_core::ModelId,
    cycle: u8,
    hour_spec: &str,
) -> Option<String> {
    let supported = rustwx_models::supported_forecast_hours(model, cycle);
    if supported.is_empty() {
        return None;
    }
    let requested = rw_ingest::ingest_hour::parse_hours(hour_spec).ok()?;
    if requested.iter().all(|hour| supported.contains(hour)) {
        return None;
    }

    let mut normalized = Vec::new();
    for token in hour_spec
        .split(',')
        .map(str::trim)
        .filter(|token| !token.is_empty())
    {
        if let Some((start, end)) = token.split_once('-') {
            let start: u16 = start.trim().parse().ok()?;
            let end: u16 = end.trim().parse().ok()?;
            if start > end {
                return None;
            }
            let before = normalized.len();
            normalized.extend(
                supported
                    .iter()
                    .copied()
                    .filter(|hour| *hour >= start && *hour <= end),
            );
            if normalized.len() == before {
                return None;
            }
        } else {
            let hour: u16 = token.parse().ok()?;
            if !supported.contains(&hour) {
                return None;
            }
            normalized.push(hour);
        }
    }

    normalized.sort_unstable();
    normalized.dedup();
    if normalized.is_empty() {
        None
    } else {
        Some(
            normalized
                .iter()
                .map(|hour| hour.to_string())
                .collect::<Vec<_>>()
                .join(","),
        )
    }
}

/// Keep the download panel's cycle/source pickers + hours hint in sync
/// with the spec's model (port of rusty-weather-ui's sync_run_pickers).
fn sync_run_pickers(download: &mut rw_ui::DownloadPanel, spec: &rw_ui::DownloadSpec) {
    let Ok(model) = spec.model.parse::<rustwx_core::ModelId>() else {
        return;
    };
    let summary = rustwx_models::model_summary(model);
    download.set_cycle_options(summary.cycle_hours_utc.to_vec());
    let mut sources = vec!["auto".to_string()];
    sources.extend(summary.sources.iter().map(|source| source.id.to_string()));
    download.set_source_options(sources);
    let supported = rustwx_models::supported_forecast_hours(model, spec.cycle);
    match (supported.first(), supported.last()) {
        (Some(first), Some(last)) => {
            let cadence = model_download_cadence_hint(model, spec.cycle);
            let hint = if cadence.is_empty() {
                format!("supported: {first}-{last} ({:02}z)", spec.cycle)
            } else {
                format!("supported: {first}-{last} ({:02}z) - {cadence}", spec.cycle)
            };
            download.set_hours_hint(hint);
        }
        _ => download.set_hours_hint("no supported hours for this cycle".to_string()),
    }
}

/// One sparkline series in an obs-history band: points (ascending time) + colour.
type ObsSparkSeries<'a> = (&'a [(DateTime<Utc>, f32)], egui::Color32);

/// Compact graphical history strip for a pinned surface station: stacked
/// sparklines of temperature/dewpoint, wind, and pressure across the 3 h
/// window, all sharing one time axis (the "time bar"). A bright vertical
/// marker sits at the currently displayed radar-frame time and slides as
/// you scan an archived loop — the obs "scrubber". Every report is a dot;
/// the report nearest the frame time is filled and read out on the right.
fn draw_obs_history_timeline(
    painter: &egui::Painter,
    rect: egui::Rect,
    history: &ObsHistoryData,
    unit_system: units::Units,
) {
    if rect.width() < 220.0 || rect.height() < 60.0 {
        return;
    }
    painter.rect_filled(
        rect,
        3.0,
        egui::Color32::from_rgba_unmultiplied(4, 7, 11, 190),
    );
    let border = egui::Stroke::new(1.0, egui::Color32::from_rgb(48, 62, 78));
    painter.line_segment([rect.left_top(), rect.right_top()], border);
    painter.line_segment([rect.right_top(), rect.right_bottom()], border);
    painter.line_segment([rect.right_bottom(), rect.left_bottom()], border);
    painter.line_segment([rect.left_bottom(), rect.left_top()], border);

    // Time -> x across the fixed [start, end] window (guard a zero span).
    let start = history.start_time;
    let end = history.end_time.max(start + chrono::Duration::seconds(1));
    let span_s = (end - start).num_seconds().max(1) as f32;
    let label_w = 34.0_f32; // left gutter for the row label
    let value_w = 52.0_f32; // right gutter for the frame readout
    let plot_left = rect.left() + label_w;
    let plot_right = rect.right() - value_w;
    let plot_w = (plot_right - plot_left).max(10.0);
    let x_of = |time: DateTime<Utc>| -> f32 {
        let frac = ((time - start).num_seconds() as f32 / span_s).clamp(0.0, 1.0);
        plot_left + frac * plot_w
    };

    let axis_h = 12.0_f32;
    let rows_top = rect.top() + 4.0;
    let rows_bottom = rect.bottom() - axis_h;
    let row_gap = 3.0_f32;
    let row_h = ((rows_bottom - rows_top) - row_gap * 2.0) / 3.0;

    // Faint hour gridlines spanning the bands — a light "time bar".
    {
        use chrono::Timelike;
        let grid_stroke =
            egui::Stroke::new(1.0, egui::Color32::from_rgba_unmultiplied(70, 84, 104, 55));
        let mut tick = start
            .with_minute(0)
            .and_then(|t| t.with_second(0))
            .and_then(|t| t.with_nanosecond(0))
            .unwrap_or(start);
        if tick < start {
            tick += chrono::Duration::hours(1);
        }
        while tick <= end {
            let x = x_of(tick);
            painter.line_segment(
                [egui::pos2(x, rows_top), egui::pos2(x, rows_bottom)],
                grid_stroke,
            );
            tick += chrono::Duration::hours(1);
        }
    }

    // Numeric series (ascending time). Rows are stored newest-first.
    let series_of = |extract: &dyn Fn(&ObsHistoryRow) -> Option<f32>| -> Vec<(DateTime<Utc>, f32)> {
        let mut pts: Vec<(DateTime<Utc>, f32)> = history
            .rows
            .iter()
            .filter_map(|row| Some((row.time_utc, extract(row)?)))
            .collect();
        pts.sort_by_key(|(time, _)| *time);
        pts
    };
    let temp_pts = series_of(&|row| {
        row.temp_c.map(|c| match unit_system {
            units::Units::Imperial => c * 9.0 / 5.0 + 32.0,
            units::Units::Metric => c,
        })
    });
    let dew_pts = series_of(&|row| {
        row.dewpoint_c.map(|c| match unit_system {
            units::Units::Imperial => c * 9.0 / 5.0 + 32.0,
            units::Units::Metric => c,
        })
    });
    let wind_pts = series_of(&|row| row.wind_speed_kt);
    let gust_pts = series_of(&|row| row.wind_gust_kt);
    let pres_pts = series_of(&|row| row.altim_in_hg);

    let frame_time = history.frame_time;
    let nearest = |pts: &[(DateTime<Utc>, f32)]| -> Option<(DateTime<Utc>, f32)> {
        pts.iter()
            .copied()
            .min_by_key(|(time, _)| (frame_time - *time).num_seconds().abs())
    };

    // Draw one band: sparkline(s) sharing a y-scale, with a nearest-frame
    // dot + right-gutter readout per series.
    let draw_band = |band_top: f32,
                     series: &[ObsSparkSeries<'_>],
                     label: &str,
                     decimals: usize,
                     suffix: &str| {
        let band_bottom = band_top + row_h;
        let band_mid = (band_top + band_bottom) * 0.5;
        painter.line_segment(
            [
                egui::pos2(plot_left, band_bottom),
                egui::pos2(plot_right, band_bottom),
            ],
            egui::Stroke::new(1.0, egui::Color32::from_rgba_unmultiplied(70, 84, 104, 90)),
        );
        painter.text(
            egui::pos2(rect.left() + 4.0, band_mid),
            egui::Align2::LEFT_CENTER,
            label,
            egui::FontId::monospace(9.5),
            egui::Color32::from_rgb(156, 213, 255),
        );
        let mut lo = f32::INFINITY;
        let mut hi = f32::NEG_INFINITY;
        for (pts, _) in series {
            for (_, value) in pts.iter() {
                lo = lo.min(*value);
                hi = hi.max(*value);
            }
        }
        if !lo.is_finite() || !hi.is_finite() {
            painter.text(
                egui::pos2(plot_right + 4.0, band_mid),
                egui::Align2::LEFT_CENTER,
                "--",
                egui::FontId::monospace(9.5),
                egui::Color32::from_rgb(150, 160, 172),
            );
            return;
        }
        let pad = ((hi - lo) * 0.15).max(0.5);
        let lo = lo - pad;
        let hi = hi + pad;
        let usable_h = (row_h - 3.0).max(2.0);
        let y_of = |value: f32| -> f32 {
            let frac = ((value - lo) / (hi - lo).max(1e-3)).clamp(0.0, 1.0);
            band_bottom - 1.5 - frac * usable_h
        };
        let series_n = series.len();
        for (idx, (pts, color)) in series.iter().enumerate() {
            if pts.is_empty() {
                continue;
            }
            if pts.len() >= 2 {
                let poly: Vec<egui::Pos2> = pts
                    .iter()
                    .map(|(time, value)| egui::pos2(x_of(*time), y_of(*value)))
                    .collect();
                painter.add(egui::Shape::line(poly, egui::Stroke::new(1.4, *color)));
            }
            for (time, value) in pts.iter() {
                painter.circle_filled(egui::pos2(x_of(*time), y_of(*value)), 1.2, *color);
            }
            if let Some((time, value)) = nearest(pts) {
                let point = egui::pos2(x_of(time), y_of(value));
                painter.circle_filled(point, 2.6, *color);
                painter.circle_stroke(point, 2.6, egui::Stroke::new(0.8, egui::Color32::BLACK));
                let dy = if series_n <= 1 {
                    0.0
                } else {
                    (idx as f32 - (series_n as f32 - 1.0) * 0.5) * 10.0
                };
                painter.text(
                    egui::pos2(plot_right + 4.0, band_mid + dy),
                    egui::Align2::LEFT_CENTER,
                    format!("{value:.decimals$}{suffix}"),
                    egui::FontId::monospace(9.5),
                    *color,
                );
            }
        }
    };

    let band0 = rows_top;
    let band1 = rows_top + row_h + row_gap;
    let band2 = rows_top + 2.0 * (row_h + row_gap);
    let temp_color = egui::Color32::from_rgb(244, 102, 92);
    let dew_color = egui::Color32::from_rgb(92, 232, 134);
    let wind_color = egui::Color32::from_rgb(120, 200, 240);
    let gust_color = egui::Color32::from_rgb(240, 186, 96);
    let pres_color = egui::Color32::from_rgb(235, 196, 120);
    let temp_unit = match unit_system {
        units::Units::Imperial => "F",
        units::Units::Metric => "C",
    };
    draw_band(
        band0,
        &[
            (temp_pts.as_slice(), temp_color),
            (dew_pts.as_slice(), dew_color),
        ],
        "T/Td",
        0,
        temp_unit,
    );
    draw_band(
        band1,
        &[
            (wind_pts.as_slice(), wind_color),
            (gust_pts.as_slice(), gust_color),
        ],
        "wind",
        0,
        "kt",
    );
    draw_band(band2, &[(pres_pts.as_slice(), pres_color)], "pres", 2, "");

    // Frame-time scrubber marker across the bands + a downward apex.
    let marker_x = x_of(frame_time);
    let marker_color = egui::Color32::from_rgb(255, 226, 120);
    painter.line_segment(
        [
            egui::pos2(marker_x, rows_top),
            egui::pos2(marker_x, rows_bottom + 1.0),
        ],
        egui::Stroke::new(1.4, marker_color),
    );
    painter.add(egui::Shape::convex_polygon(
        vec![
            egui::pos2(marker_x - 3.0, rows_top),
            egui::pos2(marker_x + 3.0, rows_top),
            egui::pos2(marker_x, rows_top + 4.0),
        ],
        marker_color,
        egui::Stroke::NONE,
    ));

    // Time axis (the "time bar") with start / end / frame labels.
    let axis_y = rows_bottom + 2.0;
    painter.line_segment(
        [
            egui::pos2(plot_left, axis_y),
            egui::pos2(plot_right, axis_y),
        ],
        egui::Stroke::new(1.0, egui::Color32::from_rgba_unmultiplied(80, 96, 118, 120)),
    );
    let axis_font = egui::FontId::monospace(9.0);
    let weak = egui::Color32::from_rgb(150, 160, 172);
    painter.text(
        egui::pos2(plot_left, axis_y + 1.0),
        egui::Align2::LEFT_TOP,
        start.format("%H:%MZ").to_string(),
        axis_font.clone(),
        weak,
    );
    painter.text(
        egui::pos2(plot_right, axis_y + 1.0),
        egui::Align2::RIGHT_TOP,
        end.format("%H:%MZ").to_string(),
        axis_font.clone(),
        weak,
    );
    let frame_label_x = marker_x.clamp(plot_left + 22.0, plot_right - 22.0);
    painter.text(
        egui::pos2(frame_label_x, axis_y + 1.0),
        egui::Align2::CENTER_TOP,
        frame_time.format("%H:%MZ").to_string(),
        axis_font,
        marker_color,
    );
}

fn draw_obs_history_table(
    painter: &egui::Painter,
    rect: egui::Rect,
    history: &ObsHistoryData,
    max_rows: usize,
    unit_system: units::Units,
) {
    if rect.width() < 220.0 || rect.height() < 44.0 || max_rows == 0 {
        return;
    }
    painter.rect_filled(
        rect,
        3.0,
        egui::Color32::from_rgba_unmultiplied(4, 7, 11, 190),
    );
    let border = egui::Stroke::new(1.0, egui::Color32::from_rgb(48, 62, 78));
    painter.line_segment([rect.left_top(), rect.right_top()], border);
    painter.line_segment([rect.right_top(), rect.right_bottom()], border);
    painter.line_segment([rect.right_bottom(), rect.left_bottom()], border);
    painter.line_segment([rect.left_bottom(), rect.left_top()], border);

    let temp_unit = match unit_system {
        units::Units::Imperial => "F",
        units::Units::Metric => "C",
    };
    let font = egui::FontId::monospace(10.0);
    let header_font = egui::FontId::monospace(10.5);
    let header_color = egui::Color32::from_rgb(156, 213, 255);
    let text_color = egui::Color32::from_rgb(225, 231, 238);
    let weak_color = egui::Color32::from_rgb(150, 160, 172);
    let left = rect.left() + 8.0;
    let mut y = rect.top() + 6.0;
    painter.text(
        egui::pos2(left, y),
        egui::Align2::LEFT_TOP,
        format!(
            "{} to {} - frame {}",
            history.start_time.format("%H:%MZ"),
            history.end_time.format("%H:%MZ"),
            history.frame_time.format("%H:%MZ")
        ),
        header_font.clone(),
        weak_color,
    );
    y += 13.0;
    let columns = [
        (0.0, "time"),
        (72.0, "age"),
        (112.0, "T"),
        (144.0, "Td"),
        (178.0, "wind"),
        (250.0, "alt"),
        (298.0, "src"),
    ];
    for (x, label) in columns {
        painter.text(
            egui::pos2(left + x, y),
            egui::Align2::LEFT_TOP,
            if label == "T" {
                format!("T {temp_unit}")
            } else if label == "Td" {
                format!("Td {temp_unit}")
            } else {
                label.to_owned()
            },
            header_font.clone(),
            header_color,
        );
    }
    y += 13.0;
    painter.line_segment(
        [egui::pos2(left, y), egui::pos2(rect.right() - 8.0, y)],
        egui::Stroke::new(1.0, egui::Color32::from_rgba_unmultiplied(80, 96, 118, 120)),
    );
    y += 3.0;
    for row in history.rows.iter().take(max_rows) {
        let color = if row.age_min > 75 {
            weak_color
        } else {
            text_color
        };
        let fields = [
            (0.0, row.time_text.as_str(), color),
            (72.0, "", weak_color),
            (
                112.0,
                row.temp_text.as_str(),
                egui::Color32::from_rgb(244, 102, 92),
            ),
            (
                144.0,
                row.dewpoint_text.as_str(),
                egui::Color32::from_rgb(92, 232, 134),
            ),
            (178.0, row.wind_text.as_str(), color),
            (250.0, row.pressure_text.as_str(), color),
            (298.0, row.network.as_str(), weak_color),
        ];
        for (x, value, field_color) in fields {
            let text = if x == 72.0 {
                format!("{}m", row.age_min)
            } else {
                value.to_owned()
            };
            painter.text(
                egui::pos2(left + x, y),
                egui::Align2::LEFT_TOP,
                text,
                font.clone(),
                field_color,
            );
        }
        y += 13.5;
    }
    if history.rows.len() > max_rows {
        painter.text(
            egui::pos2(left, y),
            egui::Align2::LEFT_TOP,
            format!(
                "+{} older reports in this 3h window",
                history.rows.len() - max_rows
            ),
            font,
            weak_color,
        );
    }
}

/// Station-plot wind barb (meteorological convention: shaft extends
/// upwind; 50-kt flags, 10-kt full barbs, 5-kt halves, calm = ring).
fn draw_station_barb(
    painter: &egui::Painter,
    tip: egui::Pos2,
    dir_deg: f32,
    spd_kt: f32,
    obs_style: &styles::ObsStyle,
) {
    let color = style_color32(obs_style.barb_color);
    let stroke = egui::Stroke::new(obs_style.barb_width, color);
    if spd_kt < 2.5 {
        painter.circle_stroke(tip, 4.0, stroke);
        return;
    }
    let dir = dir_deg.to_radians();
    // Screen y-down; wind FROM dir: upwind unit vector points toward dir.
    let tail = egui::vec2(-dir.sin(), dir.cos());
    let perp = egui::vec2(-tail.y, tail.x);
    let shaft = 22.0;
    let spacing = 3.6;
    let full_h = 8.5;
    let full_w = 5.2;
    painter.line_segment([tip, tip + tail * shaft], stroke);
    let mut remaining = ((spd_kt + 2.5) / 5.0).floor() * 5.0;
    let mut offset = shaft;
    let mut drew_any = false;
    while remaining >= 50.0 {
        let base = tip + tail * offset;
        painter.add(egui::Shape::convex_polygon(
            vec![
                base,
                base + perp * full_h - tail * (full_w * 0.5),
                base - tail * full_w,
            ],
            color,
            stroke,
        ));
        offset -= full_w + spacing;
        remaining -= 50.0;
        drew_any = true;
    }
    while remaining >= 10.0 {
        let base = tip + tail * offset;
        painter.line_segment([base, base + perp * full_h + tail * (full_w * 0.5)], stroke);
        offset -= spacing;
        remaining -= 10.0;
        drew_any = true;
    }
    if remaining >= 5.0 {
        if !drew_any {
            offset -= 1.5 * spacing;
        }
        let base = tip + tail * offset;
        painter.line_segment(
            [base, base + perp * (full_h * 0.5) + tail * (full_w * 0.25)],
            stroke,
        );
    }
}

/// Saturation vapor pressure (hPa) over liquid water at `t_c` — the
/// Magnus-type fit with Bolton's constants (Bolton 1980, Mon. Wea. Rev.
/// 108, 1046–1053, Eq. 10): es = 6.112·exp(17.67·T / (T + 243.5)).
fn saturation_vapor_pressure_hpa(t_c: f64) -> f64 {
    6.112 * ((17.67 * t_c) / (t_c + 243.5)).exp()
}

/// Dewpoint (K) from temperature (K) and relative humidity (%), inverting
/// the Bolton (1980) fit: Td = 243.5·ln(e/6.112) / (17.67 − ln(e/6.112))
/// with e = (RH/100)·es(T). Accurate to ≈0.1 °C over meteorological
/// ranges — the same fit sharprs/MetPy-style thermo uses.
fn dewpoint_k_from_rh(t_k: f32, rh_percent: f32) -> f32 {
    let t_c = f64::from(t_k) - 273.15;
    let rh = f64::from(rh_percent).clamp(0.1, 100.0) / 100.0;
    let e = (rh * saturation_vapor_pressure_hpa(t_c)).max(1e-9);
    let ln = (e / 6.112).ln();
    let td_c = 243.5 * ln / (17.67 - ln);
    (td_c + 273.15) as f32
}

/// GFS pgrb2 carries isobaric moisture as RELATIVE HUMIDITY, so rw-ingest
/// stores `rh_iso` (its documented dewpoint fallback) — but the rw-ui
/// skew-T bridge requires `dewpoint_iso` and rejects the hour outright.
/// Bridge the gap app-side: synthesize `dewpoint_iso` from
/// `temperature_iso` + `rh_iso` on rh's levels (Bolton 1980 inversion).
/// `None` = nothing to do (dewpoint already stored, e.g. HRRR, or no rh).
fn with_synthesized_dewpoint(data: &rw_ui::SoundingData) -> Option<rw_ui::SoundingData> {
    if data.vars.iter().any(|var| var.name == "dewpoint_iso") {
        return None;
    }
    let rh = data.vars.iter().find(|var| var.name == "rh_iso")?;
    let temperature = data
        .vars
        .iter()
        .find(|var| var.name == "temperature_iso")
        .filter(|var| var.units == "K")?;
    let values: Vec<f32> = rh
        .levels_hpa
        .iter()
        .zip(rh.values.iter())
        .map(|(&level, &rh_value)| {
            temperature
                .levels_hpa
                .iter()
                .position(|&have| have == level)
                .and_then(|index| temperature.values.get(index).copied())
                .filter(|t_k| t_k.is_finite() && rh_value.is_finite())
                .map(|t_k| dewpoint_k_from_rh(t_k, rh_value))
                .unwrap_or(f32::NAN)
        })
        .collect();
    let mut out = data.clone();
    out.vars.push(rw_ui::ProfileVar {
        name: "dewpoint_iso".to_owned(),
        units: "K".to_owned(),
        levels_hpa: rh.levels_hpa.clone(),
        values,
    });
    Some(out)
}

/// Build the native sounding, optionally swapping the model surface for
/// a nearby fresh observation (T/Td clamped sane, wind kt -> m/s) before
/// the sharprs parcel math runs — "obs-adjusted sounding". The title
/// metadata records the adjusting station + distance. Production goes
/// through the `_with_display` variant; this thin wrapper serves the
/// ingest_worker end-to-end test.
#[cfg(test)]
fn build_native_sounding_adjusted(
    data: &rw_ui::SoundingData,
    adjust: Option<(f32, obs::SurfaceOb)>,
) -> std::result::Result<rustwx_sounding::NativeSounding, String> {
    build_native_sounding_adjusted_with_display(data, adjust).map(|(native, _)| native)
}

/// `build_native_sounding_adjusted` plus, when the adjustment is applied,
/// the adjusted `(SoundingData, SoundingColumn)` pair for the DISPLAYED
/// skew-T panel: the v0.27.0 dock panel rebuilds its scene from RAW store
/// data, so the toggle only reaches the screen through the
/// `set_native_column` path (as the RAOB flow already does). The header
/// carries the adjusting station so the displayed title never lies about
/// the surface source. Production now calls
/// `build_native_sounding_for_request` directly (the profile build is
/// gated on the hail-env consumer); this always-build shape serves tests.
#[cfg(test)]
fn build_native_sounding_adjusted_with_display(
    data: &rw_ui::SoundingData,
    adjust: Option<(f32, obs::SurfaceOb)>,
) -> std::result::Result<
    (
        rustwx_sounding::NativeSounding,
        Option<(rw_ui::SoundingData, rustwx_sounding::SoundingColumn)>,
    ),
    String,
> {
    let (native, adjusted_display) = build_native_sounding_for_request(data, adjust, true)?;
    Ok((
        native.expect("build_profile=true always builds the sharprs sounding"),
        adjusted_display,
    ))
}

/// `build_native_sounding_for_request` output: the sharprs sounding (only
/// when requested) plus the obs-adjusted display pair (only when adjusted).
type NativeSoundingBuild = (
    Option<rustwx_sounding::NativeSounding>,
    Option<(rw_ui::SoundingData, rustwx_sounding::SoundingColumn)>,
);

/// Core builder behind a model-sounding request. `build_profile` gates the
/// sharprs `NativeSounding::from_column` parcel math: after the v0.28
/// legacy-renderer deletion its only consumer is the hail-environment
/// H0/H−20 extraction in `poll_native_sounding`, so a plain model click
/// (no hail-env request pending) skips that work. The (possibly
/// obs-adjusted) DISPLAY pair is built either way — the displayed skew-T
/// must not change with the skip.
fn build_native_sounding_for_request(
    data: &rw_ui::SoundingData,
    adjust: Option<(f32, obs::SurfaceOb)>,
    build_profile: bool,
) -> std::result::Result<NativeSoundingBuild, String> {
    // RH-only stores (GFS) get a synthesized dewpoint profile first.
    let synthesized = with_synthesized_dewpoint(data);
    let data = synthesized.as_ref().unwrap_or(data);
    let mut column = rw_ui::skewt::build_sounding_column(data)?;
    let mut tag = None;
    if let Some((distance_km, ob)) = adjust
        && let (Some(t), Some(td)) = (ob.temp_c, ob.dewpoint_c)
        && !column.temperature_c.is_empty()
    {
        column.temperature_c[0] = t as f64;
        column.dewpoint_c[0] = (td.min(t)) as f64;
        if let (Some(dir), Some(spd)) = (ob.wind_dir_deg, ob.wind_speed_kt) {
            let speed_ms = spd as f64 * 0.514_444;
            let dir_rad = (dir as f64).to_radians();
            column.u_ms[0] = -speed_ms * dir_rad.sin();
            column.v_ms[0] = -speed_ms * dir_rad.cos();
        }
        tag = Some(format!("{} obs-adj {:.0}km", ob.station_id, distance_km));
    }
    let native = if build_profile {
        let mut native =
            rustwx_sounding::NativeSounding::from_column(&column).map_err(|err| err.to_string())?;
        if let Some(tag) = &tag {
            if native.metadata.station_id.is_empty() {
                native.metadata.station_id = tag.clone();
            } else {
                native.metadata.station_id = format!("{} · {tag}", native.metadata.station_id);
            }
        }
        Some(native)
    } else {
        None
    };
    let adjusted_display = tag.map(|tag| {
        let mut display_data = data.clone();
        display_data.hour.run = format!("{} · {tag}", display_data.hour.run);
        (display_data, column)
    });
    Ok((native, adjusted_display))
}

fn raob_column_to_rw_sounding_data(
    site: &obs_soundings::RaobSite,
    valid: DateTime<Utc>,
    column: &rustwx_sounding::SoundingColumn,
    context: String,
) -> std::result::Result<rw_ui::SoundingData, String> {
    if column.pressure_hpa.len() < 2 {
        return Err("RAOB column has too few levels for the native panel".to_owned());
    }
    let surface_value = |values: &[f64], name: &str| -> std::result::Result<f32, String> {
        values
            .first()
            .copied()
            .filter(|value| value.is_finite())
            .map(|value| value as f32)
            .ok_or_else(|| format!("RAOB column missing finite {name} at the surface"))
    };
    let psfc_hpa = surface_value(&column.pressure_hpa, "pressure")?;
    let zsfc_m = surface_value(&column.height_m_msl, "height")?;
    let tsfc_c = surface_value(&column.temperature_c, "temperature")?;
    let tdsfc_c = surface_value(&column.dewpoint_c, "dewpoint")?;
    let usfc_ms = surface_value(&column.u_ms, "u wind")?;
    let vsfc_ms = surface_value(&column.v_ms, "v wind")?;

    let mut levels_hpa = Vec::new();
    let mut temperature_k = Vec::new();
    let mut dewpoint_k = Vec::new();
    let mut u_ms = Vec::new();
    let mut v_ms = Vec::new();
    let mut height_m = Vec::new();
    for index in 1..column.pressure_hpa.len() {
        let p = column.pressure_hpa[index];
        let z = column.height_m_msl[index];
        let t = column.temperature_c[index];
        let td = column.dewpoint_c[index];
        let u = column.u_ms[index];
        let v = column.v_ms[index];
        if !(p.is_finite()
            && z.is_finite()
            && t.is_finite()
            && td.is_finite()
            && u.is_finite()
            && v.is_finite())
        {
            continue;
        }
        let rounded = p.round();
        if !(1.0..=1100.0).contains(&rounded) {
            continue;
        }
        let level = rounded as u16;
        if levels_hpa.last().is_some_and(|&last| last == level) {
            continue;
        }
        levels_hpa.push(level);
        temperature_k.push((t + 273.15) as f32);
        dewpoint_k.push((td + 273.15) as f32);
        u_ms.push(u as f32);
        v_ms.push(v as f32);
        height_m.push(z as f32);
    }
    if levels_hpa.is_empty() {
        return Err("RAOB column has no usable levels above the surface".to_owned());
    }

    let profile = |name: &str, units: &str, values: Vec<f32>| rw_ui::ProfileVar {
        name: name.to_owned(),
        units: units.to_owned(),
        levels_hpa: levels_hpa.clone(),
        values,
    };
    let surface = |name: &str, units: &str, value: f32| rw_ui::SurfaceSample {
        name: name.to_owned(),
        units: units.to_owned(),
        value,
    };
    Ok(rw_ui::SoundingData {
        hour: rw_ui::HourKey {
            model: format!("{} RAOB", site.id),
            run: format!("{}{}", valid.format("%Y-%m-%d %Hz"), context),
            hour: 0,
        },
        fx: 0.0,
        fy: 0.0,
        lat: Some(site.lat),
        lon: Some(site.lon),
        vars: vec![
            profile("temperature_iso", "K", temperature_k),
            profile("dewpoint_iso", "K", dewpoint_k),
            profile("u_iso", "m/s", u_ms),
            profile("v_iso", "m/s", v_ms),
            profile("height_iso", "m", height_m),
        ],
        surface: vec![
            surface("temperature_2m", "K", tsfc_c + 273.15),
            surface("dewpoint_2m", "K", tdsfc_c + 273.15),
            surface("u_10m", "m/s", usfc_ms),
            surface("v_10m", "m/s", vsfc_ms),
            surface("surface_pressure", "Pa", psfc_hpa * 100.0),
            surface("orography", "m", zsfc_m),
            surface("mslp", "hPa", psfc_hpa),
        ],
        read_ms: 0.0,
    })
}

/// Light-by-default download spec: sounding profile, NO heavy ECAPE.
/// Heavy is ~5x the compute (all cores, minutes per hour on laptops) —
/// it must be an informed opt-in, never the default a new user trips on
/// (field report: "model data downloading is slow" = heavy by accident).
/// `model_slug` is the persisted last-used model; unknown or
/// not-ingest-supported slugs (hand-edited config) fall back to HRRR.
fn default_download_spec(model_slug: &str) -> rw_ui::DownloadSpec {
    let model = model_slug
        .parse::<rustwx_core::ModelId>()
        .ok()
        .filter(|&model| bowecho_model_download_supported(model))
        .unwrap_or(rustwx_core::ModelId::Hrrr);
    normalize_model_download_spec(rw_ui::DownloadSpec {
        model: model.as_str().to_owned(),
        profile: "sounding".to_owned(),
        heavy: false,
        hours: "0-3".to_owned(),
        // ABSOLUTE cache dir: the crate default ("out/cache") is relative,
        // which resolves inside the sealed read-only bundle on macOS
        // (field report: os error 30 on model downloads).
        cache_dir: settings::model_cache_dir().to_string_lossy().into_owned(),
        ..rw_ui::DownloadSpec::default()
    })
}

pub(crate) fn normalize_event_track_model_slug(model_slug: &str) -> String {
    let requested = match model_slug.trim().to_ascii_lowercase().as_str() {
        "rap" => rustwx_core::ModelId::Rap,
        _ => rustwx_core::ModelId::Hrrr,
    };
    if rw_ingest::ingest_supported(requested) {
        requested.as_str().to_owned()
    } else {
        rustwx_core::ModelId::Hrrr.as_str().to_owned()
    }
}

fn normalize_radar_station_id(site_id: &str) -> Option<String> {
    let site_id = site_id.trim().to_ascii_uppercase();
    (site_id.len() == 4 && site_id.bytes().all(|byte| byte.is_ascii_alphanumeric()))
        .then_some(site_id)
}

fn fetch_radar_operational_status(
    site_id: &str,
    fallback_name: Option<&str>,
) -> Result<RadarOperationalStatus, String> {
    let site_id = normalize_radar_station_id(site_id)
        .ok_or_else(|| format!("invalid radar station id '{site_id}'"))?;
    let station_url = format!("https://api.weather.gov/radar/stations/{site_id}");
    let alarms_url = format!("https://api.weather.gov/radar/stations/{site_id}/alarms");
    let station_text = data_source::fetch_text(&station_url)
        .map_err(|err| format!("station status fetch failed: {err}"))?;
    let alarms_text = data_source::fetch_text(&alarms_url)
        .map_err(|err| format!("station alarms fetch failed: {err}"))?;
    parse_radar_operational_status(&site_id, fallback_name, &station_text, &alarms_text)
}

fn parse_radar_operational_status(
    requested_site_id: &str,
    fallback_name: Option<&str>,
    station_text: &str,
    alarms_text: &str,
) -> Result<RadarOperationalStatus, String> {
    let requested_site_id = normalize_radar_station_id(requested_site_id)
        .ok_or_else(|| format!("invalid radar station id '{requested_site_id}'"))?;
    let station: WeatherGovRadarStationResponse = serde_json::from_str(station_text)
        .map_err(|err| format!("station status JSON parse failed: {err}"))?;
    let alarms: WeatherGovRadarAlarmsResponse = serde_json::from_str(alarms_text)
        .map_err(|err| format!("station alarms JSON parse failed: {err}"))?;

    let rda = station.properties.rda;
    let rda_properties = rda.as_ref().and_then(|rda| rda.properties.as_ref());
    let station_id = station
        .properties
        .id
        .as_deref()
        .and_then(normalize_radar_station_id)
        .unwrap_or(requested_site_id);
    let site_name = station
        .properties
        .name
        .as_deref()
        .or(fallback_name)
        .map(str::trim)
        .filter(|name| !name.is_empty())
        .unwrap_or(station_id.as_str())
        .to_owned();
    let rda_timestamp = rda
        .as_ref()
        .and_then(|rda| parse_radar_operational_timestamp(rda.timestamp.as_deref()));
    let mut alarm_rows = alarms
        .graph
        .into_iter()
        .filter(|alarm| {
            alarm
                .station_id
                .as_deref()
                .and_then(normalize_radar_station_id)
                .is_none_or(|alarm_site| alarm_site == station_id)
        })
        .filter_map(|alarm| {
            let message = alarm.message?.trim().to_owned();
            if message.is_empty() {
                return None;
            }
            Some(RadarOperationalAlarm {
                status: alarm.status.unwrap_or_default(),
                message,
                timestamp: parse_radar_operational_timestamp(alarm.timestamp.as_deref()),
            })
        })
        .collect::<Vec<_>>();
    alarm_rows.sort_by(|left, right| right.timestamp.cmp(&left.timestamp));

    Ok(RadarOperationalStatus {
        site_id: station_id,
        site_name,
        alarm_summary: rda_properties.and_then(|props| non_empty_string(&props.alarm_summary)),
        mode: rda_properties.and_then(|props| non_empty_string(&props.mode)),
        rda_status: rda_properties.and_then(|props| non_empty_string(&props.status)),
        operability_status: rda_properties
            .and_then(|props| non_empty_string(&props.operability_status)),
        rda_timestamp,
        alarms: alarm_rows,
    })
}

fn parse_radar_operational_timestamp(value: Option<&str>) -> Option<DateTime<Utc>> {
    DateTime::parse_from_rfc3339(value?)
        .ok()
        .map(|time| time.with_timezone(&Utc))
}

fn non_empty_string(value: &Option<String>) -> Option<String> {
    value
        .as_deref()
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .map(str::to_owned)
}

/// Classify a radar's operational health from the NWS RDA fields + active
/// alarm summary, returning the health bucket and a short human reason.
///
/// Grounded in the live `api.weather.gov/radar/stations` value space
/// (sampled 2026-07 across all 208 reporting sites): `operabilityStatus` is
/// one of {`RDA - On-line`, `RDA - Maintenance Action Required`, `RDA -
/// Maintenance Action Mandatory`, `RDA - Inoperable`}; `status` (RDA control
/// state) is {`Operate`, `Start-Up`, …}; `alarmSummary` is pipe-delimited
/// categories or `No Alarms`.
fn radar_operational_health(status: &RadarOperationalStatus) -> (RadarHealth, Option<String>) {
    let operability = status.operability_status.as_deref().unwrap_or("").trim();
    let rda_status = status.rda_status.as_deref().unwrap_or("").trim();
    let operability_lc = operability.to_ascii_lowercase();
    let rda_status_lc = rda_status.to_ascii_lowercase();

    // Operating = RDA in an active control state. Absent status is treated as
    // operating so a site that only publishes a nominal operabilityStatus is
    // not falsely flagged DOWN.
    let operating = rda_status_lc.is_empty()
        || rda_status_lc.contains("operate")
        || rda_status_lc.contains("operational");

    // DOWN: RDA reports itself inoperable, or is not actively operating
    // (Start-Up / Standby / Offline / Restart) — no usable base data.
    if operability_lc.contains("inoperable") || !operating {
        let reason = if !operability.is_empty() {
            operability.to_owned()
        } else {
            format!("RDA status: {rda_status}")
        };
        return (RadarHealth::Down, Some(reason));
    }

    // DEGRADED: still operating but flagged for maintenance, or carrying an
    // active alarm summary.
    let alarm = status
        .alarm_summary
        .as_deref()
        .map(str::trim)
        .filter(|summary| !summary.is_empty() && !summary.eq_ignore_ascii_case("No Alarms"));
    if operability_lc.contains("maintenance") || alarm.is_some() {
        let reason = alarm
            .map(str::to_owned)
            .or_else(|| (!operability.is_empty()).then(|| operability.to_owned()));
        return (RadarHealth::Degraded, reason);
    }

    if operability.is_empty() && rda_status.is_empty() {
        (RadarHealth::Unknown, None)
    } else {
        (RadarHealth::Operational, None)
    }
}

/// The colored health chip ("DOWN" / "DEGRADED" / …) shared by the status
/// panel and the best-radar context menu.
fn draw_radar_health_chip(ui: &mut egui::Ui, health: RadarHealth) {
    ui.label(
        egui::RichText::new(format!(" {} ", health.label()))
            .small()
            .strong()
            .background_color(health.color().gamma_multiply(0.35))
            .color(health.color()),
    );
}

fn draw_radar_operational_status_rows(ui: &mut egui::Ui, status: &RadarOperationalStatus) {
    let rda_time = status
        .rda_timestamp
        .map(format_utc_seconds)
        .unwrap_or_else(|| "time unknown".to_owned());
    let (health, reason) = radar_operational_health(status);
    ui.horizontal(|ui| {
        draw_radar_health_chip(ui, health);
        ui.monospace(format!("{} {}", status.site_id, status.site_name));
    });
    if let Some(reason) = reason {
        ui.colored_label(health.color(), reason);
    } else if let Some(alarm_summary) = &status.alarm_summary {
        ui.monospace(format!("Alarm: {alarm_summary}"));
    }
    let mut state_parts = Vec::new();
    if let Some(operability) = &status.operability_status {
        state_parts.push(operability.as_str());
    }
    if let Some(mode) = &status.mode {
        state_parts.push(mode.as_str());
    }
    if let Some(rda_status) = &status.rda_status {
        state_parts.push(rda_status.as_str());
    }
    if !state_parts.is_empty() {
        ui.weak(format!("{} - {rda_time}", state_parts.join(" | ")));
    }

    let alarms =
        radar_operational_display_alarms(&status.alarms, RADAR_OPERATIONAL_STATUS_DISPLAY_ROWS);
    if alarms.is_empty() {
        ui.weak("No recent alarm messages");
        return;
    }
    for alarm in alarms {
        let timestamp = alarm
            .timestamp
            .map(format_utc_seconds)
            .unwrap_or_else(|| "time unknown".to_owned());
        let line = format!("{} ({timestamp})", alarm.message);
        let response = ui.monospace(line);
        if !alarm.status.trim().is_empty() {
            response.on_hover_text(format!("status: {}", alarm.status));
        }
    }
}

fn radar_operational_display_alarms(
    alarms: &[RadarOperationalAlarm],
    limit: usize,
) -> Vec<&RadarOperationalAlarm> {
    let mut seen = BTreeSet::new();
    let mut rows = Vec::new();
    for alarm in alarms {
        let key = (
            alarm.message.trim().to_ascii_uppercase(),
            alarm.status.trim().to_ascii_lowercase(),
        );
        if seen.insert(key) {
            rows.push(alarm);
            if rows.len() >= limit {
                break;
            }
        }
    }
    rows
}

#[cfg(test)]
fn nearest_site_index(sites: &[RadarSite], target_lat: f32, target_lon: f32) -> Option<usize> {
    sites
        .iter()
        .enumerate()
        .filter_map(|(index, site)| {
            let (latitude_deg, longitude_deg) = site_location(site)?;
            let distance_km = haversine_km(target_lat, target_lon, latitude_deg, longitude_deg);
            Some((index, distance_km))
        })
        .min_by(|left, right| left.1.total_cmp(&right.1))
        .map(|(index, _)| index)
}

