    /// The live-chunk readout row must reserve the SAME height whether or
    /// not there is a readout to show. The line only exists for the live
    /// partial frame, so before the fix it appeared for the latest frame
    /// and vanished while looping/scrubbing — moving every control below it
    /// and causing misclicks (field report). Measured through a real egui
    /// layout pass.
    #[test]
    fn live_chunk_readout_row_reserves_a_stable_height() {
        fn measure(readout: Option<String>) -> f32 {
            let ctx = egui::Context::default();
            let screen = egui::Rect::from_min_size(egui::pos2(0.0, 0.0), egui::vec2(400.0, 400.0));
            let mut height = 0.0_f32;
            // Two passes: the first settles the default font atlas so the
            // second pass's galley metrics are trustworthy.
            for _ in 0..2 {
                let input = egui::RawInput {
                    screen_rect: Some(screen),
                    ..Default::default()
                };
                let _ = ctx.run_ui(input, |ui| {
                    height = live_chunk_readout_row(ui, readout.clone()).rect.height();
                });
            }
            height
        }

        let with_readout = measure(Some(
            "last chunk 23:57:10Z age 3s chunks 66 id 66 intermediate".to_owned(),
        ));
        let without = measure(None);
        assert!(with_readout > 0.0, "the row always occupies a line");
        assert!(
            (with_readout - without).abs() < 0.5,
            "live and past frames must reserve the same height: {with_readout} vs {without}"
        );
    }

    /// The archive/backfill progress slot must reserve the SAME height
    /// whether a load is running (bar or spinner) or not. A loop/preload
    /// backfill finishing mid-interaction used to make the bar vanish and
    /// shift every control below it — the reported misclick source.
    #[test]
    fn archive_load_progress_slot_height_is_stable() {
        fn measure(progress: Option<ArchiveLoadProgress>) -> f32 {
            let ctx = egui::Context::default();
            let screen = egui::Rect::from_min_size(egui::pos2(0.0, 0.0), egui::vec2(400.0, 400.0));
            let mut height = 0.0_f32;
            for _ in 0..2 {
                let input = egui::RawInput {
                    screen_rect: Some(screen),
                    ..Default::default()
                };
                let _ = ctx.run_ui(input, |ui| {
                    height = archive_load_progress_slot(ui, progress.as_ref())
                        .rect
                        .height();
                });
            }
            height
        }

        let determinate = ArchiveLoadProgress {
            label: "L2 loop".to_owned(),
            detail: "loading".to_owned(),
            done: 3,
            total: 7,
        };
        let bar = measure(Some(determinate));
        let spinner = measure(Some(ArchiveLoadProgress::latest_loop_start("KTLX")));
        let idle = measure(None);
        assert!(idle > 0.0, "the slot always reserves its height");
        assert!(
            (bar - idle).abs() < 0.5 && (spinner - idle).abs() < 0.5,
            "loading and idle must reserve the same height: bar {bar} spinner {spinner} idle {idle}"
        );
    }

    #[test]
    fn background_taiwan_cwa_refresh_does_not_hijack_the_global_status_bar() {
        let ctx = egui::Context::default();
        let mut app = test_viewer_app_with_hazards(Vec::new());
        let mut layer = TaiwanCwaMapLayer::new();
        // Fresh attempt stamp keeps the poll's visible-layer gate from
        // spawning a real network refresh inside the test.
        layer.last_refresh_attempt = Some(Instant::now());
        app.taiwan_cwa_layer = Some(layer);
        app.status = "KTLX REF loaded".to_owned();

        // Background 60-s auto-refresh completion (announce_status = false):
        // the rail carries the result; the global status bar stays untouched.
        let (sender, receiver) = mpsc::channel();
        app.taiwan_cwa_latest_rx.inject_for_test(receiver);
        sender.send(Err("listing throttled".to_owned())).unwrap();
        app.poll_taiwan_cwa_layer(&ctx);

        assert_eq!(app.status, "KTLX REF loaded");
        let error = app
            .taiwan_cwa_layer
            .as_ref()
            .and_then(|layer| layer.error.clone());
        assert_eq!(error.as_deref(), Some("listing throttled"));

        // User-initiated loads (layer add / rail refresh) still announce:
        // the WorkerSlot job only sends the result — this status string is
        // written by the drain site (spec §11.B.3).
        let layer = app.taiwan_cwa_layer.as_mut().expect("layer");
        layer.announce_status = true;
        layer.last_refresh_attempt = Some(Instant::now());
        let (sender, receiver) = mpsc::channel();
        app.taiwan_cwa_latest_rx.inject_for_test(receiver);
        sender.send(Err("listing throttled".to_owned())).unwrap();
        app.poll_taiwan_cwa_layer(&ctx);

        assert_eq!(app.status, "Taiwan CWA: listing throttled");
        // The Ready drain cleared the slot — no half-drained states.
        assert!(!app.taiwan_cwa_latest_rx.in_flight());
    }

    /// Bolton (1980) round-trip sanity: saturated air dews at the air
    /// temperature; the textbook 20 °C / 50% case lands at ≈9.3 °C.
    #[test]
    fn dewpoint_from_rh_matches_bolton() {
        let saturated = dewpoint_k_from_rh(293.15, 100.0);
        assert!((saturated - 293.15).abs() < 0.05, "got {saturated}");
        let half = dewpoint_k_from_rh(293.15, 50.0) - 273.15;
        assert!(
            (half - 9.27).abs() < 0.1,
            "20C/50%% -> {half} C, want ~9.27"
        );
        let cold = dewpoint_k_from_rh(253.15, 70.0) - 273.15;
        assert!((-24.5..=-22.5).contains(&cold), "-20C/70%% -> {cold} C");
        // Dewpoint never exceeds temperature.
        assert!(dewpoint_k_from_rh(300.0, 100.0) <= 300.0 + 0.05);
    }

    /// The GFS rh_iso -> dewpoint_iso shim: synthesizes only when needed,
    /// on rh's levels, skipping levels temperature does not share.
    #[test]
    fn synthesized_dewpoint_covers_rh_only_stores() {
        let var = |name: &str, units: &str, levels: Vec<u16>, values: Vec<f32>| rw_ui::ProfileVar {
            name: name.to_owned(),
            units: units.to_owned(),
            levels_hpa: levels,
            values,
        };
        let data = |vars: Vec<rw_ui::ProfileVar>| rw_ui::SoundingData {
            hour: rw_ui::HourKey {
                model: "gfs".to_owned(),
                run: "20260612_00z".to_owned(),
                hour: 7,
            },
            fx: 0.0,
            fy: 0.0,
            lat: None,
            lon: None,
            vars,
            surface: Vec::new(),
            read_ms: 0.0,
        };
        // RH-only store (GFS): synthesize on rh's levels.
        let gfs = data(vec![
            var(
                "temperature_iso",
                "K",
                vec![1000, 850, 500],
                vec![293.15, 283.15, 253.15],
            ),
            var("rh_iso", "%", vec![1000, 850, 700], vec![100.0, 50.0, 80.0]),
        ]);
        let out = with_synthesized_dewpoint(&gfs).expect("synthesizes for rh-only");
        let dew = out
            .vars
            .iter()
            .find(|v| v.name == "dewpoint_iso")
            .expect("dewpoint var added");
        assert_eq!(dew.units, "K");
        assert_eq!(dew.levels_hpa, vec![1000, 850, 700]);
        assert!((dew.values[0] - 293.15).abs() < 0.05, "saturated 1000 hPa");
        assert!(dew.values[1] < 283.15, "subsaturated dewpoint below T");
        assert!(dew.values[2].is_nan(), "700 hPa has no temperature: NaN");
        // Store already carries dewpoint (HRRR): no-op.
        let hrrr = data(vec![
            var("temperature_iso", "K", vec![1000], vec![293.15]),
            var("dewpoint_iso", "K", vec![1000], vec![283.15]),
        ]);
        assert!(with_synthesized_dewpoint(&hrrr).is_none());
        // No moisture at all: nothing to synthesize.
        let dry = data(vec![var("temperature_iso", "K", vec![1000], vec![293.15])]);
        assert!(with_synthesized_dewpoint(&dry).is_none());
    }

