    /// Golden parity net for the style-registry refactor: an EMPTY style
    /// document must resolve every legacy hard-coded hazard constant
    /// exactly — colors, widths, alphas. If a styles-crate default drifts,
    /// this is the test that catches it.
    #[test]
    fn default_styles_pin_legacy_hazard_constants() {
        let registry = styles::StyleRegistry::default();
        let record = |family: &str, threat: Option<&str>| {
            let mut record = test_hazard_record(
                "id",
                "label",
                family,
                square_hazard_points(-98.0, 34.0, -97.0, 35.0),
            );
            record.damage_threat = threat.map(str::to_owned);
            record
        };
        type GoldenRow = (&'static str, Option<&'static str>, (u8, u8, u8));
        let expected: &[GoldenRow] = &[
            // Damage-threat escalation ladder.
            ("tornado", Some("CATASTROPHIC"), (150, 50, 250)), // TOR EMERGENCY purple
            ("tornado", Some("CONSIDERABLE"), (255, 64, 175)), // PDS magenta
            ("tornado", None, (248, 62, 82)),
            ("severe thunderstorm", Some("CONSIDERABLE"), (255, 152, 42)),
            ("severe thunderstorm", Some("DESTRUCTIVE"), (252, 122, 28)),
            ("severe thunderstorm", None, (246, 183, 57)),
            // Base family table.
            ("flash flood", None, (78, 218, 108)),
            ("flash flood", Some("CONSIDERABLE"), (42, 224, 154)),
            ("flash flood", Some("CATASTROPHIC"), (22, 188, 126)),
            ("flood", None, (76, 190, 124)),
            ("flood", Some("CONSIDERABLE"), (50, 205, 160)),
            ("flood", Some("CATASTROPHIC"), (24, 160, 130)),
            ("fire weather", None, (255, 126, 46)),
            ("special marine", None, (70, 190, 238)),
            ("snow squall", None, (170, 210, 255)),
            ("watch", None, (235, 92, 245)),
            ("watch", Some("tornado"), (210, 82, 245)),
            ("watch", Some("severe-thunderstorm"), (246, 183, 57)),
            ("mesoscale discussion", None, (95, 174, 255)),
            ("local storm report", None, (245, 245, 245)),
            ("special weather", None, (245, 220, 72)),
            ("text polygon", None, (190, 178, 255)),
            ("anything else", None, (232, 232, 96)),
        ];
        for (family, threat, (r, g, b)) in expected {
            assert_eq!(
                hazard_color(&registry, &record(family, *threat)),
                egui::Color32::from_rgb(*r, *g, *b),
                "stroke color for {family} / {threat:?}"
            );
        }

        // Stroke geometry: width 1.5 unselected, 2.4 selected (1.5 + 0.9
        // boost); stroke alphas 205 / 245; default fill alpha 24.
        let style = registry.hazard_polygon("tornado", None);
        let global = registry.hazard_global();
        let unselected_width = style.stroke_width * global.stroke_width_scale;
        let selected_width = unselected_width + global.selected_width_boost;
        assert_eq!(unselected_width, 1.5);
        assert_eq!(selected_width, 2.4);
        assert_eq!(global.stroke_alpha, 205);
        assert_eq!(global.stroke_alpha_selected, 245);
        assert_eq!(global.fill_alpha, 24);
        // Fill defaults to the stroke color until overridden.
        assert_eq!(style.fill_color, style.stroke_color);
        assert_eq!(style.fill_alpha, None);
    }

    /// Palette persistence: saved family bindings restore on boot; a
    /// missing table name (deleted .pal) falls back to the default and is
    /// reported instead of breaking the slot.
    #[test]
    fn palette_binding_restore_falls_back_on_missing_table() {
        let mut set = ColorTableSet::default();
        let default_ref_name = set
            .for_family(ColorTableFamily::Reflectivity)
            .name()
            .to_owned();
        let mut bindings = BTreeMap::new();
        bindings.insert(
            ColorTableFamily::Velocity.label().to_owned(),
            "Balance VEL (CVD-safe)".to_owned(),
        );
        bindings.insert(
            ColorTableFamily::Reflectivity.label().to_owned(),
            "Deleted Table".to_owned(),
        );
        let misses = restore_palette_bindings(&mut set, &bindings, &[]);
        assert_eq!(
            set.for_family(ColorTableFamily::Velocity).name(),
            "Balance VEL (CVD-safe)"
        );
        assert_eq!(
            set.for_family(ColorTableFamily::Reflectivity).name(),
            default_ref_name,
            "missing binding must leave the default in place"
        );
        assert_eq!(misses.len(), 1);
        assert!(misses[0].contains("Deleted Table"), "{}", misses[0]);
    }

    /// Field report: "make it so when you restart the app the color table
    /// saves". The save side writes table.name() into config.json
    /// (apply_family_table); this pins the restore side: every name any
    /// picker can offer must resolve back to the same table on boot.
    #[test]
    fn every_builtin_table_survives_a_restart_round_trip() {
        for family in ColorTableFamily::ALL {
            for table in builtin_tables_for_family(family) {
                let resolved =
                    resolve_palette_binding(family, table.name(), &[]).unwrap_or_else(|| {
                        panic!(
                            "{} table {:?} did not resolve by name",
                            family.label(),
                            table.name()
                        )
                    });
                assert_eq!(resolved.name(), table.name());
            }
        }
    }

    /// A velocity palette's declared `Units:` is the display unit (GR2A
    /// semantics): mph tables read out and tick in mph; SI and non-m/s
    /// products are identity.
    #[test]
    fn table_display_unit_follows_the_declared_palette_units() {
        let mph = ColorTable::parse_gr_pal(
            "MPH VEL",
            "Product: BV\nUnits: MPH\nColor: -89 12 24 36\nColor: 89 200 210 220\n",
        )
        .expect("mph table parses");
        let product = DisplayProduct::Moment(MomentType::Velocity);
        let (label, scale) = table_display_unit(&mph, &product, units::Units::Imperial);
        assert_eq!(label, "mph");
        // Stops scaled into m/s at parse; display divides back to ±89.
        let vmax = mph.stops().last().expect("stops").value;
        assert!((vmax - 39.79).abs() < 0.05, "internal vmax {vmax}");
        assert!(
            (vmax / scale - 89.0).abs() < 0.01,
            "display vmax {} (scale {scale})",
            vmax / scale
        );

        let si = ColorTable::parse_gr_pal("SI VEL", "Color: -30 1 2 3\nColor: 30 4 5 6\n")
            .expect("si table parses");
        assert_eq!(
            table_display_unit(&si, &product, units::Units::Imperial),
            ("mph", color_tables::unit_scale_to_internal("mph"))
        );
        assert_eq!(
            table_display_unit(&si, &product, units::Units::Metric),
            ("km/h", color_tables::unit_scale_to_internal("km/h"))
        );
        let kmh = ColorTable::parse_gr_pal(
            "KMH VEL",
            "Product: BV\nUnits: km/h\nColor: -120 1 2 3\nColor: 120 4 5 6\n",
        )
        .expect("km/h table parses");
        assert_eq!(
            table_display_unit(&kmh, &product, units::Units::Metric),
            ("km/h", color_tables::unit_scale_to_internal("km/h"))
        );
        let mps = ColorTable::parse_gr_pal(
            "MPS VEL",
            "Product: BV\nUnits: m/s\nColor: -30 1 2 3\nColor: 30 4 5 6\n",
        )
        .expect("m/s table parses");
        assert_eq!(
            table_display_unit(&mps, &product, units::Units::Metric),
            ("m/s", 1.0),
            "explicit velocity-table m/s must not fall back to metric km/h"
        );
        assert_eq!(
            table_display_unit(&mps, &product, units::Units::Imperial),
            ("m/s", 1.0),
            "explicit velocity-table m/s must override general imperial units too"
        );
        // Non-m/s products never rescale off the table's declaration.
        let dbz = DisplayProduct::Moment(MomentType::Reflectivity);
        assert_eq!(
            table_display_unit(&mph, &dbz, units::Units::Imperial),
            ("dBZ", 1.0)
        );
    }

    /// Settings ▸ Display answers "where is m/s?": when the active velocity
    /// table declares its units, a footnote says the table governs; when it
    /// does not, velocity follows the Units setting and no note appears.
    #[test]
    fn velocity_units_note_shows_only_when_the_table_declares_units() {
        let product = DisplayProduct::Moment(MomentType::Velocity);
        let kt = ColorTable::parse_gr_pal(
            "KT VEL",
            "Product: BV\nUnits: KTS\nColor: -89 12 24 36\nColor: 89 200 210 220\n",
        )
        .expect("kt table parses");
        assert_eq!(table_declared_velocity_unit(&kt, &product), Some("kt"));
        let mps = ColorTable::parse_gr_pal(
            "MPS VEL",
            "Product: BV\nUnits: m/s\nColor: -30 1 2 3\nColor: 30 4 5 6\n",
        )
        .expect("m/s table parses");
        assert_eq!(table_declared_velocity_unit(&mps, &product), Some("m/s"));
        // Undeclared table: the Units setting governs — no note.
        let si = ColorTable::parse_gr_pal("SI VEL", "Color: -30 1 2 3\nColor: 30 4 5 6\n")
            .expect("si table parses");
        assert_eq!(table_declared_velocity_unit(&si, &product), None);
        // Non-velocity products never claim the note.
        let dbz = DisplayProduct::Moment(MomentType::Reflectivity);
        assert_eq!(table_declared_velocity_unit(&kt, &dbz), None);

        let note = velocity_units_settings_note("kt", "KT VEL");
        assert!(note.contains("Velocity display: kt"), "{note}");
        assert!(note.contains("KT VEL"), "{note}");
        assert!(note.contains("follow this setting"), "{note}");

        // App wiring: the note derives from the CURRENT velocity product's
        // active table (per-product override included).
        let mut app = test_viewer_app_with_hazards(Vec::new());
        app.selected_product = DisplayProduct::Moment(MomentType::Reflectivity);
        app.palette_product_overrides
            .insert(product.label().to_owned(), kt);
        let note = app
            .velocity_units_note_for_settings()
            .expect("declared table note");
        assert!(note.contains("Velocity display: kt"), "{note}");
        assert!(note.contains("KT VEL"), "{note}");
        app.palette_product_overrides
            .insert(product.label().to_owned(), si);
        assert_eq!(app.velocity_units_note_for_settings(), None);
    }

