    #[test]
    fn low_level_auto_advance_accepts_sails_revisit_but_ignores_short_lag_and_high_tilts() {
        let product = DisplayProduct::Moment(MomentType::Reflectivity);
        let previous = test_reflectivity_sails_volume_with_radials(&[(0.5, 0)], 720);
        let sails_revisit =
            test_reflectivity_sails_volume_with_radials(&[(0.5, 0), (0.5, 86_000)], 720);
        let short_lag =
            test_reflectivity_sails_volume_with_radials(&[(0.5, 0), (0.7, 30_000)], 720);
        let later_low_companion =
            test_reflectivity_sails_volume_with_radials(&[(0.5, 0), (1.3, 180_000)], 720);
        let high_tilt =
            test_reflectivity_sails_volume_with_radials(&[(0.5, 0), (1.8, 180_000)], 720);

        assert_eq!(
            selection_for_installed_volume(
                Some(&previous),
                0,
                &product,
                &sails_revisit,
                true,
                false,
                false,
            ),
            (1, product.clone())
        );
        assert_eq!(
            selection_for_installed_volume(
                Some(&previous),
                0,
                &product,
                &short_lag,
                true,
                false,
                false,
            ),
            (0, product.clone())
        );
        assert_eq!(
            selection_for_installed_volume(
                Some(&previous),
                0,
                &product,
                &later_low_companion,
                true,
                false,
                false,
            ),
            (0, product.clone()),
            "live auto-advance should stay in the selected low-elevation family, not jump to a later 1.3 deg companion cut"
        );
        assert_eq!(
            selection_for_installed_volume(
                Some(&previous),
                0,
                &product,
                &high_tilt,
                true,
                false,
                false,
            ),
            (0, product)
        );
    }

