    /// Audit #11: a 🎨 user-bound palette is compiled into the field's
    /// production style by the store worker, so Solar must yield to it —
    /// user override → Solar → production → generic. Untouched WRF fields
    /// (no binding) keep Solar; this fails on the old two-arg resolver,
    /// which reinstalled Solar over every WRF production style.
    #[test]
    fn user_bound_palette_beats_solar_for_wrf_fields() {
        let mut field = test_model_field("wrf", "20260519_00z", 0).as_ref().clone();
        field.key.var = "temperature_2m".to_owned();
        field.units = "K".to_owned();
        // Untouched WRF field: Solar outranks the production style.
        assert!(model_layer_solar_table(&field, true, false).is_some());
        // User-bound palette: Solar yields, so the production colormap
        // (= the user's table) is what the paint chain reaches.
        assert!(model_layer_solar_table(&field, true, true).is_none());
        assert!(model_layer_solar_table(&field, false, true).is_none());
    }

    /// Audit #11 wiring: the dock detects an editor binding exactly like the
    /// store worker's `style_for_store_variable` (same candidates, same
    /// bound-table lookup), including the persisted-settings restore path.
    #[test]
    fn dock_reports_user_style_override_for_bound_products() {
        let ctx = egui::Context::default();
        let mut dock = model_data::ModelDataDock::new_for_test(
            &ctx,
            test_model_store_tree("wrf", "20260519_00z", &[0]),
        );
        let mut field = test_model_field("wrf", "20260519_00z", 0).as_ref().clone();
        field.key.var = "temperature_2m".to_owned();
        field.units = "K".to_owned();
        assert!(!dock.user_style_override_for(&field));

        let mut settings = rw_ui::StyleOverrideSettings::default();
        settings.upsert_table(rw_ui::UserColorTable::simple("My temp", "My temp", "K"));
        settings.bind_product(&rw_ui::normalize_product_key("temperature_2m"), "My temp");
        assert!(
            dock.apply_style_overrides_json(
                &serde_json::to_value(&settings).expect("serialize overrides")
            ),
            "restore path must accept the settings"
        );

        assert!(dock.user_style_override_for(&field));
        // Other variables stay untouched (they keep Solar).
        let mut other = field.clone();
        other.key.var = "dewpoint_2m".to_owned();
        assert!(!dock.user_style_override_for(&other));
    }

    /// Audit #9: the inspector color chip must report the SAME color the map
    /// raster paints. For a WRF layer the raster uses the Solar model table,
    /// which the chip historically skipped (it fell through to the
    /// production style) — this pins chip == painted == Solar, not
    /// production.
    #[test]
    fn inspector_chip_matches_painted_color_for_solar_wrf_layer() {
        let app = test_viewer_app_with_hazards(Vec::new());
        let mut field = test_model_field("wrf", "20260519_00z", 0).as_ref().clone();
        field.key.var = "temperature_2m".to_owned();
        field.units = "K".to_owned();
        field.range = Some((250.0, 310.0));
        let field = Arc::new(field);

        // A flat-red production style that CANNOT be mistaken for Solar.
        let production_style = rw_ui::UserColorTable {
            name: "flat red".into(),
            title: "flat red".into(),
            display_units: "K".into(),
            convert: rw_ui::UserUnitConvert::None,
            legend_mode: rw_ui::UserLegendMode::Stepped,
            extend: rw_ui::UserExtendMode::Both,
            mask_below: None,
            tick_step: None,
            levels: vec![200.0, 350.0],
            colors: vec![[255, 0, 0, 255]],
        }
        .to_store_style("flat red", "K")
        .expect("production style");

        let mut slot = test_model_layer("wrf", "20260519_00z", 0);
        slot.layer.field = Arc::clone(&field);
        slot.layer.production = Some(Arc::new(rustwx_render::build_colormap(
            &production_style.scale,
            production_style.colormap_options,
        )));
        slot.layer.model_table = model_layer_solar_table(field.as_ref(), true, false);
        assert!(
            slot.layer.model_table.is_some(),
            "WRF temperature must resolve a Solar table"
        );

        let value = 273.15_f32;
        let chip = app
            .model_layer_color_for_value(&slot.layer, value)
            .expect("chip color");
        let painted = model_layer_value_color(
            None,
            slot.layer.model_table.as_deref(),
            slot.layer.production.as_deref(),
            slot.layer.field.range,
            slot.layer.colormap,
            value,
        )
        .expect("painted color");
        assert_eq!(
            chip,
            painted.to_array(),
            "chip must equal the painted pixel"
        );
        // 273.15 K == 32 °F → Solar's freezing teal anchor #0F4454 — and
        // decidedly NOT the production red the old chip reported.
        assert_eq!(chip[..3], [0x0f, 0x44, 0x54]);
        assert_ne!(chip[..3], [255, 0, 0]);

        // With a user override active the Solar table is not installed, and
        // chip == painted == the user's production red.
        slot.layer.model_table = model_layer_solar_table(field.as_ref(), true, true);
        assert!(slot.layer.model_table.is_none());
        let chip = app
            .model_layer_color_for_value(&slot.layer, value)
            .expect("chip color");
        assert_eq!(chip[..3], [255, 0, 0]);
    }

    /// REAL-DATA verification (ignored in CI — needs a wrfout on disk). Point
    /// `BOWECHO_WRF_TEST_FILE` at a raw wrfout and run:
    ///
    /// ```text
    /// BOWECHO_WRF_TEST_FILE=".../wrfout_d02_2026-05-19_00_00_00" \
    ///   cargo test -p app_ui --bin bowecho -- --ignored --nocapture wrf_real
    /// ```
    ///
    /// It pulls each field through `wrf-core` (the SAME reader the WRF ingest
    /// uses), resolves the Solar palette exactly as `model_layer_solar_table`
    /// would, samples the real values into a PNG per field (written next to the
    /// wrfout under `bowecho_solar_verify/`), and asserts each field renders in
    /// its Solar palette instead of the generic default.
    #[test]
    #[ignore = "needs a real wrfout via BOWECHO_WRF_TEST_FILE"]
    fn wrf_real_fields_render_in_solar_palettes() {
        let path = std::env::var("BOWECHO_WRF_TEST_FILE")
            .expect("set BOWECHO_WRF_TEST_FILE to a wrfout path");
        let file = wrf_core::WrfFile::open(&path).expect("open wrfout");
        let out_dir = std::path::Path::new(&path)
            .parent()
            .unwrap_or_else(|| std::path::Path::new("."))
            .join("bowecho_solar_verify");
        std::fs::create_dir_all(&out_dir).expect("make output dir");

        // (getvar name, store var name the app writes, forced units or None).
        let fields: &[(&str, &str, Option<&str>)] = &[
            ("maxdbz", "composite_reflectivity", Some("dBZ")),
            ("t2", "temperature_2m", Some("K")),
            ("dp2m", "dewpoint_2m", Some("K")),
            ("wspd10", "wind_speed_10m", Some("m/s")),
            ("rh2m", "relative_humidity_2m", Some("%")),
            ("pw", "pwat", None),
            ("sbcape", "sbcape", None),
        ];

        for &(getvar_name, store_name, forced_units) in fields {
            let opts = wrf_core::ComputeOpts {
                units: forced_units.map(str::to_owned),
                ..Default::default()
            };
            let output = match wrf_core::getvar(&file, getvar_name, Some(0), &opts) {
                Ok(output) => output,
                Err(err) => {
                    eprintln!("[skip] {getvar_name}: {err}");
                    continue;
                }
            };
            let (ny, nx) = match output.shape.as_slice() {
                [ny, nx] => (*ny, *nx),
                [1, ny, nx] => (*ny, *nx),
                other => panic!("{getvar_name}: unexpected shape {other:?}"),
            };
            let units = forced_units.unwrap_or(&output.units).to_owned();
            let values: Vec<f32> = output
                .data
                .iter()
                .map(|&v| {
                    if !v.is_finite() || v.abs() >= 1.0e30 {
                        f32::NAN
                    } else {
                        v as f32
                    }
                })
                .collect();

            // Resolve the palette exactly as the map layer would.
            let field = rw_ui::FieldData {
                key: rw_ui::FieldKey {
                    hour: rw_ui::HourKey {
                        model: "wrf".to_owned(),
                        run: "verify".to_owned(),
                        hour: 0,
                    },
                    var: store_name.to_owned(),
                },
                units: units.clone(),
                nx,
                ny,
                values: values.clone(),
                range: None,
                grid: None,
                lat_descending: true,
                style: None,
            };
            let table = model_layer_solar_table(&field, false, false)
                .unwrap_or_else(|| panic!("{store_name} ({units}) must resolve a Solar palette"));

            // Field stats over finite values.
            let finite: Vec<f32> = values.iter().copied().filter(|v| v.is_finite()).collect();
            let (mut lo, mut hi, mut sum) = (f32::INFINITY, f32::NEG_INFINITY, 0.0f64);
            for &v in &finite {
                lo = lo.min(v);
                hi = hi.max(v);
                sum += f64::from(v);
            }
            let mean = sum / finite.len().max(1) as f64;

            // Render to PNG (row 0 at top).
            let mut img = image::RgbaImage::new(nx as u32, ny as u32);
            let mut opaque = 0u64;
            let mut colors = std::collections::HashSet::new();
            for (i, &v) in values.iter().enumerate() {
                let [r, g, b, a] = table.sample(v).to_array();
                if a > 0 {
                    opaque += 1;
                    colors.insert([r, g, b]);
                }
                let (x, y) = ((i % nx) as u32, (i / nx) as u32);
                img.put_pixel(x, y, image::Rgba([r, g, b, a]));
            }
            let png = out_dir.join(format!("{store_name}.png"));
            img.save(&png).expect("write png");
            eprintln!(
                "{store_name:>22} [{units:>6}] {nx}x{ny}  min={lo:.2} mean={mean:.2} max={hi:.2}  \
                 opaque={:.0}%  distinct_colors={}  -> {}",
                100.0 * opaque as f64 / values.len() as f64,
                colors.len(),
                png.display()
            );

            // A field that actually varies must produce a genuine multi-color
            // Solar ramp, not a flat/blank default. A near-constant field
            // (e.g. reflectivity all -30 dBZ at model init) legitimately paints
            // nothing / one color — report it but don't fail on missing weather.
            if hi - lo > 1.0e-3 {
                assert!(opaque > 0, "{store_name}: varies but nothing painted");
                assert!(
                    colors.len() >= 4,
                    "{store_name}: only {} distinct colors — palette not applied",
                    colors.len()
                );
            } else {
                eprintln!("    (near-constant field — no weather to render)");
            }
        }

        // Spot-check the exact Solar anchor colors on the reflectivity + temp
        // tables (unit-aware) so the mapping is provably faithful.
        let refl = color_tables::solar_reflectivity_table();
        assert_eq!(refl.sample(41.0).to_array()[..3], [0xee, 0xb2, 0x47]); // 40-42.5 bin
        let temp = model_layer_solar_table(
            &rw_ui::FieldData {
                key: rw_ui::FieldKey {
                    hour: rw_ui::HourKey {
                        model: "wrf".to_owned(),
                        run: "verify".to_owned(),
                        hour: 0,
                    },
                    var: "temperature_2m".to_owned(),
                },
                units: "K".to_owned(),
                nx: 1,
                ny: 1,
                values: vec![273.15],
                range: None,
                grid: None,
                lat_descending: true,
                style: None,
            },
            false,
            false,
        )
        .expect("temp table");
        // 273.15 K == 32 °F -> Solar's freezing teal anchor #0F4454.
        assert_eq!(temp.sample(273.15).to_array()[..3], [0x0f, 0x44, 0x54]);
    }

    /// REAL-DATA verification for audit fixes #9 + #11 (ignored in CI —
    /// needs a wrfout on disk). Run in RELEASE:
    ///
    /// ```text
    /// BOWECHO_WRF_TEST_FILE=".../wrfout_d01_2026-05-18_18_06_00" \
    ///   cargo test -p app_ui --bin bowecho --profile release-fast -- \
    ///   --ignored --nocapture wrf_real_chip_and_user_override
    /// ```
    ///
    /// Pulls REAL 2 m temperature through `wrf-core` and renders it through
    /// the exact map-layer resolution chain, writing proof PNGs to
    /// `BOWECHO_PROOF_DIR` (default `bowecho_proof_9_11/` next to the
    /// wrfout):
    ///   1_solar_painted.png — untouched WRF field, the raster the map paints
    ///     (Solar palette);
    ///   2_solar_chip.png — the SAME field with every pixel resolved through
    ///     the inspector chip; asserted byte-identical to 1 (#9 — the old
    ///     chip fell through to production/generic here);
    ///   3_user_override.png — a 🎨 user-bound palette resolved through the
    ///     REAL `style_for_store_variable` chain; asserted to differ from 1
    ///     and to keep chip == painted (#11 — the old resolver repainted
    ///     this with Solar).
    #[test]
    #[ignore = "needs a real wrfout via BOWECHO_WRF_TEST_FILE"]
    fn wrf_real_chip_and_user_override_render() {
        let path = std::env::var("BOWECHO_WRF_TEST_FILE")
            .expect("set BOWECHO_WRF_TEST_FILE to a wrfout path");
        let file = wrf_core::WrfFile::open(&path).expect("open wrfout");
        let out_dir = std::env::var("BOWECHO_PROOF_DIR")
            .map(std::path::PathBuf::from)
            .unwrap_or_else(|_| {
                std::path::Path::new(&path)
                    .parent()
                    .unwrap_or_else(|| std::path::Path::new("."))
                    .join("bowecho_proof_9_11")
            });
        std::fs::create_dir_all(&out_dir).expect("make proof dir");

        let opts = wrf_core::ComputeOpts {
            units: Some("K".to_owned()),
            ..Default::default()
        };
        let output = wrf_core::getvar(&file, "t2", Some(0), &opts).expect("t2");
        let (ny, nx) = match output.shape.as_slice() {
            [ny, nx] => (*ny, *nx),
            [1, ny, nx] => (*ny, *nx),
            other => panic!("t2: unexpected shape {other:?}"),
        };
        let values: Vec<f32> = output
            .data
            .iter()
            .map(|&v| {
                if !v.is_finite() || v.abs() >= 1.0e30 {
                    f32::NAN
                } else {
                    v as f32
                }
            })
            .collect();
        let (mut lo, mut hi) = (f32::INFINITY, f32::NEG_INFINITY);
        for &v in values.iter().filter(|v| v.is_finite()) {
            lo = lo.min(v);
            hi = hi.max(v);
        }
        assert!(lo.is_finite() && hi > lo, "t2 must vary: {lo}..{hi}");
        let field = Arc::new(rw_ui::FieldData {
            key: rw_ui::FieldKey {
                hour: rw_ui::HourKey {
                    model: "wrf".to_owned(),
                    run: "proof".to_owned(),
                    hour: 0,
                },
                var: "temperature_2m".to_owned(),
            },
            units: "K".to_owned(),
            nx,
            ny,
            values,
            range: Some((lo, hi)),
            grid: None,
            lat_descending: true,
            style: None,
        });

        let app = test_viewer_app_with_hazards(Vec::new());
        let mut slot = test_model_layer("wrf", "proof", 0);
        slot.layer.field = Arc::clone(&field);

        // Raster exactly as `draw_model_layers` paints it (shared resolver).
        let paint_raster = |layer: &model_layer::ModelMapLayer| -> Vec<[u8; 4]> {
            layer
                .field
                .values
                .iter()
                .map(|&v| {
                    if !v.is_finite() {
                        return [0, 0, 0, 0];
                    }
                    model_layer_value_color(
                        None,
                        layer.model_table.as_deref(),
                        layer.production.as_deref(),
                        layer.field.range,
                        layer.colormap,
                        v,
                    )
                    .map(|c| c.to_array())
                    .unwrap_or([0, 0, 0, 0])
                })
                .collect()
        };
        // The same raster with every pixel through the inspector chip.
        let chip_raster = |layer: &model_layer::ModelMapLayer| -> Vec<[u8; 4]> {
            layer
                .field
                .values
                .iter()
                .map(|&v| {
                    app.model_layer_color_for_value(layer, v)
                        .unwrap_or([0, 0, 0, 0])
                })
                .collect()
        };
        let write_png = |name: &str, pixels: &[[u8; 4]]| {
            let mut img = image::RgbaImage::new(nx as u32, ny as u32);
            for (i, px) in pixels.iter().enumerate() {
                img.put_pixel(
                    (i % nx) as u32,
                    (i / nx) as u32,
                    image::Rgba([px[0], px[1], px[2], px[3]]),
                );
            }
            let path = out_dir.join(name);
            img.save(&path).expect("write proof png");
            eprintln!("wrote {}", path.display());
        };
        let distinct = |pixels: &[[u8; 4]]| {
            pixels
                .iter()
                .filter(|px| px[3] > 0)
                .map(|px| [px[0], px[1], px[2]])
                .collect::<std::collections::HashSet<_>>()
                .len()
        };

        // --- #9: untouched WRF field. Solar paints; chip == painted pixel.
        slot.layer.production = None;
        slot.layer.model_table = model_layer_solar_table(field.as_ref(), false, false);
        assert!(slot.layer.model_table.is_some(), "WRF t2 resolves Solar");
        let solar_painted = paint_raster(&slot.layer);
        let solar_chip = chip_raster(&slot.layer);
        assert_eq!(
            solar_painted, solar_chip,
            "#9: every chip pixel must equal the painted pixel"
        );
        assert!(
            distinct(&solar_painted) >= 4,
            "Solar raster must be a real multi-color ramp"
        );
        write_png("1_solar_painted.png", &solar_painted);
        write_png("2_solar_chip.png", &solar_chip);

        // --- #11: bind a user palette exactly as the 🎨 editor does, then
        // resolve the style through the REAL worker chain.
        let mut settings = rw_ui::StyleOverrideSettings::default();
        settings.upsert_table(rw_ui::UserColorTable {
            name: "Proof magma".into(),
            title: "Proof magma".into(),
            display_units: "K".into(),
            convert: rw_ui::UserUnitConvert::None,
            legend_mode: rw_ui::UserLegendMode::Stepped,
            extend: rw_ui::UserExtendMode::Both,
            mask_below: None,
            tick_step: None,
            levels: vec![
                f64::from(lo),
                f64::from(lo) + f64::from(hi - lo) * 0.25,
                f64::from(lo) + f64::from(hi - lo) * 0.5,
                f64::from(lo) + f64::from(hi - lo) * 0.75,
                f64::from(hi),
            ],
            colors: vec![
                [30, 0, 60, 255],
                [140, 20, 120, 255],
                [230, 80, 60, 255],
                [255, 200, 40, 255],
            ],
        });
        settings.bind_product(
            &rw_ui::normalize_product_key("temperature_2m"),
            "Proof magma",
        );
        assert!(
            model_data::user_style_override_active(&settings, &field),
            "#11: the binding must register as a user override"
        );
        let style = settings
            .style_for_store_variable("temperature_2m", &serde_json::Value::Null, "K", None)
            .expect("user style resolves through the worker chain");
        slot.layer.production = Some(Arc::new(rustwx_render::build_colormap(
            &style.scale,
            style.colormap_options,
        )));
        slot.layer.model_table = model_layer_solar_table(
            field.as_ref(),
            true,
            model_data::user_style_override_active(&settings, &field),
        );
        assert!(
            slot.layer.model_table.is_none(),
            "#11: Solar must yield to the user binding"
        );
        let user_painted = paint_raster(&slot.layer);
        let user_chip = chip_raster(&slot.layer);
        assert_eq!(
            user_painted, user_chip,
            "#11/#9: chip must follow the user override too"
        );
        assert_ne!(
            user_painted, solar_painted,
            "#11: the user palette must actually change the raster"
        );
        assert!(
            distinct(&user_painted) >= 4,
            "user raster must show the bound ramp"
        );
        write_png("3_user_override.png", &user_painted);
        eprintln!(
            "t2 {nx}x{ny} range {lo:.1}..{hi:.1} K; solar colors={}, user colors={}",
            distinct(&solar_painted),
            distinct(&user_painted)
        );
    }

    #[test]
    fn history_size_options_reach_96_without_changing_default() {
        assert_eq!(DEFAULT_HISTORY_FRAME_LIMIT, 7);
        assert!(HISTORY_SIZE_OPTIONS.contains(&96));
        assert_eq!(normalized_history_limit(0), DEFAULT_HISTORY_FRAME_LIMIT);
        assert_eq!(normalized_history_limit(96), 96);
        // 4e stage (i): the legacy clamp delegates to the engine — the
        // smallest combo choice must stay the engine's floor.
        assert_eq!(
            HISTORY_SIZE_OPTIONS[0],
            ui_core::loop_engine::MIN_HISTORY_FRAME_LIMIT,
            "HISTORY_SIZE_OPTIONS[0] is the legacy clamp floor; the engine's \
             normalized_frame_limit must clamp identically"
        );
        assert_eq!(normalized_history_limit(1), HISTORY_SIZE_OPTIONS[0]);
        assert_eq!(normalized_history_limit(5000), MAX_HISTORY_FRAME_LIMIT);
    }

    #[test]
    fn storm_track_settings_filter_cells_before_tracking() {
        let mut app = test_viewer_app_with_hazards(Vec::new());
        app.storm_track_max_tracks = 8;
        app.storm_track_min_dbz = 50.0;

        let mut raw_cells = Vec::new();
        for (idx, max_dbz) in (53..=62).rev().enumerate() {
            let mut cell = test_storm_cell(idx as f64);
            cell.max_dbz = max_dbz as f32;
            raw_cells.push(cell);
        }
        let mut filtered_out = test_storm_cell(20.0);
        filtered_out.max_dbz = 44.0;
        raw_cells.push(filtered_out);

        let cells = app.storm_track_cells_for_settings(&raw_cells);

        assert_eq!(cells.len(), 8);
        assert!(cells.iter().all(|cell| cell.max_dbz >= 50.0));
        assert_eq!(cells[0].max_dbz, 62.0);
    }

    fn cached_storm_key_for_frame(app: &ViewerApp, index: usize) -> FrameWorkKey {
        let frame = &app.primary.history[index];
        FrameWorkKey::new(&frame.volume, Arc::as_ptr(&frame.volume) as usize)
    }

    #[test]
    fn storm_tracks_rebuild_from_cached_history_when_loop_extends_backward() {
        let mut app = test_viewer_app_with_hazards(Vec::new());
        let ctx = egui::Context::default();
        let base = Utc.with_ymd_and_hms(2026, 6, 8, 1, 0, 0).unwrap();
        for (minutes, east_km) in [(5, 2.0), (10, 4.0)] {
            let mut volume = RadarVolume::new(
                radar_core::RadarSite::new("KTLX"),
                base + chrono::Duration::minutes(minutes),
            );
            volume.metadata.source_path = Some(format!("KTLX-{minutes:02}"));
            upsert_primary_history_frame(
                &mut app,
                test_decoded_from_volume(
                    PathBuf::from(format!("KTLX-{minutes:02}")),
                    volume,
                    FrameStatus::Complete,
                ),
            );
            let index = app.primary.history.len() - 1;
            let key = cached_storm_key_for_frame(&app, index);
            insert_limited_frame_cache(
                &mut app.storm_cells_cache,
                &mut app.storm_cells_cache_order,
                key,
                vec![test_storm_cell(east_km)],
                ALGO_FRAME_CACHE_LIMIT,
            );
        }
        app.primary
            .history
            .sort_by(|left, right| left.identity.cmp(&right.identity));
        app.primary.cursor.index = 1;
        app.volume = Some(Arc::clone(&app.primary.history[1].volume));
        let newest_key = cached_storm_key_for_frame(&app, 1);
        let newest_cells = app.storm_cells_cache[&newest_key].clone();

        app.install_storm_cells_for_frame(&newest_key, &newest_cells, &ctx);
        assert_eq!(
            app.storm_tracker
                .tracks
                .iter()
                .map(|track| track.history.len())
                .max(),
            Some(2)
        );

        let mut older = RadarVolume::new(radar_core::RadarSite::new("KTLX"), base);
        older.metadata.source_path = Some("KTLX-00".to_owned());
        upsert_primary_history_frame(
            &mut app,
            test_decoded_from_volume(PathBuf::from("KTLX-00"), older, FrameStatus::Complete),
        );
        app.primary
            .history
            .sort_by(|left, right| left.identity.cmp(&right.identity));
        let older_key = cached_storm_key_for_frame(&app, 0);
        insert_limited_frame_cache(
            &mut app.storm_cells_cache,
            &mut app.storm_cells_cache_order,
            older_key,
            vec![test_storm_cell(0.0)],
            ALGO_FRAME_CACHE_LIMIT,
        );
        app.primary.cursor.index = 2;
        app.volume = Some(Arc::clone(&app.primary.history[2].volume));
        let newest_key = cached_storm_key_for_frame(&app, 2);
        let newest_cells = app.storm_cells_cache[&newest_key].clone();

        app.install_storm_cells_for_frame(&newest_key, &newest_cells, &ctx);

        assert_eq!(
            app.storm_tracker
                .tracks
                .iter()
                .map(|track| track.history.len())
                .max(),
            Some(3),
            "adding older loop frames after live preload must extend storm tracks backward"
        );
    }

    #[test]
    fn keyboard_frame_step_selects_history_and_updates_browse_state() {
        let mut app = test_viewer_app_with_hazards(Vec::new());
        let scan_time = Utc.with_ymd_and_hms(2026, 6, 8, 1, 30, 0).unwrap();
        let mut first = test_ref_then_velocity_volume();
        first.volume_time = scan_time;
        let mut second = test_ref_then_velocity_volume();
        second.volume_time = scan_time + chrono::Duration::minutes(3);
        upsert_primary_history_frame(
            &mut app,
            test_decoded_from_volume(PathBuf::from("TEST-0130"), first, FrameStatus::Complete),
        );
        upsert_primary_history_frame(
            &mut app,
            test_decoded_from_volume(PathBuf::from("TEST-0133"), second, FrameStatus::Complete),
        );
        app.primary
            .history
            .sort_by(|left, right| left.identity.cmp(&right.identity));
        app.primary.cursor.index = 0;
        app.volume = Some(Arc::clone(&app.primary.history[0].volume));
        app.primary.cursor.playing = true;
        app.primary.cursor.browsing = true;
        let ctx = egui::Context::default();

        assert!(app.step_history_frame(1, &ctx));
        assert_eq!(app.primary.cursor.index, 1);
        assert!(!app.primary.cursor.playing);
        assert!(!app.primary.cursor.browsing);

        assert!(app.step_history_frame(-1, &ctx));
        assert_eq!(app.primary.cursor.index, 0);
        assert!(app.primary.cursor.browsing);
    }

