    #[test]
    fn resolve_marker_click_picks_the_nearest_family_with_conus_winning_ties() {
        use MarkerFamily::*;
        // Nearest across families wins regardless of declaration order.
        assert_eq!(
            resolve_marker_click(Some((1, 9.0)), Some((2, 4.0)), Some((3, 6.0)), None, None),
            Some((Intl, 2))
        );
        assert_eq!(
            resolve_marker_click(Some((1, 9.0)), None, Some((3, 2.0)), None, None),
            Some((Community, 3))
        );
        // Exact ties outside the RAOB diamond keep the historical
        // precedence: CONUS > intl > community > custom poll > RAOB.
        assert_eq!(
            resolve_marker_click(
                Some((1, RAOB_MARKER_PRIORITY_RADIUS_PX + 0.1)),
                Some((2, RAOB_MARKER_PRIORITY_RADIUS_PX + 0.1)),
                Some((3, RAOB_MARKER_PRIORITY_RADIUS_PX + 0.1)),
                Some((4, RAOB_MARKER_PRIORITY_RADIUS_PX + 0.1)),
                Some((4, RAOB_MARKER_PRIORITY_RADIUS_PX + 0.1))
            ),
            Some((Conus, 1))
        );
        assert_eq!(
            resolve_marker_click(None, Some((2, 5.0)), Some((3, 5.0)), None, None),
            Some((Intl, 2))
        );
        assert_eq!(
            resolve_marker_click(None, None, None, Some((7, 2.0)), None),
            Some((CustomPoll, 7))
        );
        assert_eq!(resolve_marker_click(None, None, None, None, None), None);
    }

    /// A click inside the visible RAOB diamond selects it even when any
    /// radar/feed-family hit target overlaps.
    #[test]
    fn raob_marker_core_wins_over_every_overlapping_marker_family() {
        use MarkerFamily::*;
        for overlap in [
            resolve_marker_click(
                Some((1, 0.0)),
                None,
                None,
                None,
                Some((4, RAOB_MARKER_PRIORITY_RADIUS_PX)),
            ),
            resolve_marker_click(
                None,
                Some((2, 0.0)),
                None,
                None,
                Some((4, RAOB_MARKER_PRIORITY_RADIUS_PX)),
            ),
            resolve_marker_click(
                None,
                None,
                Some((3, 0.0)),
                None,
                Some((4, RAOB_MARKER_PRIORITY_RADIUS_PX)),
            ),
            resolve_marker_click(
                None,
                None,
                None,
                Some((5, 0.0)),
                Some((4, RAOB_MARKER_PRIORITY_RADIUS_PX)),
            ),
        ] {
            assert_eq!(overlap, Some((Raob, 4)));
        }
    }

    /// The rest of the shared 12 px halo keeps nearest/radar-first behavior,
    /// giving an ordinary radar click a predictable target around a
    /// collocated RAOB.
    #[test]
    fn raob_marker_priority_stops_at_the_visible_diamond_boundary() {
        use MarkerFamily::*;
        // Just outside the drawn diamond, the radar wins an exact tie.
        assert_eq!(
            resolve_marker_click(
                Some((1, RAOB_MARKER_PRIORITY_RADIUS_PX + 0.1)),
                None,
                None,
                None,
                Some((4, RAOB_MARKER_PRIORITY_RADIUS_PX + 0.1)),
            ),
            Some((Conus, 1))
        );
        // Nearest-marker behavior outside the core is otherwise unchanged.
        assert_eq!(
            resolve_marker_click(Some((1, 2.0)), None, None, None, Some((4, 8.0))),
            Some((Conus, 1))
        );
        assert_eq!(
            resolve_marker_click(Some((1, 9.0)), None, None, None, Some((4, 8.0))),
            Some((Raob, 4))
        );
        // An unaccompanied RAOB hit still resolves normally anywhere in its halo.
        assert_eq!(
            resolve_marker_click(None, None, None, None, Some((4, 10.0))),
            Some((Raob, 4))
        );
    }

    /// Clicking the shared-pad cluster marker opens the feed picker
    /// instead of polling (eight stacked markers would be useless), and
    /// re-clicking it toggles the picker shut.
    #[test]
    fn cluster_marker_click_toggles_the_feed_picker() {
        let markers = data_source::community_feeds::community_markers();
        let cluster_index = markers
            .iter()
            .position(|marker| marker.feed_indices.len() > 1)
            .expect("the Norman Testbed cluster exists");
        let mut app = test_viewer_app_with_hazards(Vec::new());
        let community_points = vec![(cluster_index, egui::pos2(100.0, 100.0))];
        let pointer = egui::pos2(103.0, 100.0);
        let ctx = egui::Context::default();

        app.handle_marker_click(&[], &[], &community_points, &[], &[], pointer, &ctx);
        assert_eq!(app.community_menu, Some(cluster_index));
        // The picker, not the poll, owns a cluster click.
        assert!(!app.poll_active);

        app.handle_marker_click(&[], &[], &community_points, &[], &[], pointer, &ctx);
        assert_eq!(app.community_menu, None, "re-click toggles the picker");

        // A click elsewhere on the map dismisses an open picker.
        app.community_menu = Some(cluster_index);
        app.handle_marker_click(
            &[],
            &[],
            &community_points,
            &[],
            &[],
            egui::pos2(500.0, 500.0),
            &ctx,
        );
        assert_eq!(app.community_menu, None);
    }

