    #[test]
    #[ignore = "network: hits the live SMHI open-data API"]
    fn fetch_intl_frame_live_smhi() {
        let (identity, volume) = fetch_intl_frame("smhi", "angelholm", None)
            .expect("live SMHI fetch")
            .expect("first poll always yields a frame");
        println!(
            "live SMHI frame: identity={identity} site={} lat={:?} lon={:?} cuts={} moments(first cut)={:?}",
            volume.site.id,
            volume.site.latitude_deg,
            volume.site.longitude_deg,
            volume.cuts.len(),
            volume.cuts.first().map(|cut| cut.moments_available())
        );
        assert!(identity.contains("angelholm"), "identity: {identity}");
        assert!(!volume.cuts.is_empty());
        // The not-in-catalog map jump needs coordinates from the volume.
        assert!(volume.site.latitude_deg.is_some());
        assert!(volume.site.longitude_deg.is_some());
        // Second tick with the installed identity: no download, no change.
        assert!(
            fetch_intl_frame("smhi", "angelholm", Some(&identity))
                .expect("live SMHI re-probe")
                .is_none()
        );
    }

    #[test]
    fn stale_realtime_chunks_trigger_archive_fallback() {
        let now = Utc.with_ymd_and_hms(2026, 7, 1, 4, 50, 0).unwrap();
        let fresh = data_source::RealtimeLevel2Volume {
            site: "KTLX".to_owned(),
            volume_id: 1,
            volume_time: now - chrono::Duration::seconds(90),
            chunks: Vec::new(),
            complete: false,
            total_size: 0,
        };
        let stale = data_source::RealtimeLevel2Volume {
            volume_time: now
                - chrono::Duration::seconds(REALTIME_LEVEL2_STALE_FALLBACK_SECONDS + 1),
            ..fresh.clone()
        };

        assert!(!realtime_level2_is_stale_for_latest_load(&fresh, now));
        assert!(realtime_level2_is_stale_for_latest_load(&stale, now));
        assert!(realtime_load_error_allows_archive_fallback(
            &stale_realtime_fallback_reason(&stale)
        ));
        assert!(!realtime_load_error_allows_archive_fallback(
            "unchanged cache hit"
        ));
    }

    #[test]
    fn newest_dir_list_entry_skips_metadata_and_dirs() {
        // The field repro: latest.json sorts after every timestamped
        // volume and poisoned the lexicographic pick on a local bridge.
        let listing = "1024 ITOK_20260611_001000\n2048 ITOK_20260611_002000\n64 latest.json\n";
        assert_eq!(
            newest_dir_list_entry(listing).as_deref(),
            Some("ITOK_20260611_002000")
        );
        // Bare names (no size column) and uppercase sidecar extensions.
        let listing = "a_20260611_0010\na_20260611_0020\nREADME.TXT\ngrlevel2.cfg\n";
        assert_eq!(
            newest_dir_list_entry(listing).as_deref(),
            Some("a_20260611_0020")
        );
        // Directory entries and metadata only -> no usable pick.
        assert_eq!(newest_dir_list_entry("ITOK/\nlatest.json\n"), None);
        assert_eq!(newest_dir_list_entry(""), None);
        // Dotted volume names with data extensions still win.
        let listing = "KILX_20260611_0020.gz\nlatest.json\n";
        assert_eq!(
            newest_dir_list_entry(listing).as_deref(),
            Some("KILX_20260611_0020.gz")
        );
        assert_eq!(
            dir_list_volume_entries_newest_first(
                "10 GAWX_20260615_0607\n10 GAWX_20260615_0609\nlatest.json\n"
            ),
            vec![
                "GAWX_20260615_0609".to_owned(),
                "GAWX_20260615_0607".to_owned()
            ]
        );
    }

