    #[test]
    fn freshness_ring_color_honors_custom_style() {
        let now = Utc.with_ymd_and_hms(2026, 6, 7, 23, 0, 0).unwrap();
        // Custom thresholds shift the boundaries; custom colors come through.
        let style = styles::RadarAgeStyle {
            green_seconds: 60,
            yellow_seconds: 120,
            red_seconds: 180,
            fresh_color: [0, 0, 255, 255],
            aging_color: [10, 20, 30, 255],
            stale_color: [40, 50, 60, 255],
            ..styles::RadarAgeStyle::default()
        };
        assert_eq!(
            freshness_ring_color(now - chrono::Duration::seconds(30), now, 200, &style),
            egui::Color32::from_rgba_unmultiplied(0, 0, 255, 200)
        );
        assert_eq!(
            freshness_ring_color(now - chrono::Duration::seconds(120), now, 200, &style),
            egui::Color32::from_rgba_unmultiplied(10, 20, 30, 200)
        );
        assert_eq!(
            freshness_ring_color(now - chrono::Duration::seconds(180), now, 200, &style),
            egui::Color32::from_rgba_unmultiplied(40, 50, 60, 200)
        );
        // With default 6-min green, 30 s would still be solid green — the
        // custom 60 s threshold is what moved the boundary.
        assert_eq!(
            freshness_ring_color(
                now - chrono::Duration::seconds(90),
                now,
                200,
                &styles::RadarAgeStyle::default()
            ),
            egui::Color32::from_rgba_unmultiplied(65, 238, 104, 200)
        );
    }

    #[test]
    fn mode_chip_uses_radar_age_style_threshold_and_colors() {
        let mut app = test_viewer_app_with_hazards(Vec::new());
        let mut style_settings = styles::StyleSettings::default();
        style_settings.radar_age.stale_chip_seconds = Some(90);
        style_settings.radar_age.fresh_color = Some([1, 2, 3, 255]);
        style_settings.radar_age.stale_color = Some([4, 5, 6, 255]);
        style_settings.radar_age.aging_color = Some([7, 8, 9, 255]);
        app.style_settings = style_settings.clone();
        app.style_registry = styles::StyleRegistry::from_settings(&style_settings);
        app.primary.live.enabled = true;
        set_primary_chip_frame(
            &mut app,
            Arc::new(RadarVolume::new(
                radar_core::RadarSite::new("KTLX"),
                Utc::now() - chrono::Duration::seconds(10),
            )),
        );

        let (_, live_bg, live_kind) = app.mode_chip_state().expect("live chip");

        assert_eq!(live_kind, "LIVE");
        assert_eq!(live_bg, egui::Color32::from_rgba_unmultiplied(1, 2, 3, 255));

        set_primary_chip_frame(
            &mut app,
            Arc::new(RadarVolume::new(
                radar_core::RadarSite::new("KTLX"),
                Utc::now() - chrono::Duration::minutes(3),
            )),
        );
        let (_, stale_bg, stale_kind) = app.mode_chip_state().expect("stale chip");

        assert_eq!(stale_kind, "STALE");
        assert_eq!(
            stale_bg,
            egui::Color32::from_rgba_unmultiplied(4, 5, 6, 255)
        );

        app.primary.live.enabled = false;
        let (_, archive_bg, archive_kind) = app.mode_chip_state().expect("archive chip");

        assert_eq!(archive_kind, "ARCH");
        assert_eq!(
            archive_bg,
            egui::Color32::from_rgba_unmultiplied(7, 8, 9, 255)
        );

        let old_time = Utc::now() - chrono::Duration::days(3) - chrono::Duration::minutes(17);
        set_primary_chip_frame(
            &mut app,
            Arc::new(RadarVolume::new(
                radar_core::RadarSite::new("KTLX"),
                old_time,
            )),
        );
        let (old_label, _, old_kind) = app.mode_chip_state().expect("old archive chip");

        assert_eq!(old_kind, "ARCH");
        assert!(old_label.contains(&old_time.format("%Y-%m-%d %H:%MZ").to_string()));
        assert!(
            !old_label.contains("m old"),
            "old archive chip should not show a giant minute count: {old_label}"
        );

        set_primary_chip_frame(
            &mut app,
            Arc::new(RadarVolume::new(
                radar_core::RadarSite::new("KTLX"),
                Utc::now() + chrono::Duration::minutes(5),
            )),
        );
        let (future_label, _, future_kind) = app.mode_chip_state().expect("future archive chip");

        assert_eq!(future_kind, "ARCH");
        assert!(future_label.contains("0m old"));
    }

    #[test]
    fn primary_mode_chip_follows_intl_display_owner() {
        let mut app = test_viewer_app_with_hazards(Vec::new());
        // Years-old ORD archive frames while the stale US auto-refresh flag
        // is still set: the chip must say ARCHIVE, never "LIVE · STALE"
        // (the flag is primary-US state no intl path sets or clears).
        app.primary.live.enabled = true;
        app.set_intl_archive_primary_source("ord", "deess");
        set_primary_chip_frame(
            &mut app,
            Arc::new(RadarVolume::new(
                radar_core::RadarSite::new("deess"),
                Utc::now() - chrono::Duration::days(365),
            )),
        );
        let (label, _, kind) = app.mode_chip_state().expect("intl archive chip");
        assert_eq!(
            kind, "ARCH",
            "intl archive display must read ARCHIVE: {label}"
        );

        // A streaming intl poll reads LIVE regardless of the US flag.
        app.poll_active = true;
        app.primary.live.enabled = false;
        set_primary_chip_frame(
            &mut app,
            Arc::new(RadarVolume::new(
                radar_core::RadarSite::new("deess"),
                Utc::now() - chrono::Duration::minutes(9),
            )),
        );
        let (label, _, kind) = app.mode_chip_state().expect("intl live chip");
        assert_eq!(kind, "LIVE", "an armed active intl poll is LIVE: {label}");
        // 9 minutes is a routine intl publish gap — the NEXRAD-tuned 480 s
        // default must not flag a healthy feed STALE.
        assert!(
            !label.contains("STALE"),
            "routine intl cadence is not a fault: {label}"
        );

        // The primary Live control pauses/resumes the intl poll in place.
        let (_sender, receiver) = mpsc::channel::<Result<PolledVolumeLoad, String>>();
        app.poll_rx = Some(receiver);
        app.set_intl_poll_paused(true);
        assert!(!app.poll_active);
        assert!(app.poll_rx.is_none(), "pause drops the in-flight tick");
        let (_, _, kind) = app.mode_chip_state().expect("paused intl chip");
        assert_eq!(kind, "ARCH", "a paused intl poll must not claim LIVE");
        app.set_intl_poll_paused(false);
        assert!(app.poll_active);
        assert!(app.poll_next.is_none(), "resume fires on the next tick");
        let (_, _, kind) = app.mode_chip_state().expect("resumed intl chip");
        assert_eq!(kind, "LIVE");
    }

    /// Contract harness (v0.29 Phase 1, spec §11 Milestone A item 1): the
    /// full chip truth table for `mode_chip_state_with_live_and_stale_floor`
    /// at floor = 0 (the US path) and floor = INTL_STALE_CHIP_FLOOR_SECONDS,
    /// pinned cell by cell so the Phase-4 `LoopEngine::liveness()` port must
    /// reproduce every label byte-for-byte.
    #[test]
    fn mode_chip_stale_floor_truth_table() {
        let mut app = test_viewer_app_with_hazards(Vec::new());
        let volume_aged = |seconds: i64| {
            Some(Arc::new(RadarVolume::new(
                radar_core::RadarSite::new("KTLX"),
                Utc::now() - chrono::Duration::seconds(seconds),
            )))
        };

        // No volume -> no chip, regardless of liveness or floor.
        app.volume = None;
        assert!(
            app.mode_chip_state_with_live_and_stale_floor(true, INTL_STALE_CHIP_FLOOR_SECONDS)
                .is_none()
        );

        // live, age <= the user threshold (default 480 s): LIVE either way.
        app.volume = volume_aged(60);
        for floor in [0, INTL_STALE_CHIP_FLOOR_SECONDS] {
            let (label, _, kind) = app
                .mode_chip_state_with_live_and_stale_floor(true, floor)
                .expect("fresh live chip");
            assert_eq!((label.as_str(), kind), ("● LIVE", "LIVE"), "floor {floor}");
        }

        // live, age past the user threshold but inside the intl floor:
        // floor 0 flags STALE with the minute count; the 1800 s floor
        // rescues a routine international publish gap.
        app.volume = volume_aged(600);
        let (label, _, kind) = app
            .mode_chip_state_with_live_and_stale_floor(true, 0)
            .expect("stale live chip");
        assert_eq!(kind, "STALE");
        assert_eq!(label, "● LIVE · STALE 10m");
        let (label, _, kind) = app
            .mode_chip_state_with_live_and_stale_floor(true, INTL_STALE_CHIP_FLOOR_SECONDS)
            .expect("floor-rescued live chip");
        assert_eq!((label.as_str(), kind), ("● LIVE", "LIVE"));

        // live, age past max(user, floor): STALE at both floors.
        app.volume = volume_aged(2000);
        let (label, _, kind) = app
            .mode_chip_state_with_live_and_stale_floor(true, INTL_STALE_CHIP_FLOOR_SECONDS)
            .expect("stale intl chip");
        assert_eq!(kind, "STALE");
        assert_eq!(label, "● LIVE · STALE 33m");

        // A user threshold ABOVE the floor still wins — the floor is a
        // floor, not an override.
        let mut style_settings = styles::StyleSettings::default();
        style_settings.radar_age.stale_chip_seconds = Some(3600);
        app.style_registry = styles::StyleRegistry::from_settings(&style_settings);
        let (label, _, kind) = app
            .mode_chip_state_with_live_and_stale_floor(true, INTL_STALE_CHIP_FLOOR_SECONDS)
            .expect("user-threshold live chip");
        assert_eq!((label.as_str(), kind), ("● LIVE", "LIVE"));
        app.style_registry =
            styles::StyleRegistry::from_settings(&styles::StyleSettings::default());

        // not live, age < 24 h: relative ARCHIVE, identical at both floors
        // (the floor only moves the LIVE/STALE boundary, never the
        // live/archive split).
        app.volume = volume_aged(600);
        for floor in [0, INTL_STALE_CHIP_FLOOR_SECONDS] {
            let (label, _, kind) = app
                .mode_chip_state_with_live_and_stale_floor(false, floor)
                .expect("archive chip");
            assert_eq!(kind, "ARCH", "floor {floor}");
            assert_eq!(label, "ARCHIVE · 10m old", "floor {floor}");
        }

        // not live, age >= 24 h: dated ARCHIVE.
        let old_time = Utc::now() - chrono::Duration::days(2);
        app.volume = Some(Arc::new(RadarVolume::new(
            radar_core::RadarSite::new("KTLX"),
            old_time,
        )));
        let (label, _, kind) = app
            .mode_chip_state_with_live_and_stale_floor(false, 0)
            .expect("dated archive chip");
        assert_eq!(kind, "ARCH");
        assert_eq!(
            label,
            format!("ARCHIVE · {}", old_time.format("%Y-%m-%d %H:%MZ"))
        );
    }

    #[test]
    fn primary_mode_chip_flags_a_slow_intl_poll_stale_past_the_floor() {
        // The intl display-owner route through `mode_chip_state`: liveness
        // is `intl_poll_owns_primary()` and the stale boundary is the 1800 s
        // floor — an armed active poll whose newest frame is 40 minutes old
        // is a fault worth flagging even on intl cadences.
        let mut app = test_viewer_app_with_hazards(Vec::new());
        app.primary.feed = FeedSource::Live(SiteRef::Intl {
            provider_id: "ord".to_owned(),
            site_id: "deess".to_owned(),
        });
        app.poll_active = true;
        set_primary_chip_frame(
            &mut app,
            Arc::new(RadarVolume::new(
                radar_core::RadarSite::new("deess"),
                Utc::now() - chrono::Duration::seconds(2400),
            )),
        );
        let (label, _, kind) = app.mode_chip_state().expect("stale intl chip");
        assert_eq!(kind, "STALE");
        assert_eq!(label, "● LIVE · STALE 40m");
    }

    #[test]
    fn reset_view_centers_on_the_loaded_intl_volume() {
        let mut app = test_viewer_app_with_hazards(Vec::new());
        app.sites = vec![RadarSite::new("KTLX").with_location(
            Some("Norman".to_owned()),
            Some(35.333),
            Some(-97.278),
        )];
        app.selected_site_index = 0;
        let mut site = radar_core::RadarSite::new("sekkr");
        site.latitude_deg = Some(59.654);
        site.longitude_deg = Some(17.947);
        app.volume = Some(Arc::new(RadarVolume::new(site, Utc::now())));
        app.map_center_lat = 45.0;
        app.map_center_lon = 10.0;

        app.reset_view();

        // Old behavior read the stale US selected_site_index and snapped
        // the map across the Atlantic mid-European-session.
        assert!(
            (app.map_center_lat - 59.654).abs() < 0.001
                && (app.map_center_lon - 17.947).abs() < 0.001,
            "Reset View must follow the loaded volume: {} {}",
            app.map_center_lat,
            app.map_center_lon
        );

        // Without a loaded volume the selected US site remains the anchor.
        app.volume = None;
        app.reset_view();
        assert!(
            (app.map_center_lat - 35.333).abs() < 0.001,
            "no volume -> selected site fallback: {}",
            app.map_center_lat
        );
    }

    #[test]
    fn velocity_quality_tag_discloses_nyquist_less_dealias() {
        // DVEL/DSRV on a Nyquist-less feed (JMA always): a product labeled
        // dealiased must disclose the pass-through instead of silently
        // rendering raw velocity (old behavior: no tag at all).
        assert_eq!(
            velocity_quality_tag(true, true, true, None),
            Some(VelocityQualityTag::NoNyquistPassThrough)
        );
        assert_eq!(
            velocity_quality_tag(true, true, true, Some("ord")),
            Some(VelocityQualityTag::NoNyquistPassThrough),
            "the pass-through disclosure outranks the provenance chip"
        );
        assert_eq!(
            VelocityQualityTag::NoNyquistPassThrough.label(),
            "no Nyquist in this feed — showing raw velocity"
        );
        // Existing tags are preserved: ORD provenance, raw fold warning,
        // silence for genuinely dealiased renders and non-velocity.
        assert_eq!(
            velocity_quality_tag(true, true, false, Some("ord")),
            Some(VelocityQualityTag::DealiasedLocally)
        );
        assert_eq!(velocity_quality_tag(true, true, false, None), None);
        assert_eq!(
            velocity_quality_tag(false, true, false, None),
            Some(VelocityQualityTag::RawFoldsPossible)
        );
        assert_eq!(velocity_quality_tag(false, false, false, None), None);

        // The displayed-cut query wires the render2d skip detection to
        // the active volume/cut.
        let mut app = test_viewer_app_with_hazards(Vec::new());
        app.selected_cut = 0;
        let mut volume = test_aliased_velocity_volume();
        for radial in &mut volume.cuts[0].radials {
            radial.nyquist_velocity_mps = None;
        }
        app.volume = Some(Arc::new(volume));
        assert!(
            app.displayed_cut_dealias_skipped_no_nyquist(),
            "JMA-style Nyquist-less cut must report the pass-through"
        );
        app.volume = Some(Arc::new(test_aliased_velocity_volume()));
        assert!(
            !app.displayed_cut_dealias_skipped_no_nyquist(),
            "a feed with Nyquist dealiases for real — no disclosure tag"
        );
        app.volume = None;
        assert!(!app.displayed_cut_dealias_skipped_no_nyquist());
    }

    #[test]
    fn owned_pane_chip_tracks_the_panes_own_live_flag() {
        let mut app = test_viewer_app_with_hazards(Vec::new());
        app.sites = vec![RadarSite::new("KTLX"), RadarSite::new("KEAX")];
        app.selected_site_index = 0;
        app.primary.live.enabled = true;
        app.volume = Some(Arc::new(RadarVolume::new(
            radar_core::RadarSite::new("KTLX"),
            Utc::now() - chrono::Duration::seconds(30),
        )));
        app.extra_panes
            .push(test_pane(DisplayProduct::Moment(MomentType::Reflectivity)));
        app.extra_panes
            .push(test_pane(DisplayProduct::Moment(MomentType::Reflectivity)));
        app.extra_panes[0].pin = Some(SiteRef::Us {
            level2_id: "KEAX".to_owned(),
        });

        // Cell 0 (primary) and the FOLLOWING pane display the primary feed,
        // so the primary Live flag is their truth.
        assert!(app.pane_chip_is_live(0));
        assert!(app.pane_chip_is_live(2));
        // Radar-owning panes auto-refresh themselves now: the chip is the
        // PANE's own flag, in both directions.
        assert!(app.pane_chip_is_live(1));
        app.extra_panes[0].engine.live.enabled = false;
        assert!(!app.pane_chip_is_live(1));
        app.extra_panes[0].engine.live.enabled = true;
        app.primary.live.enabled = false;
        assert!(
            app.pane_chip_is_live(1),
            "pane's own poll does not depend on the primary flag"
        );

        // An inherited non-catalog id has no live feed behind it: the chip
        // must not claim LIVE for a pane nothing will refresh.
        app.extra_panes[0].pin = Some(SiteRef::Us {
            level2_id: "sella".to_owned(),
        });
        assert!(!app.pane_chip_is_live(1));
        let (label, _, kind) = app
            .mode_chip_state_with_live_and_stale_floor(app.pane_chip_is_live(1), 0)
            .expect("owned pane chip");
        assert_eq!(kind, "ARCH");
        assert!(label.contains("0m old"), "{label}");
    }

    /// v0.29 Phase 4e stage (iii): the pane-0 grid chip now shares the
    /// PRIMARY's display-owner-aware liveness truth — the last live R8
    /// residue (pane 0 answering with the bare US auto-refresh flag while
    /// an international source owned the display) is dead, and this test
    /// replaces the Phase-1 pin of the known-wrong cells
    /// (`pane_zero_grid_chip_still_reads_the_us_auto_refresh_flag`, which
    /// its own doc said to delete when the engine port landed). The chip
    /// class is untestable-to-reintroduce: both chips derive from the same
    /// flag + feed, so they cannot disagree.
    #[test]
    fn pane_zero_grid_chip_shares_the_primary_display_owner_liveness() {
        let mut app = test_viewer_app_with_hazards(Vec::new());

        // Fixed cell 1: an intl ARCHIVE owns the display while the stale US
        // flag is still set — BOTH chips read ARCHIVE now.
        app.primary.live.enabled = true;
        app.set_intl_archive_primary_source("ord", "deess");
        set_primary_chip_frame(
            &mut app,
            Arc::new(RadarVolume::new(
                radar_core::RadarSite::new("deess"),
                Utc::now() - chrono::Duration::days(365),
            )),
        );
        let (_, _, kind) = app.mode_chip_state().expect("primary chip");
        assert_eq!(kind, "ARCH", "the single-pane chip dispatches honestly");
        assert!(
            !app.pane_chip_is_live(0),
            "pane 0 mirrors the primary: an intl archive owner is not live"
        );
        let (_, _, pane_kind) = app.pane_mode_chip_state(0).expect("pane-0 chip");
        assert_eq!(pane_kind, "ARCH", "grid chip agrees with the primary chip");

        // Fixed cell 2, the converse: a streaming intl poll with the US
        // flag off — BOTH chips read LIVE.
        app.poll_active = true;
        app.primary.live.enabled = false;
        set_primary_chip_frame(
            &mut app,
            Arc::new(RadarVolume::new(
                radar_core::RadarSite::new("deess"),
                Utc::now() - chrono::Duration::minutes(5),
            )),
        );
        let (_, _, kind) = app.mode_chip_state().expect("primary chip");
        assert_eq!(kind, "LIVE");
        assert!(
            app.pane_chip_is_live(0),
            "pane 0 mirrors the primary: a streaming intl poll is live"
        );
        let (_, _, pane_kind) = app.pane_mode_chip_state(0).expect("pane-0 chip");
        assert_eq!(
            pane_kind, "LIVE",
            "grid chip agrees (intl floor keeps a 5-minute-old frame fresh)"
        );
    }

    /// Phase-4d port of `extra_pane_live_source_dedupes_primary_site_and_
    /// rejects_foreign_ids`: the same (pin, primary-state) cells, asserted
    /// through the pane ENGINE's verdict (`extra_pane_live_action` ->
    /// `LoopEngine::live_tick`) now that the SharedWithPrimary dedupe is
    /// SiteRef equality inside the engine. Classification-only cells keep
    /// asserting `extra_pane_live_source` (None/UsSite/Intl).
    #[test]
    fn pane_live_action_dedupes_primary_site_and_rejects_foreign_ids() {
        let mut app = test_viewer_app_with_hazards(Vec::new());
        app.sites = vec![RadarSite::new("KTLX"), RadarSite::new("KEAX")];
        app.selected_site_index = 0;
        app.primary.live.enabled = true;
        app.extra_panes
            .push(test_pane(DisplayProduct::Moment(MomentType::Reflectivity)));
        let now = Instant::now();

        // Same site as the live-polling primary: reuse its decode.
        app.extra_panes[0].pin = Some(SiteRef::Us {
            level2_id: "KTLX".to_owned(),
        });
        assert_eq!(
            app.extra_pane_live_action(0, now),
            LiveAction::FollowPrimary
        );
        // Different catalog site: the pane polls its own feed.
        app.extra_panes[0].pin = Some(SiteRef::Us {
            level2_id: "KEAX".to_owned(),
        });
        assert_eq!(app.extra_pane_live_action(0, now), LiveAction::Poll);
        // Primary paused: same-site pane now owns its own polling.
        app.primary.live.enabled = false;
        app.extra_panes[0].pin = Some(SiteRef::Us {
            level2_id: "KTLX".to_owned(),
        });
        assert_eq!(app.extra_pane_live_action(0, now), LiveAction::Poll);
        app.primary.live.enabled = true;
        // An armed international poll owns the primary view, so the primary
        // is NOT live-polling KTLX and the pane must fetch it itself.
        app.primary.feed = FeedSource::Live(SiteRef::Intl {
            provider_id: "smhi".to_owned(),
            site_id: "sella".to_owned(),
        });
        app.poll_active = true;
        assert_eq!(app.extra_pane_live_action(0, now), LiveAction::Poll);
        // ...while an intl pane pinned to that SAME armed intl poll now
        // FOLLOWS it — the Phase-4d dedupe cell (fails on the pre-4d tree,
        // which classified every intl pin as its own poll).
        app.extra_panes[0].pin = Some(SiteRef::Intl {
            provider_id: "smhi".to_owned(),
            site_id: "sella".to_owned(),
        });
        assert_eq!(
            app.extra_pane_live_action(0, now),
            LiveAction::FollowPrimary,
            "intl pane sharing the intl primary's site must not double-poll"
        );
        // The equality includes the provider: cross-provider same-site-id
        // strings still poll their own feed.
        app.extra_panes[0].pin = Some(SiteRef::Intl {
            provider_id: "dwd".to_owned(),
            site_id: "sella".to_owned(),
        });
        assert_eq!(app.extra_pane_live_action(0, now), LiveAction::Poll);
        app.poll_active = false;
        app.primary.feed = FeedSource::CustomUrl(String::new());
        // A pinned id outside the US catalog (inherited from an
        // international/archive display) has nothing to poll.
        app.extra_panes[0].pin = Some(SiteRef::Us {
            level2_id: "sella".to_owned(),
        });
        assert_eq!(
            app.extra_pane_live_source(&app.extra_panes[0]),
            PaneLiveSource::None
        );
        assert_eq!(app.extra_pane_live_action(0, now), LiveAction::Skip);
        // International pane source polls the provider.
        app.extra_panes[0].pin = Some(SiteRef::Intl {
            provider_id: "smhi".to_owned(),
            site_id: "sella".to_owned(),
        });
        assert_eq!(
            app.extra_pane_live_source(&app.extra_panes[0]),
            PaneLiveSource::Intl
        );
        assert_eq!(app.extra_pane_live_action(0, now), LiveAction::Poll);
        // The v0.28 "intl source outranks a lingering pinned US id" cell is
        // UNREPRESENTABLE since the Phase-3 pin collapse: one `pin` field
        // holds exactly one world, so there is nothing to outrank.
        // Pinned-id catalog lookup and the primary dedupe are both
        // case-insensitive.
        app.extra_panes[0].pin = Some(SiteRef::Us {
            level2_id: "keax".to_owned(),
        });
        assert_eq!(app.extra_pane_live_action(0, now), LiveAction::Poll);
        app.extra_panes[0].pin = Some(SiteRef::Us {
            level2_id: "ktlx".to_owned(),
        });
        assert_eq!(
            app.extra_pane_live_action(0, now),
            LiveAction::FollowPrimary
        );
        // An in-flight pane load owns the pane, even over FollowPrimary.
        let (_sender, receiver) = mpsc::channel::<AsyncLoadResult>();
        app.extra_panes[0].load_receiver = Some(receiver);
        assert_eq!(app.extra_pane_live_action(0, now), LiveAction::Skip);
        app.extra_panes[0].load_receiver = None;
        // The pane Live toggle is the user's pause: off skips everything.
        app.extra_panes[0].engine.live.enabled = false;
        assert_eq!(app.extra_pane_live_action(0, now), LiveAction::Skip);
        app.extra_panes[0].engine.live.enabled = true;
        // Not due yet: a fresh refresh stamp skips a would-be Poll (5 s US
        // pane cadence via the engine)...
        app.extra_panes[0].pin = Some(SiteRef::Us {
            level2_id: "KEAX".to_owned(),
        });
        app.extra_panes[0].engine.live.last_refresh = Some(now);
        assert_eq!(app.extra_pane_live_action(0, now), LiveAction::Skip);
        // ...but never gates the cadence-free FollowPrimary.
        app.extra_panes[0].pin = Some(SiteRef::Us {
            level2_id: "KTLX".to_owned(),
        });
        assert_eq!(
            app.extra_pane_live_action(0, now),
            LiveAction::FollowPrimary
        );
        app.extra_panes[0].engine.live.last_refresh = None;
        // An armed custom-URL poll owns the primary view (the guard keys on
        // `poll_url`, not the variant payload): the same-site pane must poll
        // its own feed.
        app.poll_active = true;
        app.poll_url = "http://example.com/dow8".to_owned();
        assert_eq!(app.extra_pane_live_action(0, now), LiveAction::Poll);
        app.poll_active = false;
        app.poll_url = String::new();
        // An international ARCHIVE display owner (armed intl source, poll
        // inactive) also means the primary is not live-polling KTLX...
        app.set_intl_archive_primary_source("smhi", "sella");
        assert_eq!(app.extra_pane_live_action(0, now), LiveAction::Poll);
        // ...and an intl pane pinned to that ARCHIVE owner polls itself
        // too: there is no live primary feed to ride.
        app.extra_panes[0].pin = Some(SiteRef::Intl {
            provider_id: "smhi".to_owned(),
            site_id: "sella".to_owned(),
        });
        assert_eq!(app.extra_pane_live_action(0, now), LiveAction::Poll);
        app.primary.feed = FeedSource::CustomUrl(String::new());
        // A research/community feed resolves in the catalog but the pane
        // load path refuses it: no live source.
        app.sites =
            site_catalog_with_community_feeds(vec![RadarSite::new("KTLX"), RadarSite::new("KEAX")]);
        app.extra_panes[0].pin = Some(SiteRef::Us {
            level2_id: "KBPP".to_owned(),
        });
        assert_eq!(
            app.extra_pane_live_source(&app.extra_panes[0]),
            PaneLiveSource::None
        );
        assert_eq!(app.extra_pane_live_action(0, now), LiveAction::Skip);
        // A following pane has no source of its own.
        app.extra_panes[0].pin = None;
        assert_eq!(
            app.extra_pane_live_source(&app.extra_panes[0]),
            PaneLiveSource::None
        );
        assert_eq!(app.extra_pane_live_action(0, now), LiveAction::Skip);
    }

    /// THE Phase-4d dedupe deliverable, end to end ("intl double-poll
    /// dies", spec §7 4d + migration row `extra_pane_live_source`): with an
    /// intl PRIMARY poll active on a site and a pane pinned to the SAME
    /// site, the tick verdict is FollowPrimary and the follow mirrors the
    /// primary's newest volume Arc into the pane — one download, one
    /// decode. FAILS ON THE PRE-4D TREE, which classified every intl pin
    /// as its own poll (verdict Poll = a second provider download) and
    /// whose follow path refused non-US pins outright.
    #[test]
    fn intl_pane_pinned_to_the_intl_primary_site_follows_instead_of_double_polling() {
        let mut app = test_viewer_app_with_hazards(Vec::new());
        let ctx = egui::Context::default();
        app.extra_panes
            .push(test_pane(DisplayProduct::Moment(MomentType::Reflectivity)));
        app.primary.feed = FeedSource::Live(SiteRef::Intl {
            provider_id: "smhi".to_owned(),
            site_id: "angelholm".to_owned(),
        });
        app.poll_active = true;
        // The primary's newest polled frame (intl volumes carry provider
        // site ids that need not match the registry id).
        let volume = Arc::new(RadarVolume::new(
            radar_core::RadarSite::new("seang"),
            Utc::now() - chrono::Duration::minutes(5),
        ));
        app.primary.history.push(FrameHistoryEntry {
            identity: frame_identity_for_volume(&volume),
            path: PathBuf::from("poll://seang"),
            volume: Arc::clone(&volume),
            timings: None,
            status: FrameStatus::Complete,
            source_label: "polled seang".to_owned(),
        });
        app.extra_panes[0].pin = Some(SiteRef::Intl {
            provider_id: "smhi".to_owned(),
            site_id: "angelholm".to_owned(),
        });

        assert_eq!(
            app.extra_pane_live_action(0, Instant::now()),
            LiveAction::FollowPrimary,
            "same intl site as the intl primary: ONE download"
        );
        app.follow_primary_volume_into_pane(0, &ctx);
        assert_eq!(app.extra_panes[0].engine.history.len(), 1);
        assert!(
            Arc::ptr_eq(&app.extra_panes[0].engine.history[0].volume, &volume),
            "the pane mirrors the primary's decode (Arc clone), not a refetch"
        );
        assert_eq!(
            app.extra_panes[0].followed_primary_volume_ptr,
            Some(Arc::as_ptr(&volume) as usize),
            "the Arc-ptr dedupe key is recorded so the next tick skips"
        );
        // A cross-site intl pin must NOT mirror this primary.
        app.extra_panes[0].pin = Some(SiteRef::Intl {
            provider_id: "smhi".to_owned(),
            site_id: "sella".to_owned(),
        });
        app.extra_panes[0].followed_primary_volume_ptr = None;
        app.extra_panes[0].engine.clear_history();
        // The earlier mirror stamped last_refresh; clear it so the verdict
        // under test is the dedupe, not the cadence.
        app.extra_panes[0].engine.live.last_refresh = None;
        assert_eq!(
            app.extra_pane_live_action(0, Instant::now()),
            LiveAction::Poll
        );
        app.follow_primary_volume_into_pane(0, &ctx);
        assert!(
            app.extra_panes[0].engine.history.is_empty(),
            "the feed-level guard refuses a mismatched intl pin"
        );
    }

    /// Contract harness (v0.29 Phase 1, spec §11 Milestone A item 2): the
    /// pane half of the history-clear rule table. `start_extra_pane_intl_load`
    /// keeps the pane's loop when the source is unchanged and clears the
    /// pane's display state on ANY source change — the same keep/clear pairs
    /// `switch_policy` centralizes in Phase 4.
    #[test]
    fn extra_pane_intl_load_clears_pane_history_only_on_source_change() {
        let mut app = test_viewer_app_with_hazards(Vec::new());
        let ctx = egui::Context::default();
        app.extra_panes
            .push(test_pane(DisplayProduct::Moment(MomentType::Reflectivity)));
        // Unknown provider id: the spawned worker fails its provider lookup
        // immediately, so the test never touches the network — the state
        // under test is all written synchronously before the spawn.
        let intl_site = |id: &str| data_source::international::IntlSite {
            provider_id: "zz-test",
            site_id: id.to_owned(),
            label: id.to_uppercase(),
            country: "Testland",
            latitude_deg: None,
            longitude_deg: None,
        };
        let seed_pane = |pane: &mut PaneView, site: &str| {
            let volume = Arc::new(RadarVolume::new(
                radar_core::RadarSite::new(site),
                Utc::now() - chrono::Duration::minutes(4),
            ));
            pane.engine.history.push(FrameHistoryEntry {
                identity: frame_identity_for_volume(&volume),
                path: PathBuf::from(format!("intl:{site}")),
                volume: Arc::clone(&volume),
                timings: None,
                status: FrameStatus::Complete,
                source_label: format!("zz-test {site}"),
            });
            pane.volume = Some(volume);
            pane.cut = Some(0);
        };

        // KEEP: reloading the SAME intl source leaves the pane loop alone.
        app.extra_panes[0].pin = Some(SiteRef::Intl {
            provider_id: "zz-test".to_owned(),
            site_id: "alpha".to_owned(),
        });
        seed_pane(&mut app.extra_panes[0], "alpha");
        app.start_extra_pane_intl_load(0, intl_site("alpha"), LatestLoadMode::User, &ctx);
        let pane = &app.extra_panes[0];
        assert_eq!(
            pane.engine.history.len(),
            1,
            "same-source pane reload keeps history"
        );
        assert!(pane.volume.is_some());
        assert_eq!(
            pane.cut,
            Some(0),
            "tilt override survives a same-source load"
        );
        assert!(pane.load_receiver.is_some(), "load worker armed");

        // CLEAR: a different site of the same provider resets the pane's
        // display state (history, volume, tilt, texture) before the load.
        app.start_extra_pane_intl_load(0, intl_site("beta"), LatestLoadMode::User, &ctx);
        let pane = &app.extra_panes[0];
        assert!(
            pane.engine.history.is_empty(),
            "cross-site pane load clears the pane loop"
        );
        assert!(pane.volume.is_none());
        assert_eq!(pane.cut, None);
        assert_eq!(
            pane.pin,
            Some(SiteRef::Intl {
                provider_id: "zz-test".to_owned(),
                site_id: "beta".to_owned(),
            })
        );

        // CLEAR: a US-pinned pane switching to an international source (the
        // previous pin is a US ref, so the intl pin never matches).
        app.extra_panes[0].pin = Some(SiteRef::Us {
            level2_id: "KTLX".to_owned(),
        });
        seed_pane(&mut app.extra_panes[0], "KTLX");
        app.start_extra_pane_intl_load(0, intl_site("alpha"), LatestLoadMode::User, &ctx);
        let pane = &app.extra_panes[0];
        assert!(
            pane.engine.history.is_empty(),
            "US-to-intl pane switch clears the pane loop"
        );
        assert!(pane.volume.is_none());
        assert!(
            matches!(pane.pin, Some(SiteRef::Intl { .. })),
            "the pinned US id is released to the intl source"
        );
    }

    /// v0.29 Phase 3 §1.4 startup restore: the display owner persists as
    /// ONE encoded settings key at every ownership transition, and a fresh
    /// session re-arms an intl owner from it (poll inactive — nothing
    /// auto-starts). Owner checkpoint: a full Ängelholm session resumes in
    /// Sweden — display owner, archive dispatch, and Reset View included.
    #[test]
    fn intl_display_owner_persists_and_restores_the_session() {
        let mut app = test_viewer_app_with_hazards(Vec::new());
        app.set_intl_archive_primary_source("smhi", "angelholm");
        assert_eq!(
            app.app_settings.display_owner_site.as_deref(),
            Some("intl:smhi:angelholm"),
            "ownership TAKE persists the encoded key"
        );

        // Fresh session: the persisted key re-arms the intl poll source.
        let restored = restored_primary_feed(&app.app_settings);
        assert!(
            matches!(
                &restored,
                FeedSource::Live(SiteRef::Intl { provider_id, site_id })
                    if provider_id == "smhi" && site_id == "angelholm"
            ),
            "restore re-arms the intl owner: {restored:?}"
        );
        let mut fresh = test_viewer_app_with_hazards(Vec::new());
        fresh.sites = vec![RadarSite::new("KTLX").with_location(
            Some("Norman".to_owned()),
            Some(35.333),
            Some(-97.278),
        )];
        fresh.selected_site_index = 0;
        fresh.primary.feed = restored;
        fresh.poll_active = false;
        assert_eq!(
            fresh.display_owner_site(),
            SiteRef::Intl {
                provider_id: "smhi".to_owned(),
                site_id: "angelholm".to_owned(),
            },
            "the restored session's display owner is the intl site"
        );
        // Reset View lands in Sweden even before the first poll installs
        // a volume — never on the stale US selection.
        fresh.reset_view();
        assert!(
            (fresh.map_center_lat - 56.3675).abs() < 0.05
                && (fresh.map_center_lon - 12.8517).abs() < 0.05,
            "Reset View follows the restored intl owner, got ({}, {})",
            fresh.map_center_lat,
            fresh.map_center_lon
        );

        // Releasing ownership back to the US persists the new owner.
        fresh.release_intl_primary_display();
        assert_eq!(
            fresh.app_settings.display_owner_site.as_deref(),
            Some("KTLX"),
            "ownership RELEASE persists the US owner"
        );

        // Legacy settings without the key keep the CustomUrl seed.
        let legacy = settings::AppSettings::default();
        assert!(matches!(
            restored_primary_feed(&legacy),
            FeedSource::CustomUrl(url) if url.is_empty()
        ));
        // A stale intl key (site gone from the catalog) degrades to legacy.
        let stale = settings::AppSettings {
            display_owner_site: Some("intl:smhi:gone".to_owned()),
            ..Default::default()
        };
        assert!(matches!(
            restored_primary_feed(&stale),
            FeedSource::CustomUrl(_)
        ));
    }

    /// v0.29 Phase 3 favorites parity: the star keys on the display owner's
    /// `settings_key()`, so an international owner favorites as a
    /// case-preserved `intl:` key that resolves back to its own catalog
    /// label — and never shadows (or is shadowed by) a bare US id.
    #[test]
    fn intl_favorites_key_on_the_display_owner_and_resolve_labels() {
        let mut app = test_viewer_app_with_hazards(Vec::new());
        app.set_intl_archive_primary_source("smhi", "angelholm");
        let owner = app.display_owner_site();
        assert_eq!(owner.settings_key(), "intl:smhi:angelholm");

        app.app_settings.add_favorite(&owner.settings_key());
        assert!(app.app_settings.is_favorite("intl:smhi:angelholm"));
        assert!(
            !app.app_settings.is_favorite("ANGELHOLM"),
            "an intl favorite never doubles as a bare US id"
        );

        // The chip row resolves the stored key through the one catalog.
        let record =
            data_source::sites::resolve(&SiteRef::parse_settings_key("intl:smhi:angelholm"))
                .expect("Ängelholm resolves");
        assert_eq!(record.label, "Ängelholm");
        assert!(matches!(record.kind, SiteKind::Intl { .. }));

        // Removal accepts the verbatim key (right-click chip path).
        app.app_settings.remove_favorite("intl:smhi:angelholm");
        assert!(!app.app_settings.is_favorite("intl:smhi:angelholm"));
    }

    /// v0.29 Phase 3: explicit pane pins persist as settings keys and a
    /// fresh session's `sync_extra_panes` restores them — US pins as bare
    /// legacy ids (forever), intl pins as case-preserved `intl:` keys.
    /// Clearing back to Follow-primary removes the entry.
    #[test]
    fn explicit_pane_pins_persist_and_restore_across_sessions() {
        let mut app = test_viewer_app_with_hazards(Vec::new());
        app.sites = vec![RadarSite::new("KTLX"), RadarSite::new("KEAX")];
        app.selected_site_index = 0;
        app.app_settings.independent_panels = true;
        app.extra_panes
            .push(test_pane(DisplayProduct::Moment(MomentType::Reflectivity)));

        app.set_extra_pane_selected_site(0, 1);
        assert_eq!(
            app.app_settings.extra_pane_pins.get(&0).map(String::as_str),
            Some("KEAX")
        );

        let angelholm = ViewerApp::find_intl_site("smhi", "angelholm")
            .expect("SMHI Ängelholm is in the static catalog");
        app.set_extra_pane_intl_site(0, &angelholm);
        assert_eq!(
            app.app_settings.extra_pane_pins.get(&0).map(String::as_str),
            Some("intl:smhi:angelholm"),
            "intl pins persist with case intact"
        );

        // Fresh session: the pin comes back through sync_extra_panes.
        let mut restarted = test_viewer_app_with_hazards(Vec::new());
        restarted.sites = vec![RadarSite::new("KTLX"), RadarSite::new("KEAX")];
        restarted.app_settings.independent_panels = true;
        restarted.app_settings.extra_pane_pins =
            std::collections::BTreeMap::from([(0, "intl:smhi:angelholm".to_owned())]);
        restarted.grid_layout = PanelLayout::TwoVertical;
        restarted.sync_extra_panes();
        assert_eq!(
            restarted.extra_panes[0].pin,
            Some(SiteRef::Intl {
                provider_id: "smhi".to_owned(),
                site_id: "angelholm".to_owned(),
            }),
            "the intl pane pin restores on restart"
        );

        // Bare legacy ids restore as US refs forever.
        let mut legacy = test_viewer_app_with_hazards(Vec::new());
        legacy.sites = vec![RadarSite::new("KTLX"), RadarSite::new("KEAX")];
        legacy.app_settings.independent_panels = true;
        legacy.app_settings.extra_pane_pins =
            std::collections::BTreeMap::from([(0, "keax".to_owned())]);
        legacy.grid_layout = PanelLayout::TwoVertical;
        legacy.sync_extra_panes();
        assert_eq!(
            legacy.extra_panes[0].pin,
            Some(SiteRef::Us {
                level2_id: "KEAX".to_owned(),
            }),
            "bare ids restore as (uppercased) US pins"
        );

        // Releasing the pane back to Follow-primary removes the entry.
        app.clear_extra_pane_radar(0);
        app.remember_extra_pane_pin(0);
        assert!(!app.app_settings.extra_pane_pins.contains_key(&0));
    }

    #[test]
    fn archive_primary_hands_panes_a_paused_live_flag() {
        let mut app = test_viewer_app_with_hazards(Vec::new());
        app.sites = vec![RadarSite::new("KTLX")];
        app.selected_site_index = 0;
        // Archive/event loads clear the primary auto-refresh flag; panes
        // initialized from that display inherit the pause so the live poll
        // can never clobber archive browsing.
        app.primary.live.enabled = false;
        app.volume = Some(Arc::new(RadarVolume::new(
            radar_core::RadarSite::new("KTLX"),
            Utc.with_ymd_and_hms(2013, 5, 20, 20, 0, 0).unwrap(),
        )));
        app.extra_panes
            .push(test_pane(DisplayProduct::Moment(MomentType::Reflectivity)));
        app.initialize_extra_pane_from_primary(0);
        assert!(!app.extra_panes[0].engine.live.enabled);
        assert_eq!(
            app.extra_pane_live_action(0, Instant::now()),
            LiveAction::Skip
        );

        // A live primary hands panes a live flag — users expect every
        // independent pane to keep updating.
        app.primary.live.enabled = true;
        app.initialize_extra_pane_from_primary(0);
        assert!(app.extra_panes[0].engine.live.enabled);
    }

    #[test]
    fn same_site_pane_follows_primary_volume_and_trims_history() {
        fn ktlx_live_frame(minutes_ago: i64) -> FrameHistoryEntry {
            let volume = Arc::new(RadarVolume::new(
                radar_core::RadarSite::new("KTLX"),
                Utc::now() - chrono::Duration::minutes(minutes_ago),
            ));
            FrameHistoryEntry {
                identity: frame_identity_for_volume(volume.as_ref()),
                path: PathBuf::from(format!("chunks-ktlx-{minutes_ago}")),
                volume,
                timings: None,
                status: FrameStatus::LiveComplete,
                source_label: "realtime L2 KTLX".to_owned(),
            }
        }

        let mut app = test_viewer_app_with_hazards(Vec::new());
        let ctx = egui::Context::default();
        app.sites = vec![RadarSite::new("KTLX")];
        app.selected_site_index = 0;
        app.primary.live.enabled = true;
        app.primary.limits.frame_limit = 3;
        app.primary.history.push(ktlx_live_frame(20));
        app.extra_panes
            .push(test_pane(DisplayProduct::Moment(MomentType::Reflectivity)));
        app.extra_panes[0].pin = Some(SiteRef::Us {
            level2_id: "KTLX".to_owned(),
        });

        app.maybe_refresh_extra_panes(&ctx);
        // The pane holds the PRIMARY's decode (same Arc): one download and
        // one decode feed both panes.
        assert_eq!(app.extra_panes[0].engine.history.len(), 1);
        assert!(Arc::ptr_eq(
            &app.extra_panes[0].engine.history[0].volume,
            &app.primary.history[0].volume
        ));
        assert!(
            app.extra_panes[0].load_receiver.is_none(),
            "no worker spawned"
        );

        // An unchanged primary volume is not re-installed every tick.
        app.extra_panes[0].engine.status = "sentinel".to_owned();
        app.maybe_refresh_extra_panes(&ctx);
        assert_eq!(app.extra_panes[0].engine.status, "sentinel");

        // Each new primary install propagates within a tick, and the pane
        // history trim applies on this install path too.
        for minutes_ago in [15, 10, 5] {
            app.primary.history.push(ktlx_live_frame(minutes_ago));
            app.maybe_refresh_extra_panes(&ctx);
        }
        assert_eq!(app.primary.history.len(), 4);
        assert_eq!(
            app.extra_panes[0].engine.history.len(),
            3,
            "trimmed to limit"
        );
        let newest_primary = &app.primary.history.last().expect("primary frames").volume;
        assert!(Arc::ptr_eq(
            app.extra_panes[0].volume.as_ref().expect("pane volume"),
            newest_primary
        ));

        // A pane with its Live checkbox off stays untouched.
        app.extra_panes[0].engine.live.enabled = false;
        app.extra_panes[0].engine.status = "paused".to_owned();
        app.primary.history.push(ktlx_live_frame(1));
        app.maybe_refresh_extra_panes(&ctx);
        assert_eq!(app.extra_panes[0].engine.status, "paused");
        assert_eq!(app.extra_panes[0].engine.history.len(), 3);
    }

    #[test]
    fn radar_age_glyph_arc_sweep_uses_red_threshold_and_clamps() {
        let now = Utc.with_ymd_and_hms(2026, 6, 7, 23, 0, 0).unwrap();
        let style = styles::RadarAgeStyle {
            red_seconds: 120,
            ..styles::RadarAgeStyle::default()
        };

        assert_eq!(radar_age_glyph_arc_sweep_fraction(now, now, &style), 0.0);
        assert_eq!(
            radar_age_glyph_arc_sweep_fraction(now + chrono::Duration::seconds(30), now, &style),
            0.0
        );
        assert!(
            (radar_age_glyph_arc_sweep_fraction(now - chrono::Duration::seconds(60), now, &style)
                - 0.5)
                .abs()
                < 0.001
        );
        assert_eq!(
            radar_age_glyph_arc_sweep_fraction(now - chrono::Duration::seconds(180), now, &style),
            1.0
        );
    }

    #[test]
    fn radar_age_glyph_arc_points_start_at_noon_and_sweep_clockwise() {
        let now = Utc.with_ymd_and_hms(2026, 6, 7, 23, 0, 0).unwrap();
        let center = egui::pos2(20.0, 30.0);
        let style = styles::RadarAgeStyle {
            red_seconds: 100,
            glyph_arc_radius_px: 10.0,
            ..styles::RadarAgeStyle::default()
        };

        let points =
            radar_age_glyph_arc_points(center, now - chrono::Duration::seconds(50), now, &style);
        let first = points.first().expect("arc starts");
        let last = points.last().expect("arc ends");

        assert!((first.x - 20.0).abs() < 0.001);
        assert!((first.y - 20.0).abs() < 0.001);
        assert!((last.x - 20.0).abs() < 0.001);
        assert!((last.y - 40.0).abs() < 0.001);
        assert!(
            radar_age_glyph_arc_points(center, now, now, &style).is_empty(),
            "zero-age scan draws no arc"
        );
    }

    /// Golden parity: the GLM ramp through the style registry is
    /// bit-identical to the legacy hard-coded `flash_color`.
    #[test]
    fn glm_flash_color_pins_legacy_ramp() {
        let style = styles::GlmStyle::default();
        assert_eq!(
            glm_layer::flash_color(0.0, &style),
            egui::Color32::from_rgba_unmultiplied(255, 235, 120, 235)
        );
        assert_eq!(
            glm_layer::flash_color(1.0, &style),
            egui::Color32::from_rgba_unmultiplied(255, 75, 10, 85)
        );
        // Mid-ramp matches the legacy formula (truncating casts).
        for age in [0.1_f32, 0.25, 0.5, 0.75, 0.9] {
            let legacy = egui::Color32::from_rgba_unmultiplied(
                255,
                (235.0 - 160.0 * age) as u8,
                (120.0 - 110.0 * age) as u8,
                (235.0 - 150.0 * age) as u8,
            );
            assert_eq!(glm_layer::flash_color(age, &style), legacy, "age {age}");
        }
    }

