            test_storm_track(6, scan_time + chrono::Duration::minutes(2), 2.0, 1.0, None);
        future.max_dbz = 70.0;
        let mut merged = test_storm_track(7, scan_time, 4.0, 1.0, None);
        merged.max_dbz = 80.0;
        merged.merged_into = Some(5);
