    #[test]
    fn vol3d_velocity_defaults_use_symmetric_magnitude_threshold() {
        let app = test_viewer_app_with_hazards(Vec::new());
        let product = DisplayProduct::Moment(MomentType::Velocity);
        let (value_min, value_max) = app.vol3d_product_value_range(&product);

        let defaults = ViewerApp::vol3d_product_defaults(&product, value_min, value_max);
        let (low, high) = ViewerApp::vol3d_shader_threshold_bounds(
            defaults.threshold_mode,
            defaults.threshold,
            value_min,
            value_max,
        );
        let zero = ViewerApp::normalized_vol3d_value(0.0, value_min, value_max);

        assert_eq!(defaults.threshold_mode, vol3d::Vol3dThresholdMode::Outside);
        assert!(defaults.threshold > 0.0);
        assert!(low < zero && zero < high);
        assert!(defaults.opacity < 0.35);
        assert!(defaults.density < 0.8);
    }

    #[test]
    fn vol3d_correlation_coefficient_defaults_render_low_values() {
        let app = test_viewer_app_with_hazards(Vec::new());
        let product = DisplayProduct::Moment(MomentType::CorrelationCoefficient);
        let (value_min, value_max) = app.vol3d_product_value_range(&product);

        let defaults = ViewerApp::vol3d_product_defaults(&product, value_min, value_max);
        let (threshold, high) = ViewerApp::vol3d_shader_threshold_bounds(
            defaults.threshold_mode,
            defaults.threshold,
            value_min,
            value_max,
        );

        assert_eq!(defaults.threshold_mode, vol3d::Vol3dThresholdMode::Below);
        assert!((0.80..=0.98).contains(&defaults.threshold));
        assert!(threshold > 0.0 && threshold < 1.0);
        assert!(high < 0.0);
        assert_eq!(defaults.quality, vol3d::Vol3dQuality::High);
    }

    #[test]
    fn vol3d_uses_complete_same_site_volume_instead_of_live_partial() {
        let mut app = test_viewer_app_with_hazards(Vec::new());
        let scan_time = Utc.with_ymd_and_hms(2026, 6, 23, 4, 10, 0).unwrap();
        let mut complete =
            test_reflectivity_sails_volume_with_radials(&[(0.5, 0), (1.5, 60_000)], 720);
        complete.site.id = "KTLX".to_owned();
        complete.volume_time = scan_time;
        let complete = Arc::new(complete);
        let mut partial = test_reflectivity_sails_volume_with_radials(&[(0.5, 0)], 720);
        partial.site.id = "KTLX".to_owned();
        partial.volume_time = scan_time + chrono::Duration::minutes(3);
        let partial = Arc::new(partial);
        app.primary.history.push(FrameHistoryEntry {
            identity: frame_identity_for_volume(complete.as_ref()),
            path: PathBuf::from("KTLX-complete"),
            volume: Arc::clone(&complete),
            timings: None,
            status: FrameStatus::LiveComplete,
            source_label: "test".to_owned(),
        });
        app.primary.history.push(FrameHistoryEntry {
            identity: frame_identity_for_volume(partial.as_ref()),
            path: PathBuf::from("KTLX-partial"),
            volume: Arc::clone(&partial),
            timings: None,
            status: FrameStatus::LivePartial,
            source_label: "test".to_owned(),
        });
        app.primary.cursor.index = 1;
        app.volume = Some(Arc::clone(&partial));

        let source = app
            .vol3d_complete_source_volume_for(Arc::clone(&partial), &MomentType::Reflectivity)
            .expect("same-site complete fallback");
        assert!(Arc::ptr_eq(&source, &complete));

        app.primary.cursor.index = 0;
        let source = app
            .vol3d_complete_source_volume_for(Arc::clone(&partial), &MomentType::Reflectivity)
            .expect("same-site complete fallback even if selection lags");
        assert!(Arc::ptr_eq(&source, &complete));
        app.primary.cursor.index = 1;

        let mut other_site =
            test_reflectivity_sails_volume_with_radials(&[(0.5, 0), (1.5, 60_000)], 720);
        other_site.site.id = "KFDR".to_owned();
        other_site.volume_time = scan_time;
        let other_site = Arc::new(other_site);
        app.primary.history[0] = FrameHistoryEntry {
            identity: frame_identity_for_volume(other_site.as_ref()),
            path: PathBuf::from("KFDR-complete"),
            volume: other_site,
            timings: None,
            status: FrameStatus::LiveComplete,
            source_label: "test".to_owned(),
        };
        assert!(
            app.vol3d_complete_source_volume_for(Arc::clone(&partial), &MomentType::Reflectivity)
                .is_none(),
            "3D should wait instead of borrowing a previous radar's volume"
        );
    }

