    /// The synthetic-loop -> Live freeze fix: the reaper releases a drained
    /// frame's `Arc<RadarVolume>` on its worker thread (not the caller), and
    /// an empty reap spawns nothing.
    #[test]
    fn loop_history_reaper_releases_frames_off_thread() {
        let volume = Arc::new(RadarVolume::new(
            radar_core::RadarSite::new("WRF"),
            chrono::Utc::now(),
        ));
        let weak = Arc::downgrade(&volume);
        let entry = frame_history_entry_from_decoded(DecodedLoad {
            path: std::path::PathBuf::from("synthetic-frame"),
            volume,
            timings: LoadTimings::default(),
            status: FrameStatus::Local,
            source_label: "simulated WRF".to_owned(),
        });
        // The drained entry now holds the only strong reference.
        assert_eq!(weak.strong_count(), 1);

        let handle = spawn_loop_history_reaper(vec![entry], VecDeque::new())
            .expect("a non-empty reap spawns a worker");
        handle.join().expect("reaper thread joins");
        assert!(
            weak.upgrade().is_none(),
            "the reaper thread dropped the last frame Arc, off the UI thread"
        );

        assert!(
            spawn_loop_history_reaper(Vec::new(), VecDeque::new()).is_none(),
            "an empty reap is a no-op (no thread)"
        );
    }

    #[test]
    fn cache_capacity_scales_with_pane_count() {
        // A quad grid cycles 4 distinct (product, cut) keys through the one
        // shared worker; capacities below 4 would evict another pane's caches
        // on every render. Single-pane stays at the thread-based size.
        let mut policy = test_cache_policy(12); // thread-based capacity 3
        assert_eq!(policy.sample_cache_capacity(), 3);
        policy.note_pane(3); // pane id 3 => 4 panes in use
        assert_eq!(policy.sample_cache_capacity(), 4);
        assert_eq!(policy.moment_cache_capacity(), 4);
        policy.note_pane(99); // capped at the 4-pane grid maximum
        assert_eq!(policy.sample_cache_capacity(), 4);
        // Overlay workers are unaffected.
        let mut overlay = test_overlay_cache_policy(12);
        overlay.note_pane(3);
        assert_eq!(overlay.sample_cache_capacity(), 1);
    }

    #[test]
    fn note_lane_maps_lanes_onto_the_legacy_pane_floor() {
        // Pane(n) grows the multi-pane cache floor exactly like the legacy
        // nonzero pane id n; Primary/Overlay/Prewarm are legacy pane 0 (the
        // floor stays at the single-pane minimum).
        let mut policy = test_cache_policy(12);
        policy.note_lane(LaneId::Primary);
        policy.note_lane(LaneId::Overlay(7));
        policy.note_lane(LaneId::Prewarm);
        assert_eq!(policy.min_entries, 1);
        policy.note_lane(LaneId::Pane(3));
        assert_eq!(policy.min_entries, 4);
    }

